ST.xhtml:
// === IMPLEMENTATION ===

{region "§1 Repli image reelle banc desactive"}
IF NOT Enable THEN
    // 🔌 Banc désactivé : repli sur l'image réelle, aucune simulation en cours
    KoboldMeasureEnablePrevious := FALSE;
    KoboldAutoEpisodeActive := FALSE;
    instKoboldPowerUpTimer(IN := FALSE);
    Ready       := FALSE;
    Busy        := FALSE;
    Done        := FALSE;
    Winch       := HwReal.Winch;
    Translation := HwReal.Translation;
    Operator    := HwReal.Operator;
    Machine     := HwReal.Machine;
    instSimJoystick(Enable := FALSE);
    RETURN;
END_IF;

// ▶️ Banc actif : le cycle de simulation démarre pour ce scan.
// 🔒 Le comptage brut M1/M2 (`_SimEncoderRawPosM1`/`M2`, GVL_PERSISTENT) n'est JAMAIS réécrit ici :
//    `FB_Sim_Encoder` en reste le producteur unique (accumulation signée / preset). L'origine de banc
//    plausible vient de l'initialisation DÉCLARÉE `GVL_PERSISTENT` (1 000 000 pts), pas d'une
//    réinjection conditionnelle : un 0 lu ici n'est PAS une mémoire vierge, c'est un point de passage
//    légitime du compteur SIGNÉ. Le banc ne réécrit donc aucune mémoire codeur, pas même pour
//    « initialiser » une valeur lue à 0 — une telle réinjection (1 100 000 pts = 268,55 m de position
//    publiée en un seul scan, sans mouvement ni défaut et référence de homing conservée)
//    transformerait un zéro réel en téléportation de position.
Ready := TRUE;
Busy  := TRUE;
Done  := FALSE;


{endregion}

{region "§2 Simulation treuils M1/M2"}
// ── 1. MODÈLE TREUILS (M1 + M2) ─────────────────────────────────────────────
// Presets codeurs : déclenchés si PresetTriggerCmd = 2
M1_PresetCmd := (M1_PresetTriggerCmd = 2);
M2_PresetCmd := (M2_PresetTriggerCmd = 2);
WinchSpeedReportTauEffectiveS := SEL(SimWinchDynamicsActive, 0.0, SimWinchSpeedReportTauS);
WinchBrakeOpenDelayEffectiveS := SEL(SimWinchDynamicsActive, 0.0, SimWinchBrakeOpenDelayS);
WinchBrakeCloseDelayEffectiveS := SEL(SimWinchDynamicsActive, 0.0, SimWinchBrakeCloseDelayS);

// Conversions d'injection d'écart synchro (0.5m -> points codeur avec 8192 pts/tour, 2m/tour)
// 1m = 4096 points codeur.
M1_OffsetPts := REAL_TO_DINT(SimSyncDeviationOffset_M * 4096.0);
M2_OffsetPts := REAL_TO_DINT(SimSyncDeviationOffset_M * 4096.0);

// Une plongée auto fige ses réglages avant l'arrêt : modifier l'IHM pendant AX5..AX8
// ne crée ni faux front fond ni changement de roulis en cours de mouvement.
IF KoboldMeasureEnable AND NOT KoboldMeasureEnablePrevious THEN
    KoboldAutoEpisodeActive := SimKoboldAutoModeActive;
    KoboldAutoDepthEpisode_M := SimKoboldAutoDepth_M;
    KoboldPowerUpEpisodeTime := SimKoboldPowerUpTime;
END_IF;
KoboldMeasureEnablePrevious := KoboldMeasureEnable;

// Instance modèle codeur M1
instSimEncoderM1(
    Enable           := TRUE,
    RelayFwd         := M1_RelayFwd,
    RelayRev         := M1_RelayRev,
    StepNumber       := M1_StepNumber,
    PresetCmd        := M1_PresetCmd,
    PresetValue      := M1_PresetValueOut,
    SpeedScaleFactor := SimEncoderSpeedFactor,
    CoastDistanceM   := SimWinchCoast_M,
    SpeedReportTauS  := WinchSpeedReportTauEffectiveS,
    TestOffsetCmd    := SimSyncDeviationInjectM1,
    TestOffsetPts    := M1_OffsetPts,
    RawPos           := RawPosM1
);

// T317 exploratoire -- electrique+charge+couplage M1/M2, diagnostic seul (Winch.* metier deja
// consomme via M2_TensionedCable_DI ci-dessous). Couplage/charge cables sur stimuli de banc en
// attente des signaux reels amont (CoupledBoth, benne au sol) -- cf. registre PLAN_T317.
instWinchElectricalM1(
    Enable                := Enable AND SimWinchElectricalDiagnosticsActive,
    StepCmd               := MAX(1, M1_StepNumber),
    DirectionCmd          := SEL(M1_RelayRev, 1, -1),
    NetworkVoltageAct_V   := 400.0,
    LoadFrac_Ratio         := SEL(SimBucketJamActive, SimWinchLoadFrac_Ratio, CST_SimBucketJamLoadFrac_Ratio),
    IsBucketGrounded      := KoboldBottomTouchPrev_DI,
    IsCoupledToPeer        := SimWinchCoupledActive,
    PeerTorque_Nm          := PeerTorqueM2Prev_Nm,
    PeerSpeed_Rpm          := PeerSpeedM2Prev_Rpm
);
IF SimWinchElectricalDiagnosticsActive THEN
    MotorTorqueM1_Nm := instWinchElectricalM1.MotorTorque_Nm;
    MotorIsStalledM1 := instWinchElectricalM1.IsStalled;
    PeerTorqueM1Prev_Nm := instWinchElectricalM1.MotorTorque_Nm;
    PeerSpeedM1Prev_Rpm := instWinchElectricalM1.SpeedAct_Rpm;
ELSE
    MotorTorqueM1_Nm := 0.0;
    MotorIsStalledM1 := FALSE;
    PeerTorqueM1Prev_Nm := 0.0;
    PeerSpeedM1Prev_Rpm := 0.0;
END_IF;

instWinchElectricalM2(
    Enable                := Enable AND SimWinchElectricalDiagnosticsActive,
    StepCmd               := MAX(1, M2_StepNumber),
    DirectionCmd          := SEL(M2_RelayRev, 1, -1),
    NetworkVoltageAct_V   := 400.0,
    LoadFrac_Ratio         := SEL(SimBucketJamActive, SimWinchLoadFrac_Ratio, CST_SimBucketJamLoadFrac_Ratio),
    IsBucketGrounded      := KoboldBottomTouchPrev_DI,
    IsCoupledToPeer        := SimWinchCoupledActive,
    PeerTorque_Nm          := PeerTorqueM1Prev_Nm,
    PeerSpeed_Rpm          := PeerSpeedM1Prev_Rpm
);
IF SimWinchElectricalDiagnosticsActive THEN
    MotorTorqueM2_Nm := instWinchElectricalM2.MotorTorque_Nm;
    MotorIsStalledM2 := instWinchElectricalM2.IsStalled;
    PeerTorqueM2Prev_Nm := instWinchElectricalM2.MotorTorque_Nm;
    PeerSpeedM2Prev_Rpm := instWinchElectricalM2.SpeedAct_Rpm;
ELSE
    MotorTorqueM2_Nm := 0.0;
    MotorIsStalledM2 := FALSE;
    PeerTorqueM2Prev_Nm := 0.0;
    PeerSpeedM2Prev_Rpm := 0.0;
END_IF;

// Détection coupure relais M2 pour renouveler la dispersion pseudo-aléatoire (±0.1m)
IF (M2_RelayFwdPrev AND NOT M2_RelayFwd) OR (M2_RelayRevPrev AND NOT M2_RelayRev) THEN
    // Générateur LCG 32-bit standard : X_{n+1} = (1103515245 * X_n + 12345) MOD 2^31
    RandomSeed := (RandomSeed * 1103515245 + 12345) AND 16#7FFFFFFF;
    // Dispersion pseudo-aléatoire entre -0.10 m et +0.10 m
    M2_EffectiveCoastM := SimWinchCoast_M + (UDINT_TO_REAL(RandomSeed MOD 2000) / 10000.0) - 0.10;
END_IF;
M2_RelayFwdPrev := M2_RelayFwd;
M2_RelayRevPrev := M2_RelayRev;

// Le FB codeur reste l'unique producteur de RawPosM2. Le ralentissement mesuré
// agit uniquement sur sa dynamique pendant une descente BOTH effectivement appliquée.
M2CoupledDescentActive := SimM2CoupledDescentModelActive
                          AND WinchBothDescentIntent
                          AND M1_RelayRev AND M2_RelayRev
                          AND NOT M1_RelayFwd AND NOT M2_RelayFwd;
M2EffectiveSpeedScaleFactor := SimEncoderSpeedFactor;
IF M2CoupledDescentActive THEN
    M2EffectiveSpeedScaleFactor := SimEncoderSpeedFactor * MAX(0.0, SimM2CoupledDescentFactor);
END_IF;

// P02 consomme la mesure publiée au scan précédent. Reconstituer le déplacement
// de ce scan évite un trou d'un cycle lors du seuil d'arrêt de FB_Bucket.
M2ExpectedStepDistance_M := (1.0 + (INT_TO_REAL(MAX(M2_StepNumber, 1)) - 1.0) * 0.25)
                            * MAX(0.0, SimEncoderSpeedFactor)
                            * CST_SimBenchCycleTimeS;
M2OpenStopThreshold_M := BucketOffsetOpen_M + MAX(0.0, BucketOpenAnticipation_M)
                         + M2ExpectedStepDistance_M;

// Armer le roulis long uniquement à l'approche du seuil d'ouverture AX15B.
// Un jog manuel, un homing ou un arrêt ailleurs garde le roulis historique.
IF NOT M2_RelayRev OR M2_RelayFwd THEN
    M2AutoOpenCoastArmed := FALSE;
ELSIF SimWinchCouplingModelActive AND BucketAx15bOpenActive
      AND NOT M1_RelayFwd AND NOT M1_RelayRev
      AND (M2_CablePos_M - M1_CablePos_M)
          <= M2OpenStopThreshold_M THEN
    M2AutoOpenCoastArmed := TRUE;
END_IF;

// À l'arrêt anticipé automatique, le roulis couvre seulement l'écart restant
// jusqu'à la butée ouverte : il ne sur-ouvre pas et ne modifie pas le jog manuel.
M2EffectiveCoastDistance_M := M2_EffectiveCoastM;
IF M2AutoOpenCoastArmed THEN
    M2OpenDistanceRemaining_M := MAX(0.0, M2_CablePos_M - M1_CablePos_M
                                          - BucketOffsetOpen_M - M2ExpectedStepDistance_M);
    M2EffectiveCoastDistance_M := MIN(MAX(0.0, BucketOpenAnticipation_M),
                                      M2OpenDistanceRemaining_M);
END_IF;

// Instance modèle codeur M2 (avec roulis et dispersion)
instSimEncoderM2(
    Enable           := TRUE,
    RelayFwd         := M2_RelayFwd,
    RelayRev         := M2_RelayRev,
    StepNumber       := M2_StepNumber,
    PresetCmd        := M2_PresetCmd,
    PresetValue      := M2_PresetValueOut,
    SpeedScaleFactor := M2EffectiveSpeedScaleFactor,
    CoastDistanceM   := M2EffectiveCoastDistance_M,
    SpeedReportTauS  := WinchSpeedReportTauEffectiveS,
    TestOffsetCmd    := SimSyncDeviationInjectM2,
    TestOffsetPts    := M2_OffsetPts,
    RawPos           := RawPosM2
);

// L'épisode Kobold ne produit que la DI. Le cycle commande l'arrêt ; les FB codeurs
// conservent leur roulis historique après la retombée des relais.
IF NOT KoboldMeasureEnable AND NOT M1_RelayRev AND NOT M2_RelayRev
   AND NOT M1_RelayFwd AND NOT M2_RelayFwd THEN
    KoboldAutoEpisodeActive := FALSE;
END_IF;

// Recopie structures Winch simulées :
// 🛑 POLARITÉ DE FREIN SIMULÉ : 1 = contacteur commandé = frein OUVERT.
// Câblage réel : DI = 1 ⟺ frein OUVERT. Le modèle produit donc M1_BrakeIsOpen_DI := M1_BrakeCmd !
// Delai electrique/meca opt-in : SimWinchBrakeOpenDelayS/CloseDelayS=0.0 -> bascule le
// meme scan (comportement historique inchange, TC-P13-012). >0 -> retour retarde, sans jamais
// inverser la polarite (M1_BrakeIsOpenState suit toujours M1_BrakeCmd, juste avec latence).
IF M1_BrakeCmd THEN
    IF NOT M1_BrakeIsOpenState THEN
        M1_BrakeOpenTimerS := M1_BrakeOpenTimerS + CST_SimBenchCycleTimeS;
        IF M1_BrakeOpenTimerS >= MAX(0.0, WinchBrakeOpenDelayEffectiveS) THEN
            M1_BrakeIsOpenState := TRUE;
            M1_BrakeOpenTimerS := 0.0;
        END_IF;
    END_IF;
    M1_BrakeCloseTimerS := 0.0;
ELSE
    IF M1_BrakeIsOpenState THEN
        M1_BrakeCloseTimerS := M1_BrakeCloseTimerS + CST_SimBenchCycleTimeS;
        IF M1_BrakeCloseTimerS >= MAX(0.0, WinchBrakeCloseDelayEffectiveS) THEN
            M1_BrakeIsOpenState := FALSE;
            M1_BrakeCloseTimerS := 0.0;
        END_IF;
    END_IF;
    M1_BrakeOpenTimerS := 0.0;
END_IF;
Winch.M1_BrakeIsOpen_DI        := M1_BrakeIsOpenState;
// Retour UNIQUE « tous contacteurs retombés » = sens ET vitesse.
// Omettre les paliers ferait croire à l'arrêt pendant les transitoires → Méca A armée à tort.
Winch.M1_ContactorsReleased_DI := NOT (M1_RelayFwd OR M1_RelayRev
                                    OR M1_SpeedContactor_1 OR M1_SpeedContactor_2
                                    OR M1_SpeedContactor_3 OR M1_SpeedContactor_4);
Winch.M1_ThermalOk_DI          := TRUE; // Sauf panne simulée

IF M2_BrakeCmd THEN
    IF NOT M2_BrakeIsOpenState THEN
        M2_BrakeOpenTimerS := M2_BrakeOpenTimerS + CST_SimBenchCycleTimeS;
        IF M2_BrakeOpenTimerS >= MAX(0.0, WinchBrakeOpenDelayEffectiveS) THEN
            M2_BrakeIsOpenState := TRUE;
            M2_BrakeOpenTimerS := 0.0;
        END_IF;
    END_IF;
    M2_BrakeCloseTimerS := 0.0;
ELSE
    IF M2_BrakeIsOpenState THEN
        M2_BrakeCloseTimerS := M2_BrakeCloseTimerS + CST_SimBenchCycleTimeS;
        IF M2_BrakeCloseTimerS >= MAX(0.0, WinchBrakeCloseDelayEffectiveS) THEN
            M2_BrakeIsOpenState := FALSE;
            M2_BrakeCloseTimerS := 0.0;
        END_IF;
    END_IF;
    M2_BrakeOpenTimerS := 0.0;
END_IF;
Winch.M2_BrakeIsOpen_DI        := M2_BrakeIsOpenState;
Winch.M2_ContactorsReleased_DI := NOT (M2_RelayFwd OR M2_RelayRev
                                    OR M2_SpeedContactor_1 OR M2_SpeedContactor_2
                                    OR M2_SpeedContactor_3 OR M2_SpeedContactor_4);
Winch.M2_ThermalOk_DI          := TRUE;

// Cohérent avec M2_TensionedCable_DI (sain par défaut) : capteur TOP libre en simu,
// sauf stimulus manuel SimTopPositionActive (injection de fait capteur au banc).
Winch.M1M2_TopPositionFree_DI  := NOT SimTopPositionActive;
// Le Kobold ne deduit pas l'etat cable : seul le stimulus safety explicite injecte une panne.
Winch.M2_TensionedCable_DI     := NOT SimM2TensionedCableFaultInject;

Winch.COD1_PosValue            := instSimEncoderM1.RawPosOut;
Winch.COD1_SpdValue            := instSimEncoderM1.RawSpdOut;
Winch.COD1_Alarms              := 0;
Winch.COD1_Warnings            := 0;
Winch.COD1_DeviceState         := DEVICE_STATE.RUNNING; // État device RUNNING (bus OK)

Winch.COD2_PosValue            := instSimEncoderM2.RawPosOut;
Winch.COD2_SpdValue            := instSimEncoderM2.RawSpdOut;
Winch.COD2_Alarms              := 0;
Winch.COD2_Warnings            := 0;
Winch.COD2_DeviceState         := DEVICE_STATE.RUNNING; // État device RUNNING

{region "§2bis Rattrapage mecanique M1/M2"}
// La benne relie mecaniquement les deux treuils. En MONTEE couplee et sans blocage, le jeu relatif
// est repris : Delta = PosM2 - PosM1 rejoint la BUTEE mecanique benne FERMEE (OffsetCloseM).
// Sans ce rattrapage, un ecart residuel (trou metier de fermeture : coupure d'anticipation a 13,8 m
// alors que l'etat ferme exige 14,0 m) laisse la benne "non fermee" et plafonne la montee au palier 1.
// 🔒 Le modele n'ecrit QUE l'image publiee (Winch.COD2_PosValue) -- JAMAIS RawPosM2, memoire
//    persistante du codeur dont FB_Sim_Encoder reste l'unique producteur.
// 🔒 MONTEE UNIQUEMENT : la descente couplee reste au modele existant SimM2CoupledDescentModelActive
//    (exclusion mutuelle : les deux modeles ne s'appliquent jamais ensemble).
// 🔒 Cible = BUTEE MECANIQUE benne fermee (BucketOffsetCloseM) : seule valeur qui fasse converger
//    l'ouverture benne vers 0 % ; une cible intermediaire laisse un ecart plancher jamais
//    corrigible. Le sens unique (correction seulement si Delta < cible) et le bornage de pente
//    (LIMIT + MIN(cible - Delta)) interdisent tout depassement de butee.
WinchCouplingBothSameDir := (M1_RelayFwd AND M2_RelayFwd) OR (M1_RelayRev AND M2_RelayRev);
WinchCouplingGate := SimWinchCouplingModelActive
                     AND WinchCouplingBothSameDir
                     AND M1_RelayFwd AND NOT M1_RelayRev        // montee uniquement
                     AND M1_BrakeIsOpenState AND M2_BrakeIsOpenState
                     AND Winch.M2_TensionedCable_DI            // cable tendu : sinon aucun effort transmis
                     AND NOT KoboldBottomTouchPrev_DI          // benne au fond : aucun mouvement reel
                     AND NOT (M1_PresetCmd OR M2_PresetCmd)    // jamais pendant un preset/homing
                     AND NOT SimBucketJamActive;               // mâchoires bloquees : aucun rattrapage
WinchCouplingActive := WinchCouplingGate;
WinchCouplingCorrectionPts := 0;
IF WinchCouplingGate THEN
    WinchCouplingDelta_M := M2_CablePos_M - M1_CablePos_M;
    // Cible = butee mecanique benne FERMEE (ecart relatif 0 %). Le sens unique et le bornage
    // de pente garantissent qu'aucune correction ne depasse cette butee.
    WinchCouplingTarget_M := BucketOffsetCloseM;
    IF WinchCouplingDelta_M < WinchCouplingTarget_M THEN
        WinchCouplingCorrection_M := (WinchCouplingTarget_M - WinchCouplingDelta_M)
                                     * CST_SimBenchCycleTimeS
                                     / (CST_SimWinchCouplingTauS + CST_SimBenchCycleTimeS);
        // Sens unique + bornage (§6) : jamais de saut, jamais au-dela de la cible
        WinchCouplingCorrection_M := LIMIT(0.0, WinchCouplingCorrection_M,
                                           MIN(CST_SimWinchCouplingStepMax_M,
                                               WinchCouplingTarget_M - WinchCouplingDelta_M));
        WinchCouplingCorrectionDInt := REAL_TO_DINT(WinchCouplingCorrection_M
                                                    * CST_SimWinchCouplingPtsPerM);
        IF WinchCouplingCorrectionDInt > 0 THEN
            WinchCouplingAccumPts := WinchCouplingAccumPts + WinchCouplingCorrectionDInt;
            WinchCouplingCorrectionPts := WinchCouplingCorrectionDInt;
        END_IF;
    END_IF;
ELSIF M2_RelayRev AND NOT M2_RelayFwd THEN
    // Ouverture commandee : la reprise de jeu est relachee (le cable de fermeture devide),
    // sinon l'image M2 masquerait l'ouverture reelle.
    WinchCouplingCorrectionDInt := REAL_TO_DINT(CST_SimWinchCouplingStepMax_M
                                                * CST_SimWinchCouplingPtsPerM);
    WinchCouplingAccumPts := MAX(0, WinchCouplingAccumPts - WinchCouplingCorrectionDInt);
END_IF;
// Un preset/homing rend la reference absolue : l'offset de reprise de jeu n'a plus de sens.
IF M1_PresetCmd OR M2_PresetCmd THEN
    WinchCouplingAccumPts := 0;
END_IF;
// Report sur l'IMAGE uniquement (le raw persistant n'est jamais touche), et seulement quand le
// modele est actif : en mode desactive, l'image reste strictement celle du codeur.
IF SimWinchCouplingModelActive AND (WinchCouplingAccumPts > 0) THEN
    Winch.COD2_PosValue := Winch.COD2_PosValue + DINT_TO_UDINT(WinchCouplingAccumPts);
END_IF;
{endregion}


{endregion}

{region "§3 Simulation translation M3"}
// ── 2. MODÈLE TRANSLATION M3 (AC600) ─────────────────────────────────────────
M3_RelayFwd := M3_ReqTremie AND NOT M3_ReqMaintenance;
M3_RelayRev := M3_ReqMaintenance AND NOT M3_ReqTremie;

instSimTranslation(
    Enable          := TRUE,
    ReqTremie       := M3_RelayFwd,
    ReqMaintenance  := M3_RelayRev,
    SpeedTgt_Pct    := M3_SpeedCmd_Pct,
    PosTremie_M        := M3_PosTremie_M,
    PosPV_M            := M3_PosPV_M,
    PosP2_M            := M3_PosP2_M,
    PosP1_M            := M3_PosP1_M,
    PosMaintenance_M   := M3_PosMaintenance_M,
    GainMetersPerHzSec := M3_OdometryGain,
    EndStopMargin_M    := SimM3EndStopMargin_M,
    MaxFreq_Hz      := CST_M3MaxFreq_Hz,
    SpeedFactor     := SimM3SpeedFactor,
    BrakeReleaseCmd := M3_BrakeCmd,
    SensorIntermittenceActive := SimM3SensorIntermittenceActive,
    SensorStabilizationS := SimM3SensorStabilizationS,
    SensorElectricalDelayS := SimM3SensorElectricalDelayS,
    SensorIntermittencePeriodS := SimM3SensorIntermittencePeriodS,
    SensorHysteresis_M := SimM3SensorHysteresis_M,
    SensorLoadAngleTriggerRad := SimM3SensorLoadAngleTriggerRad,
    SensorScenarioSeed := SimM3SensorScenarioSeed,
    SensorBlipTransitions := SimM3SensorBlipTransitions,
    SensorBlipDurationS := SimM3SensorBlipDurationS,
    BrakeFaultCloseWhileRunning := SimM3BrakeFaultCloseWhileRunning,
    BrakeFaultCloseDelay_S := SimM3BrakeFaultCloseDelayS,
    EndStopRecoilMax_M := SimM3EndStopRecoilMax_M,
    LoadReactionGain_Mps2 := SimM3LoadReactionGain_Mps2
);
M3BrakeFaultCloseActive := instSimTranslation.BrakeFaultCloseActive;
M3SensorBlipActive := instSimTranslation.SensorBlipActive;

// Remplissage capteurs de position M3 : l'override manuel conserve exactement le
// même ordre que FB_Translation_PositionDecoder (bit4=Trémie ... bit0=Maintenance).
IF SimM3SensorsWordOverrideActive THEN
    Translation.M3_PosTremie_DI      := SimM3SensorsWord.4;
    Translation.M3_PosPV_DI          := SimM3SensorsWord.3;
    Translation.M3_PosPVP2_DI        := SimM3SensorsWord.2;
    Translation.M3_PosP1_DI          := SimM3SensorsWord.1;
    Translation.M3_PosMaintenance_DI := SimM3SensorsWord.0;
ELSE
    Translation.M3_PosTremie_DI      := instSimTranslation.PosTremie;
    Translation.M3_PosPV_DI          := instSimTranslation.PosPV;
    Translation.M3_PosPVP2_DI        := instSimTranslation.PosP2;
    Translation.M3_PosP1_DI          := instSimTranslation.PosP1;
    Translation.M3_PosMaintenance_DI := instSimTranslation.PosMaintenance;
END_IF;

// Retour auxiliaire du frein, distinct de la commande electrique.
Translation.M3_BrakeIsOpen_DI    := instSimTranslation.BrakeContactOpen;

// Thermique moteur/variateur AC600 — pas de panne simulée, toujours OK (comme Winch.M1/M2_ThermalOk_DI)
Translation.M3_ThermalOK_DI      := TRUE;

// Simulation StatusWord AC600 : Bit 0 (Power Ready) = 1, Bit 7 (Comm Ready) = 1 -> 16#0087 en mouvement
// Bit0 retombe à l'arrêt, cohérent avec un variateur qui confirme l'arrêt sans rester "actif" —
// FB_Safety_Translation lit ce bit comme indicateur "mouvement non commandé" (Méca B, TonMecaB 3s) :
// un Bit0 forcé à 1 en continu à l'arrêt déclencherait un PowerCutOff simulé permanent après 3s.
// DrivePowerReady (diagnostic IHM seul, non consommé par un interlock) est le seul autre lecteur,
// aucune régression de mouvement possible.
IF instSimTranslation.ActualFrequency_Hz > 0.5 THEN
    M3_StatusWordSim := 16#0087; // + Operating/Running
ELSE
    M3_StatusWordSim := 16#0080; // Comm Ready seul -- Bit0 retombé, arrêt confirmé
END_IF;
M3_ActualFreqHz := REAL_TO_UINT(instSimTranslation.ActualFrequency_Hz * 100.0);

Translation.M3_StatusWord        := M3_StatusWordSim;
Translation.M3_ActualFrequencyHz := M3_ActualFreqHz;
Translation.AC600_DeviceState    := DEVICE_STATE.RUNNING; // État device RUNNING


{endregion}

{region "§4 Simulation operateur joystick"}
// ── 3. MODÈLE OPÉRATEUR / JOYSTICK ───────────────────────────────────────────
IF NOT OperatorSourceActive THEN
    // Le geste ne continue pas en arriere-plan lorsque le domaine est reel.
    instSimJoystick(Enable := FALSE);
    Operator := HwReal.Operator;
ELSE
    SimJoystickManualNeutral := (SimJoystickRawX = 5000) AND (SimJoystickRawY = 5000);
    SimJoystickGesturePermit := SimJoystickManualNeutral AND NOT SimJoystickRawButton;
    instSimJoystick(
        Enable              := TRUE,
        GesturePermit       := SimJoystickGesturePermit,
        NeutralRaw          := 5000,
        MaxRaw              := 10000,
        BtnLeft_Rev_TREMIE  := SimJoystickLeft_Rev_TREMIE_Active,
        BtnRight_Fwd_MAINT  := SimJoystickRight_Fwd_MAINT_Active,
        BtnFwd_Up_Close     := SimJoystickFwd_Up_Close_Active,
        BtnRev_Down_Open    := SimJoystickRev_Down_Open_Active,
        OvershootActive     := SimJoystickOvershoot_Active,
        BagotementActive    := SimJoystickBagotement_Active,
        CycleTimeS          := 0.010
    );

    // Une seule source possede les trois signaux : aucun melange bouton/axes.
    // La propriete automatique persiste au retour et si un stimulus manuel est en conflit.
    IF instSimJoystick.ModelActive THEN
        Operator.JoyXRaw_ANA1 := instSimJoystick.RawX;
        Operator.JoyYRaw_ANA2 := instSimJoystick.RawY;
        Operator.JoyBtnRaw := instSimJoystick.RawButton;
    ELSE
        // Modèle au repos → stimulus analogique avancé (mode « sans bouton »).
        Operator.JoyXRaw_ANA1 := SimJoystickRawX;
        Operator.JoyYRaw_ANA2 := SimJoystickRawY;
        Operator.JoyBtnRaw := SimJoystickRawButton;
    END_IF;

    Operator.CanBusState      := 2; // CANbusState 2 = ACTIVE
    Operator.JOY1_DeviceState := DEVICE_STATE.RUNNING; // État device RUNNING
END_IF;

{endregion}

{region "§5 Simulation securite et image machine"}
// ── 4. MODÈLE SÉCURITÉ & COMMUNS MACHINE ─────────────────────────────────────
instSimSafety(
    Enable            := TRUE,
    SimChainOkBit     := SimChainOkBit,
    SimPhaseRotationOkBit := SimPhaseRotationOkBit,
    PowerCutOff_A     := PowerKeepAlive_A,
    PowerCutOff_B     := PowerKeepAlive_B,
    PowerCutOffRequest:= PowerCutOffRequest,
    EmergencyArming   := EmergencyArming_RQ,
    BtnEmergencyStop  := BtnEmergencyStop,
    TestCutActive     := TestCutActive
);

Machine.PowerContactorEngaged_DI   := instSimSafety.SimContactorOk;
Machine.EmergencyChainClosed_DI    := instSimSafety.SimChainOk;
Machine.PhaseRotationOk_DI          := instSimSafety.SimPhaseRotationOk;
Machine.M1_M2_M3_BrakeThermalOk_DI     := TRUE;
instKoboldPowerUpTimer(IN := KoboldAutoEpisodeActive AND KoboldMeasureEnable
                        AND (M1_CablePos_M > KoboldAutoDepthEpisode_M),
                        PT := KoboldPowerUpEpisodeTime);
IF KoboldAutoEpisodeActive THEN
    Machine.M1_M2_KoboldBottomTouch_DI := instKoboldPowerUpTimer.Q
                                           AND (M1_CablePos_M > KoboldAutoDepthEpisode_M);
ELSE
    Machine.M1_M2_KoboldBottomTouch_DI := SimKoboldContactValue;
END_IF;
// T317 : memorise pour le prochain scan -- reutilise le VRAI capteur fond (Kobold), pas un
// stimulus invente, cf. retour utilisateur 2026-09-18 (le capteur fond existe deja reel+sim).
KoboldBottomTouchPrev_DI := Machine.M1_M2_KoboldBottomTouch_DI;
Machine.HydraulicThermalOk_DI          := TRUE;
Machine.TremieFull_OR_GateRaised_DI    := FALSE; // Pas encore câblé, simulé inactif par défaut

// ✅ Cycle de simulation terminé : les 4 images sont publiées pour ce scan
Busy := FALSE;
Done := TRUE;

{endregion}

instCycleTime(DefaultValueS := 0.010);
(* Le modele mono-pas suit le temps de cycle reel jusqu'a 100 ms. Cette borne
   evite de ralentir artificiellement la dynamique lorsque la trace est executee
   dans VISU_TASK (environ 100 ms), tout en restant stable pour le pendule reduit.
   Au-dela, FB_CycleTime fournit deja son temps de secours et aucun saut aberrant
   n'est accepte. La qualification des delais sub-100 ms exige toutefois une tache
   de trace plus rapide que 100 ms. *)
CycleTimeS := LIMIT(0.001, instCycleTime.CycleTimeS, 0.100);

(* Butees mecaniques derivees des capteurs extremes (reglages machine) + marge du rail. *)
EndStopTremie_M := PosTremie_M - MAX(EndStopMargin_M, CST_MinEndStopMargin_M);
EndStopMaintenance_M := PosMaintenance_M + MAX(EndStopMargin_M, CST_MinEndStopMargin_M);

IF NOT Enable THEN
    Initialized := FALSE;
    instDrive(Enable := FALSE);
    instBrake(Enable := FALSE);
    instSuspendedLoad(Enable := FALSE);
    FrequencyCmd_Hz := 0.0;
    ElectricalFrequency_Hz := 0.0;
    ActualFrequency_Hz := 0.0;
    BrakeMechanicallyOpen := FALSE;
    BrakeContactOpen := FALSE;
    BrakeCoilEnergized := FALSE;
    BrakeFaultCloseActive := FALSE;
    PositionTrue_M := PosP1_M;
    VelocityTrue_Mps := 0.0;
    PreviousVelocity_Mps := 0.0;
    TravelDirection := 0.0;
    LoadAngle_Rad := 0.0;
    SensorTransitionCount := 0;
    SensorBlipActive := FALSE;
    HardStopTremieActive := FALSE;
    HardStopMaintenanceActive := FALSE;
    (* Repli deterministe compatible avec le mot thermometre P1 = 00011. *)
    PosTremie := FALSE;
    PosPV := FALSE;
    PosP2 := FALSE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
    instSensorTremie(Enable := FALSE);
    instSensorPV(Enable := FALSE);
    instSensorP2(Enable := FALSE);
    instSensorP1(Enable := FALSE);
    instSensorMaintenance(Enable := FALSE);
    RETURN;
ELSIF NOT Initialized THEN
    Initialized := TRUE;
    PositionTrue_M := PosP1_M;
    TravelDirection := 0.0;
END_IF;

IF Enable THEN
    DirectionSign := 0.0;
    IF ReqTremie AND NOT ReqMaintenance THEN
        DirectionSign := -1.0;
    ELSIF ReqMaintenance AND NOT ReqTremie THEN
        DirectionSign := 1.0;
    END_IF;

    FrequencyTarget_Hz := LIMIT(0.0, ABS(SpeedTgt_Pct) * MaxFreq_Hz / 100.0, MaxFreq_Hz);
    IF DirectionSign = 0.0 THEN
        FrequencyTarget_Hz := 0.0;
    END_IF;
    instDrive(Enable := TRUE, FrequencyTgt_Hz := FrequencyTarget_Hz,
        AccelRate_HzPerS := AccelRate_HzPerS, DecelRate_HzPerS := DecelRate_HzPerS,
        TimeConstant_S := DriveTimeConstantS,
        LoadAngularVelocity_RadPerS := instSuspendedLoad.AngularVelocity_RadPerS,
        LoadFrequencyDroopGain_Hz := LoadFrequencyDroopGain_Hz, CycleTime_S := CycleTimeS);
    FrequencyCmd_Hz := instDrive.FrequencyCmd_Hz;
    ElectricalFrequency_Hz := instDrive.ElectricalFrequency_Hz;
    SpeedFactorApplied := LIMIT(1.0, SpeedFactor, 5.0);
    ActualFrequency_Hz := instDrive.ActualFrequency_Hz * SpeedFactorApplied;
    instBrake(Enable := TRUE, ReleaseCmd := BrakeReleaseCmd,
        ActualFrequency_Hz := instDrive.ActualFrequency_Hz, OpenDelay_S := BrakeOpenDelayS,
        CloseDelay_S := BrakeCloseDelayS, ContactDelay_S := BrakeContactDelayS,
        CycleTime_S := CycleTimeS,
        FaultCloseWhileRunning := BrakeFaultCloseWhileRunning,
        FaultCloseDelay_S := BrakeFaultCloseDelay_S);
    BrakeCoilEnergized := instBrake.CoilEnergized;
    BrakeMechanicallyOpen := instBrake.MechanicallyOpen;
    BrakeContactOpen := instBrake.ContactOpen;
    BrakeFaultCloseActive := instBrake.FaultCloseActive;

    (* Sens memorise (C3). Regles, dans cet ordre :
       1. un ordre simple valide (re)memorise le sens ;
       2. deux ordres contradictoires neutralisent immediatement le sens — aucune
          excitation inventee (preserve TC-T300-MEC-030) ;
       3. commande retiree : le sens est CONSERVE tant que le variateur retourne de la
          vitesse (deceleration libre), puis purge des que la vitesse est nulle. *)
    IF ReqTremie AND NOT ReqMaintenance THEN
        TravelDirection := -1.0;
    ELSIF ReqMaintenance AND NOT ReqTremie THEN
        TravelDirection := 1.0;
    ELSIF ReqTremie AND ReqMaintenance THEN
        TravelDirection := 0.0;
    ELSIF ABS(instDrive.ActualFrequency_Hz) <= CST_StopFrequency_Hz THEN
        TravelDirection := 0.0;
    END_IF;

    PreviousVelocity_Mps := VelocityTrue_Mps;
    IF BrakeMechanicallyOpen THEN
        (* Source unique : meme gain que l'estimateur machine (vitesse = gain x frequence). *)
        VelocityTarget_Mps := TravelDirection * MAX(0.0, GainMetersPerHzSec) * ActualFrequency_Hz;
    ELSE
        VelocityTarget_Mps := 0.0;
    END_IF;
    VelocityTrue_Mps := VelocityTrue_Mps + instDrive.ResponseAlpha * (VelocityTarget_Mps - VelocityTrue_Mps);
    IF NOT BrakeMechanicallyOpen THEN
        VelocityTrue_Mps := 0.0;
    END_IF;
    HardStopTremieActive := FALSE;
    HardStopMaintenanceActive := FALSE;
    PositionCandidate_M := PositionTrue_M + VelocityTrue_Mps * CycleTimeS;
    IF PositionCandidate_M < EndStopTremie_M THEN
        PositionTrue_M := EndStopTremie_M;
        VelocityTrue_Mps := 0.0;
        HardStopTremieActive := TRUE;
    ELSIF PositionCandidate_M > EndStopMaintenance_M THEN
        PositionTrue_M := EndStopMaintenance_M;
        VelocityTrue_Mps := 0.0;
        HardStopMaintenanceActive := TRUE;
    END_IF;
    CartAcceleration_Mps2 := (VelocityTrue_Mps - PreviousVelocity_Mps) / CycleTimeS;
    instSuspendedLoad(Enable := TRUE, BrakeMechanicallyOpen := BrakeMechanicallyOpen,
        CartAcceleration_Mps2 := CartAcceleration_Mps2, Length_M := SuspendedLoadLength_M,
        Damping := SuspendedLoadDamping, ReactionGain_Mps2 := LoadReactionGain_Mps2,
        CycleTime_S := CycleTimeS);
    LoadAngle_Rad := instSuspendedLoad.Angle_Rad;
    IF HardStopTremieActive OR HardStopMaintenanceActive THEN
        RecoilMax_M := MIN(MAX(0.0, EndStopRecoilMax_M), EndStopMaintenance_M - EndStopTremie_M);
        IF (RecoilMax_M > 0.0) AND BrakeMechanicallyOpen THEN
            (* Recul autorise UNIQUEMENT en s'eloignant de la butee touchee, borne par
               EndStopRecoilMax_M : jamais plus loin dans la butee, jamais de saut cache. *)
            VelocityTrue_Mps := VelocityTrue_Mps + instSuspendedLoad.VelocityReaction_Mps;
            (* Contre une butee, l'entrainement DECROCHE : il ne maintient pas une consigne de
               vitesse dans l'obstacle. Sans cette purge, la consigne de vitesse ecrasait en
               permanence la reaction de charge et le chariot ne pouvait jamais ressortir de
               la zone capteur (recul alors impossible, quelle que soit la charge). *)
            TravelDirection := 0.0;
            IF HardStopTremieActive THEN
                VelocityTrue_Mps := MAX(0.0, VelocityTrue_Mps);
                PositionCandidate_M := LIMIT(EndStopTremie_M,
                    PositionTrue_M + VelocityTrue_Mps * CycleTimeS,
                    EndStopTremie_M + RecoilMax_M);
            ELSE
                VelocityTrue_Mps := MIN(0.0, VelocityTrue_Mps);
                PositionCandidate_M := LIMIT(EndStopMaintenance_M - RecoilMax_M,
                    PositionTrue_M + VelocityTrue_Mps * CycleTimeS,
                    EndStopMaintenance_M);
            END_IF;
            PositionTrue_M := PositionCandidate_M;
        ELSE
            VelocityTrue_Mps := 0.0;
        END_IF;
    ELSE
        VelocityTrue_Mps := VelocityTrue_Mps + instSuspendedLoad.VelocityReaction_Mps;
        PositionCandidate_M := PositionTrue_M + VelocityTrue_Mps * CycleTimeS;
        IF PositionCandidate_M < EndStopTremie_M THEN
            PositionTrue_M := EndStopTremie_M;
            VelocityTrue_Mps := 0.0;
            HardStopTremieActive := TRUE;
        ELSIF PositionCandidate_M > EndStopMaintenance_M THEN
            PositionTrue_M := EndStopMaintenance_M;
            VelocityTrue_Mps := 0.0;
            HardStopMaintenanceActive := TRUE;
        ELSE
            PositionTrue_M := PositionCandidate_M;
        END_IF;
    END_IF;
END_IF;

IF Enable AND (ABS(LoadAngle_Rad) > 0.0001) THEN
    SensorNoiseState := 3.91 * SensorNoiseState * (1.0 - SensorNoiseState);
    SensorNoise_M := (2.0 * SensorNoiseState - 1.0) * SensorJitterAmplitude_M;
ELSE
    SensorNoise_M := 0.0;
END_IF;
(* Les capteurs sont fixes au rail et observent le chariot. Le balancier agit
   seulement par la reaction mecanique sur PositionTrue_M et conditionne un
   episode electrique ; aucune deflexion de godet n'est injectee directement. *)
SensorPosition_M := PositionTrue_M + SensorNoise_M;
(* Les capteurs M3 sont volontairement cumulatifs : 11111 -> 00000. Chaque
   brique garde son hysteresis et son episode propres ; aucun timer partage ne
   peut masquer un front d'un autre capteur. *)
instSensorTremie(Enable := Enable, Position_M := SensorPosition_M,
    Threshold_M := PosTremie_M, Hysteresis_M := SensorHysteresis_M,
    ElectricalDelayS := SensorElectricalDelayS, IntermittenceActive := SensorIntermittenceActive
        AND (ABS(LoadAngle_Rad) >= SensorLoadAngleTriggerRad),
    IntermittenceDurationS := SensorStabilizationS, IntermittencePeriodS := SensorIntermittencePeriodS,
    ScenarioSeed := SensorScenarioSeed + 11,
    BlipTransitions := SensorBlipTransitions, BlipDurationS := SensorBlipDurationS,
    CycleTimeS := CycleTimeS);
instSensorPV(Enable := Enable, Position_M := SensorPosition_M,
    Threshold_M := PosPV_M, Hysteresis_M := SensorHysteresis_M,
    ElectricalDelayS := SensorElectricalDelayS, IntermittenceActive := SensorIntermittenceActive
        AND (ABS(LoadAngle_Rad) >= SensorLoadAngleTriggerRad),
    IntermittenceDurationS := SensorStabilizationS, IntermittencePeriodS := SensorIntermittencePeriodS,
    ScenarioSeed := SensorScenarioSeed + 23,
    BlipTransitions := SensorBlipTransitions, BlipDurationS := SensorBlipDurationS,
    CycleTimeS := CycleTimeS);
instSensorP2(Enable := Enable, Position_M := SensorPosition_M,
    Threshold_M := PosP2_M, Hysteresis_M := SensorHysteresis_M,
    ElectricalDelayS := SensorElectricalDelayS, IntermittenceActive := SensorIntermittenceActive
        AND (ABS(LoadAngle_Rad) >= SensorLoadAngleTriggerRad),
    IntermittenceDurationS := SensorStabilizationS, IntermittencePeriodS := SensorIntermittencePeriodS,
    ScenarioSeed := SensorScenarioSeed + 37,
    BlipTransitions := SensorBlipTransitions, BlipDurationS := SensorBlipDurationS,
    CycleTimeS := CycleTimeS);
instSensorP1(Enable := Enable, Position_M := SensorPosition_M,
    Threshold_M := PosP1_M, Hysteresis_M := SensorHysteresis_M,
    ElectricalDelayS := SensorElectricalDelayS, IntermittenceActive := SensorIntermittenceActive
        AND (ABS(LoadAngle_Rad) >= SensorLoadAngleTriggerRad),
    IntermittenceDurationS := SensorStabilizationS, IntermittencePeriodS := SensorIntermittencePeriodS,
    ScenarioSeed := SensorScenarioSeed + 53,
    BlipTransitions := SensorBlipTransitions, BlipDurationS := SensorBlipDurationS,
    CycleTimeS := CycleTimeS);
instSensorMaintenance(Enable := Enable, Position_M := SensorPosition_M,
    Threshold_M := PosMaintenance_M, Hysteresis_M := SensorHysteresis_M,
    ElectricalDelayS := SensorElectricalDelayS, IntermittenceActive := SensorIntermittenceActive
        AND (ABS(LoadAngle_Rad) >= SensorLoadAngleTriggerRad),
    IntermittenceDurationS := SensorStabilizationS, IntermittencePeriodS := SensorIntermittencePeriodS,
    ScenarioSeed := SensorScenarioSeed + 71,
    BlipTransitions := SensorBlipTransitions, BlipDurationS := SensorBlipDurationS,
    CycleTimeS := CycleTimeS);

PosTremie := instSensorTremie.ElectricalOutput;
PosPV := instSensorPV.ElectricalOutput;
PosP2 := instSensorP2.ElectricalOutput;
PosP1 := instSensorP1.ElectricalOutput;
PosMaintenance := instSensorMaintenance.ElectricalOutput;
SensorTransitionCount := instSensorTremie.TransitionCount + instSensorPV.TransitionCount
    + instSensorP2.TransitionCount + instSensorP1.TransitionCount
    + instSensorMaintenance.TransitionCount;
SensorBlipActive := instSensorTremie.BlipActive OR instSensorPV.BlipActive
    OR instSensorP2.BlipActive OR instSensorP1.BlipActive
    OR instSensorMaintenance.BlipActive;

// === IMPLEMENTATION ===

{region "§1 Gain actif (toujours calculé — réglage pur, indépendant d'Enable)"}
DistanceP2PV_M := PosP2_M - PosPV_M;
IF (DistanceP2PV_M > 0.0) AND (CalibFreq_Hz > 0.0) AND (CalibTime_S > 0.0) THEN
    CalibGain := DistanceP2PV_M / (CalibFreq_Hz * CalibTime_S);
    CalibValid := (CalibGain >= CST_GainMin) AND (CalibGain <= CST_GainMax);
ELSE
    CalibGain := 0.0;
    CalibValid := FALSE;
END_IF;

IF CalibValid THEN
    GainActive := CalibGain;
ELSE
    // Repli borné : un repli nul/aberrant figerait l'estimateur (et le chariot simulé).
    GainActive := LIMIT(CST_GainMin, FallbackGain, CST_GainMax);
END_IF;
{endregion}

{region "§2 Gate mesure"}
// Fronts évalués à chaque scan, y compris hors Enable : aucun front périmé à la réactivation.
EdgeUpP2(CLK := SensorP2);   EdgeDnP2(CLK := SensorP2);
EdgeUpPV(CLK := SensorPV);   EdgeDnPV(CLK := SensorPV);

IF NOT Enable THEN
    MeasureActive := FALSE;
    RETURN;
END_IF;

CycleTimeCalc(DefaultValueS := 0.010);
FreqSample_Hz := LIMIT(0.0, DriveActualFreq_Hz, CST_FreqMax_Hz);
{endregion}

{region "§3 Mesure proposée P2 <-> PV (jamais appliquée)"}
// Mot thermomètre (TRUE si position <= cote) :
//   vers la Trémie      : P2 monte puis PV monte ;
//   vers la Maintenance : PV descend puis P2 descend.
// Seul le 1er front compte : les rebonds du capteur de départ (vu -> perdu -> retrouvé) sont
// ignorés une fois la mesure lancée ; la mesure ne se termine que sur le front ATTENDU.
IF NOT MeasureActive THEN
    IF EdgeUpP2.Q OR EdgeDnPV.Q THEN
        MeasureActive := TRUE;
        MeasureTowardTremie := EdgeUpP2.Q;
        ElapsedS := 0.0;
        FreqIntegral_HzS := 0.0;
        FreqMin_Hz := FreqSample_Hz;
        FreqMax_Hz := FreqSample_Hz;
    END_IF;
ELSE
    ElapsedS := ElapsedS + CycleTimeCalc.CycleTimeS;
    FreqIntegral_HzS := FreqIntegral_HzS + FreqSample_Hz * CycleTimeCalc.CycleTimeS;
    FreqMin_Hz := MIN(FreqMin_Hz, FreqSample_Hz);
    FreqMax_Hz := MAX(FreqMax_Hz, FreqSample_Hz);

    MeasureEnd := (MeasureTowardTremie AND EdgeUpPV.Q) OR (NOT MeasureTowardTremie AND EdgeDnP2.Q);

    IF MeasureEnd THEN
        MeasureActive := FALSE;
        MeasuredTime_S := ElapsedS;
        MeasuredFreqSpread_Hz := FreqMax_Hz - FreqMin_Hz;
        IF ElapsedS > 0.0 THEN
            MeasuredFreqAvg_Hz := FreqIntegral_HzS / ElapsedS;
        ELSE
            MeasuredFreqAvg_Hz := 0.0;
        END_IF;
        IF (FreqIntegral_HzS > 0.0) AND (DistanceP2PV_M > 0.0) THEN
            MeasuredGain := DistanceP2PV_M / FreqIntegral_HzS;
        ELSE
            MeasuredGain := 0.0;
        END_IF;
        MeasureCount := MeasureCount + 1;
    ELSIF (FreqSample_Hz < CST_MeasureMinFreq_Hz) OR (ElapsedS > CST_MeasureTimeout_S) THEN
        // Arrêt ou trajet interrompu : mesure abandonnée, dernier résultat publié conservé.
        MeasureActive := FALSE;
    END_IF;
END_IF;
{endregion}

{region "§0 Session simulation & aiguillage"}
// === 🧪 §0 SIMULATION & SÉLECTION DE SOURCE ===
// 🎯 Producteur unique des aiguillages Reel/Simu par domaine (HwReal vs HwSim -> HwIn).

SimulationModeRise(CLK := GVL_Simulation.SimulationModeActive);
SimulationModeFall(CLK := GVL_Simulation.SimulationModeActive);

// 🧪 Activation par domaine = SUR FRONT UNIQUEMENT : Sim*Active bascule au front montant
// (TRUE) et au front descendant (FALSE) de SimulationModeActive, jamais en niveau chaque scan.
// ⚠️ Si SimulationModeActive est déjà TRUE au boot (aucun front observé), Sim*Active reste
// FALSE → routage HwReal. Activer la simulation par un vrai front OFF→ON après démarrage.
// Cohérent pour les 4 domaines (Winch/Translation/Operator/Safety).
IF SimulationModeRise.Q THEN
    GVL_Simulation.SimWinchActive       := TRUE;
    GVL_Simulation.SimTranslationActive := TRUE;
    GVL_Simulation.SimOperatorActive    := TRUE;
    GVL_Simulation.SimSafetyActive      := TRUE;
END_IF;

IF SimulationModeFall.Q THEN
    // 🧪 Desactivation des aiguillages + reset des stimuli de simulation (front descendant)
    GVL_Simulation.SimWinchActive       := FALSE;
    GVL_Simulation.SimTranslationActive := FALSE;
    GVL_Simulation.SimOperatorActive    := FALSE;
    GVL_Simulation.SimSafetyActive      := FALSE;
    GVL_Simulation.SimM3SensorsWordOverrideActive := FALSE;
    GVL_Simulation.SimM3SensorsWord := 16#07;
    GVL_Simulation.SimJoystickLeft_Rev_TREMIE_Active := FALSE;
    GVL_Simulation.SimJoystickRight_Fwd_MAINT_Active := FALSE;
    GVL_Simulation.SimJoystickFwd_Up_Close_Active := FALSE;
    GVL_Simulation.SimJoystickRev_Down_Open_Active := FALSE;
    GVL_Simulation.SimJoystickRawX := 5000;
    GVL_Simulation.SimJoystickRawY := 5000;
    GVL_Simulation.SimJoystickRawButton := FALSE;
    GVL_Simulation.SimJoystickOvershoot_Active := FALSE;
    GVL_Simulation.SimJoystickBagotement_Active := FALSE;
    GVL_Simulation.SimEncoderSpeedFactor := 1.0;
    GVL_Simulation.SimTopPositionActive := FALSE;
    GVL_Simulation.SimChainOk := FALSE; // Chaîne AU ouverte à la ré-entrée (on n'a pas armé)
    GVL_Simulation.SimSyncDeviationInjectM1 := FALSE;
    GVL_Simulation.SimSyncDeviationInjectM2 := FALSE;
    GVL_Simulation.SimSyncDeviationOffset_M := 0.5;
    GVL_Simulation.SimKoboldContactValue := FALSE;
    GVL_Simulation.SimKoboldAutoModeActive := FALSE;
END_IF;

// 🪝 Kobold automatique : armement unique à l'entrée en SEMI_AUTO sur banc.
// Une action opérateur à FALSE reste donc effective pendant le mode courant.
SimulationSemiAutoActive := GVL_Simulation.SimulationModeActive
                            AND (PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.SEMI_AUTO);
IF SimulationSemiAutoActive AND NOT SimulationSemiAutoPrevious THEN
    GVL_Simulation.SimKoboldAutoModeActive := TRUE;
ELSIF NOT SimulationSemiAutoActive AND SimulationSemiAutoPrevious THEN
    GVL_Simulation.SimKoboldAutoModeActive := FALSE;
END_IF;
SimulationSemiAutoPrevious := SimulationSemiAutoActive;

// 🔀 Aiguillages de source uniques par domaine
WinchInputSourceSimulated       := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimWinchActive;
TranslationInputSourceSimulated := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimTranslationActive;
OperatorInputSourceSimulated    := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimOperatorActive;
MachineInputSourceSimulated     := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimSafetyActive;
{endregion}

{region "§1 Acquisition brute — HwReal"}
// === 📥 §1 ACQUISITION BRUTE MATÉRIELLE (HwReal) ===

// Winch M1 / M2 et codeurs
// Inversion des retours contacteurs physiques (compensation cablage terrain DI M1 <-> M2)
HwReal.Winch.M1_ContactorsReleased_DI := M2_ContactorsReleased_DI;
HwReal.Winch.M1_ThermalOk_DI          := M1_ThermalOk_DI;
HwReal.Winch.M1_BrakeIsOpen_DI        := M1_BrakeIsOpen_DI;

HwReal.Winch.M2_ContactorsReleased_DI := M1_ContactorsReleased_DI;
HwReal.Winch.M2_ThermalOk_DI          := M2_ThermalOk_DI;
HwReal.Winch.M2_BrakeIsOpen_DI        := M2_BrakeIsOpen_DI;

HwReal.Winch.M1M2_TopPositionFree_DI  := M1M2_TopPositionFree_DI;
HwReal.Winch.M2_TensionedCable_DI     := M2_TensionedCable_DI;

HwReal.Winch.COD1_PosValue            := COD1_PosValue;
HwReal.Winch.COD1_SpdValue            := COD1_SpdValue;
HwReal.Winch.COD1_Alarms              := COD1_Alarms;
HwReal.Winch.COD1_Warnings            := COD1_Warnings;
HwReal.Winch.COD1_DeviceState         := COD1_CODEUR.GetDeviceState();

HwReal.Winch.COD2_PosValue            := COD2_PosValue;
HwReal.Winch.COD2_SpdValue            := COD2_SpdValue;
HwReal.Winch.COD2_Alarms              := COD2_Alarms;
HwReal.Winch.COD2_Warnings            := COD2_Warnings;
HwReal.Winch.COD2_DeviceState         := COD2_CODEUR.GetDeviceState();

// Translation M3 et variateur AC600
HwReal.Translation.M3_PosTremie_DI      := M3_PosTremie_DI;
HwReal.Translation.M3_PosPV_DI          := M3_PosPV_DI;
HwReal.Translation.M3_PosPVP2_DI        := M3_PosPVP2_DI;
HwReal.Translation.M3_PosP1_DI          := M3_PosP1_DI;
HwReal.Translation.M3_PosMaintenance_DI := M3_PosMaintenance_DI;
HwReal.Translation.M3_BrakeIsOpen_DI    := M3_BrakeIsOpen_DI;
HwReal.Translation.M3_ThermalOK_DI       := M3_ThermalOK_DI;
HwReal.Translation.M3_StatusWord        := M3_StatusWord;
HwReal.Translation.M3_ActualFrequencyHz := M3_ActualFrequencyHz;
HwReal.Translation.AC600_DeviceState    := AC600_ECAT_Drive.GetDeviceState();

// Opérateur / Joystick / bus CANopen
HwReal.Operator.JoyXRaw_ANA1      := JoyXRaw_ANA1;
HwReal.Operator.JoyYRaw_ANA2      := JoyYRaw_ANA2;
HwReal.Operator.JoyBtnRaw         := JoyBtnRaw;
HwReal.Operator.CanBusState       := CANbus.GetBusState();
HwReal.Operator.JOY1_DeviceState  := JOY1_JOYSTICK_MCB560_CO4201A.GetDeviceState();

// Sécurités / Communs Machine
HwReal.Machine.PowerContactorEngaged_DI   := PowerContactorEngaged_DI;
HwReal.Machine.EmergencyChainClosed_DI    := EmergencyChainClosed_DI;
HwReal.Machine.PhaseRotationOk_DI         := PhaseRotationOk_DI;
HwReal.Machine.M1_M2_M3_BrakeThermalOk_DI  := M1_M2_M3_BrakeThermalOk_DI;
HwReal.Machine.M1_M2_KoboldBottomTouch_DI  := M1_M2_KoboldBottomTouch_DI;
HwReal.Machine.HydraulicThermalOk_DI       := HydraulicThermalOk_DI;
HwReal.Machine.ConveyorInfeedReady_DI      := ConveyorInfeedReady_DI;
HwReal.Machine.TremieFull_OR_GateRaised_DI := TremieFull_OR_GateRaised_DI; // 🚧 Déclaré, non consommé — interlock trémie à câbler
{endregion}

{region "§1bis Diagnostic modules E/S"}
// === 🩺 §1bis DIAGNOSTIC MODULES E/S ===
// 🩺 Diagnostic carte des 5 modules d'E/S physiques (AF06 §3bis).
// GetDeviceState() = RUNNING => module opérationnel. Si la simulation globale/machine est active,
// les cartes physiques absentes sont simulées OK pour permettre le fonctionnement banc.
IF MachineInputSourceSimulated OR GVL_IHM.Network.Bypass.Global OR GVL_IHM.Network.Bypass.InputModules THEN
    Data.InputModules.LocalDigitalIoOk := TRUE;
    Data.InputModules.Vh0800EndOk      := TRUE;
    Data.InputModules.Vh0808EtpOk      := TRUE;
    Data.InputModules.Vh0008ErOk       := TRUE;
    Data.InputModules.Vh0008Er1Ok      := TRUE;
ELSE
    Data.InputModules.LocalDigitalIoOk := (Local_Digital_IO.GetDeviceState() = DEVICE_STATE.RUNNING);
    Data.InputModules.Vh0800EndOk      := (VH_0800END.GetDeviceState() = DEVICE_STATE.RUNNING);
    Data.InputModules.Vh0808EtpOk      := (VH_0808ETP.GetDeviceState() = DEVICE_STATE.RUNNING);
    Data.InputModules.Vh0008ErOk       := (VH_0008ER.GetDeviceState() = DEVICE_STATE.RUNNING);
    Data.InputModules.Vh0008Er1Ok      := (VH_0008ER_1.GetDeviceState() = DEVICE_STATE.RUNNING);
END_IF;
Data.InputModules.Fault := NOT (Data.InputModules.LocalDigitalIoOk AND Data.InputModules.Vh0800EndOk AND Data.InputModules.Vh0808EtpOk AND Data.InputModules.Vh0008ErOk AND Data.InputModules.Vh0008Er1Ok);
{endregion}

{region "§1ter Diagnostic reseaux (CANopen + EtherCAT)"}
// === 🔌 §1ter DIAGNOSTIC RÉSEAUX (CANopen + EtherCAT) ===
// 🔌 Diagnostics reseau produits ICI (rang 02) car consommes par PRG_02 (joystick,
// codeurs) et par les PRG 04/05 — producteur avant consommateur (AF02 §4).
// 🔌 Auto-acquittement borné des diagnostics transitoires (EtherCAT / CANopen).
// ⚠️ Les 2 autorisations sont ACTIVES PAR DÉFAUT, câblées en dur : le service doit fonctionner
//    sans réglage ni exposition opérateur. Elles ne dépendent PLUS de GVL_Simulation, dont la
//    frontière réel/simulé reste seule propriétaire : un booléen de configuration sans écrivain
//    laissait le service totalement inerte (State figé à 0, Phase et ResetPulse jamais atteints).
instAutoResetTransientDiag(
    Enable                  := TRUE,
    StartupEnable           := TRUE,
    PowerRearmEnable        := TRUE,
    EmergencyChainClosed    := HwIn.Machine.EmergencyChainClosed_DI,
    PowerContactorEngaged   := HwIn.Machine.PowerContactorEngaged_DI,
    PowerCutOffActive       := PRG_06_Outputs.PowerCutOffActive,
    MotionActive             := PRG_04_Treuils_Benne.Data.BothActive
                                  OR PRG_04_Treuils_Benne.Data.WinchM1State.Busy
                                  OR PRG_04_Treuils_Benne.Data.WinchM2State.Busy
                                  OR PRG_05_Translation.TranslationState.Busy,
    DiagnosticsStable        := instDiagEthercat.DeviceEthercatMaster.Operational
                                  AND instDiagCanOpen.DeviceCanOpenMaster.Operational
    // Les 3 réglages Cfg_ ne sont pas câblés : le FB applique ses propres défauts déclarés
    // (1 tentative, T#1s de stabilisation, T#1s entre tentatives), valeurs identiques à celles
    // portées auparavant par la GVL de simulation.
);

instDiagCanOpen(
    Enable                 := TRUE,
    Reset                  := PRG_07_Supervision.FaultMachineReset_IHM,
    ResetTransient         := instAutoResetTransientDiag.ResetPulse,
    CANbusStateRaw         := HwReal.Operator.CanBusState,
    DeviceJoystickStateRaw := HwReal.Operator.JOY1_DeviceState,
    SimBypassActive        := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimOperatorActive,
    NetworkBypassActive    := GVL_IHM.Network.Bypass.Global,
    CanBusBypassActive     := GVL_IHM.Network.Bypass.BusCanOpen,
    JoystickBypassActive   := GVL_IHM.Network.Bypass.Joystick
);
instDiagEthercat(
    Enable                   := TRUE,
    Reset                    := PRG_07_Supervision.FaultMachineReset_IHM,
    ResetTransient           := instAutoResetTransientDiag.ResetPulse,
    DeviceVariateurStateRaw  := HwReal.Translation.AC600_DeviceState,
    DeviceVariateurSimBypass := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimTranslationActive,
    DeviceEncoderM1StateRaw  := HwReal.Winch.COD1_DeviceState,
    DeviceEncoderM1SimBypass := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimWinchActive,
    DeviceEncoderM2StateRaw  := HwReal.Winch.COD2_DeviceState,
    DeviceEncoderM2SimBypass := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimWinchActive,
    NetworkBypassActive      := GVL_IHM.Network.Bypass.Global,
    // ⚠️ TEST MES TEMPORAIRE : inhibition EtherCAT forcée par le code.
    // Le bypass maitre est desactive : la stabilite reelle reste observable.
    EcatBusBypassActive      := FALSE,
    VariateurBypassActive    := GVL_IHM.Network.Bypass.VariateurM3,
    EncoderM1BypassActive    := GVL_IHM.Network.Bypass.EncoderM1,
    EncoderM2BypassActive    := GVL_IHM.Network.Bypass.EncoderM2
);

// 📤 Publication du sous-bus diagnostics réseaux
Data.Network.CanOpenMaster   := instDiagCanOpen.DeviceCanOpenMaster;
Data.Network.Joystick        := instDiagCanOpen.DeviceJoystick;
Data.Network.EthercatMaster  := instDiagEthercat.DeviceEthercatMaster;
Data.Network.EncoderM1       := instDiagEthercat.DeviceEncoderM1;
Data.Network.EncoderM2       := instDiagEthercat.DeviceEncoderM2;
Data.Network.DriveM3         := instDiagEthercat.DeviceVariateur;
{endregion}

{region "§2 Simulation et aiguillage — HwIn"}
// === 🎭 §2 SIMULATION & AIGUILLAGE (HwIn) ===

instSimBench(
    Enable                   := GVL_Simulation.SimulationModeActive,
    OperatorSourceActive     := OperatorInputSourceSimulated,
    M1_RelayFwd              := PRG_06_Outputs.Data.M1RelayFwd,
    M1_RelayRev              := PRG_06_Outputs.Data.M1RelayRev,
    M1_SpeedContactor_1      := PRG_06_Outputs.Data.M1SpeedContactor1,
    M1_SpeedContactor_2      := PRG_06_Outputs.Data.M1SpeedContactor2,
    M1_SpeedContactor_3      := PRG_06_Outputs.Data.M1SpeedContactor3,
    M1_SpeedContactor_4      := PRG_06_Outputs.Data.M1SpeedContactor4,
    M1_SpeedCmd_Pct          := PRG_04_Treuils_Benne.Data.M1LogicRequestSpeedCmd_Pct,
    M1_StepNumber            := PRG_04_Treuils_Benne.Data.WinchM1State.StepNumber,
    M1_PresetTriggerCmd      := instEncoderM1.HwOut.PresetTriggerCmd,
    M1_PresetValueOut        := instEncoderM1.HwOut.PresetValueOut,
    M1_BrakeCmd              := PRG_06_Outputs.Data.M1BrakeCmd,
    M2_RelayFwd              := PRG_06_Outputs.Data.M2RelayFwd,
    M2_RelayRev              := PRG_06_Outputs.Data.M2RelayRev,
    M2_SpeedContactor_1      := PRG_06_Outputs.Data.M2SpeedContactor1,
    M2_SpeedContactor_2      := PRG_06_Outputs.Data.M2SpeedContactor2,
    M2_SpeedContactor_3      := PRG_06_Outputs.Data.M2SpeedContactor3,
    M2_SpeedContactor_4      := PRG_06_Outputs.Data.M2SpeedContactor4,
    M2_SpeedCmd_Pct          := PRG_04_Treuils_Benne.Data.M2LogicRequestSpeedCmd_Pct,
    M2_StepNumber            := PRG_04_Treuils_Benne.Data.WinchM2State.StepNumber,
    M2_PresetTriggerCmd      := instEncoderM2.HwOut.PresetTriggerCmd,
    M2_PresetValueOut        := instEncoderM2.HwOut.PresetValueOut,
    M2_BrakeCmd              := PRG_06_Outputs.Data.M2BrakeCmd,
    // 🧪 Simulation M3 — FIDÉLITÉ : le modèle ne doit progresser QUE quand la
    // vraie machine commande réellement (sortie PRG_06, post-interlock), pas sur la
    // commande brute (sinon le modèle outrepasse butées/limites). Les deux bits explicites
    // sont décodés depuis le mot effectivement appliqué au variateur.
    M3_ReqTremie            := M3_CommandWord = 1,
    M3_ReqMaintenance       := M3_CommandWord = 2,
    M3_SpeedCmd_Pct          := LIMIT(0.0,
                                      (WORD_TO_UINT(M3_SetpointFrequencyHz) / 100.0)
                                      / GVL_PERSISTENT._TranslationMaxFreq_Hz * 100.0,
                                      100.0),
    M3_BrakeCmd              := PRG_06_Outputs.Data.TranslationBrakeCmd,
    PowerKeepAlive_A         := PRG_06_Outputs.Data.PowerKeepAliveACmd,
    PowerKeepAlive_B         := PRG_06_Outputs.Data.PowerKeepAliveBCmd,
    // 🧪 Simulation uniquement : l'état étape 5 sécurise le transfert même si la sortie
    // inter-POU ArmPulse est observée avec un cycle de retard dans la tâche.
    EmergencyArming_RQ       := PRG_06_Outputs.Data.EmergencyArmingCmd
                                 OR (PRG_06_Outputs.EmergencyState.Step = 5),
    // 🧪 Test de redondance AU : la simulation ouvre la boucle (SimChainOk=FALSE) pendant
    // le test A/B pour que le FB AU valide la chute de chaîne (cercle cassé, voir FB_Sim_Safety).
    TestCutActive            := PRG_06_Outputs.Data.TestCutActive,
    // 🛑 Coupure métier : la simulation ouvre la chaîne AU (arrêt d'urgence) sur PowerCutOffRequest.
    PowerCutOffRequest       := PRG_06_Outputs.Data.PowerCutOffRequest,
    // 🧪 Contrôle granulaire de la chaîne AU : bit opérateur (GVL_Simulation.SimChainOk).
    SimChainOkBit            := GVL_Simulation.SimChainOk,
    // 🧪 Stimulus défaut rotation de phases : TRUE = phases saines, FALSE = défaut.
    SimPhaseRotationOkBit    := GVL_Simulation.SimPhaseRotationOk,
    SimEncoderSpeedFactor    := GVL_Simulation.SimEncoderSpeedFactor,
    SimWinchCoast_M          := GVL_Simulation.SimWinchCoast_M,
    SimTopPositionActive     := GVL_Simulation.SimTopPositionActive,
    SimSyncDeviationInjectM1 := GVL_Simulation.SimSyncDeviationInjectM1,
    SimSyncDeviationInjectM2 := GVL_Simulation.SimSyncDeviationInjectM2,
    SimSyncDeviationOffset_M := GVL_Simulation.SimSyncDeviationOffset_M,
    SimM2CoupledDescentModelActive := GVL_Simulation.SimM2CoupledDescentModelActive,
    SimM2CoupledDescentFactor := GVL_Simulation.SimM2CoupledDescentFactor,
    WinchBothDescentIntent   := PRG_03_Modes_Cycle.Data.WinchBothIntent.Active
                                AND PRG_03_Modes_Cycle.Data.WinchBothIntent.ReqDescend,
    SimWinchDynamicsActive   := GVL_Simulation.SimWinchDynamicsActive,
    SimWinchSpeedReportTauS  := GVL_Simulation.SimWinchSpeedReportTauS,
    SimWinchBrakeOpenDelayS  := GVL_Simulation.SimWinchBrakeOpenDelayS,
    SimWinchBrakeCloseDelayS := GVL_Simulation.SimWinchBrakeCloseDelayS,
    SimWinchElectricalDiagnosticsActive := GVL_Simulation.SimWinchElectricalDiagnosticsActive,
    // Rattrapage mecanique M1/M2 : reprise de jeu en montee couplee (banc uniquement).
    SimWinchCouplingModelActive := GVL_Simulation.SimWinchCouplingModelActive,
    SimBucketJamActive       := GVL_Simulation.SimBucketJamActive,
    M2_CablePos_M            := Data.EncoderM2.Measurement.CablePosM,
    BucketOffsetCloseM       := _BucketCfgPersist.Config.OffsetCloseM,
    BucketCoherenceLimitM    := _BucketCfgPersist.Config.CoherenceLimitM,
    BucketOffsetOpen_M       := _BucketCfgPersist.Config.OffsetOpenM,
    BucketOpenAnticipation_M := _BucketCfgPersist.Config.OpenAnticipationM,
    BucketAx15bOpenActive    := PRG_03_Modes_Cycle.Data.SequenceState.Step = E_AutoCycleStep.AX15B_DUMP_OPEN,
    SimM2TensionedCableFaultInject := GVL_Simulation.SimM2TensionedCableFaultInject,
    SimM3SensorsWordOverrideActive := GVL_Simulation.SimM3SensorsWordOverrideActive,
    SimM3SensorsWord               := GVL_Simulation.SimM3SensorsWord,
    SimM3SensorIntermittenceActive  := GVL_Simulation.SimM3SensorIntermittenceActive,
    SimM3SensorStabilizationS       := GVL_Simulation.SimM3SensorStabilizationS,
    SimM3SensorElectricalDelayS     := GVL_Simulation.SimM3SensorElectricalDelayS,
    SimM3SensorIntermittencePeriodS := GVL_Simulation.SimM3SensorIntermittencePeriodS,
    SimM3SensorHysteresis_M         := GVL_Simulation.SimM3SensorHysteresis_M,
    SimM3SensorLoadAngleTriggerRad  := GVL_Simulation.SimM3SensorLoadAngleTriggerRad,
    SimM3SensorScenarioSeed         := GVL_Simulation.SimM3SensorScenarioSeed,
    SimM3SensorBlipTransitions      := GVL_Simulation.SimM3SensorBlipTransitions,
    SimM3SensorBlipDurationS        := GVL_Simulation.SimM3SensorBlipDurationS,
    SimM3EndStopRecoilMax_M         := GVL_Simulation.SimM3EndStopRecoilMax_M,
    SimM3EndStopMargin_M            := GVL_Simulation.SimM3EndStopMargin_M,
    // T301/L1 — SOURCE UNIQUE : positions capteurs = reglages machine, gain = gain EFFECTIF de
    // l'estimateur (PRG_05, valeur du cycle precedent). Le banc ne porte aucune geometrie propre.
    M3_PosTremie_M                  := GVL_PERSISTENT._TranslationPosTremie_M,
    M3_PosPV_M                      := GVL_PERSISTENT._TranslationPosPV_M,
    M3_PosP2_M                      := GVL_PERSISTENT._TranslationPosP2_M,
    M3_PosP1_M                      := GVL_PERSISTENT._TranslationPosP1_M,
    M3_PosMaintenance_M             := GVL_PERSISTENT._TranslationPosMaintenance_M,
    M3_OdometryGain                 := PRG_05_Translation.Data.TranslationState.OdometryGainActive,
    SimM3LoadReactionGain_Mps2      := GVL_Simulation.SimM3LoadReactionGain_Mps2,
    SimM3BrakeFaultCloseWhileRunning := GVL_Simulation.SimM3BrakeFaultCloseWhileRunning,
    SimM3BrakeFaultCloseDelayS       := GVL_Simulation.SimM3BrakeFaultCloseDelayS,
    SimJoystickLeft_Rev_TREMIE_Active  := GVL_Simulation.SimJoystickLeft_Rev_TREMIE_Active,
    SimJoystickRight_Fwd_MAINT_Active  := GVL_Simulation.SimJoystickRight_Fwd_MAINT_Active,
    SimJoystickFwd_Up_Close_Active     := GVL_Simulation.SimJoystickFwd_Up_Close_Active,
    SimJoystickRev_Down_Open_Active    := GVL_Simulation.SimJoystickRev_Down_Open_Active,
    SimJoystickRawX                    := GVL_Simulation.SimJoystickRawX,
    SimJoystickRawY                    := GVL_Simulation.SimJoystickRawY,
    SimJoystickRawButton               := GVL_Simulation.SimJoystickRawButton,
    SimJoystickOvershoot_Active        := GVL_Simulation.SimJoystickOvershoot_Active,
    SimJoystickBagotement_Active       := GVL_Simulation.SimJoystickBagotement_Active,
    SimKoboldContactValue    := GVL_Simulation.SimKoboldContactValue,
    SimKoboldAutoModeActive  := GVL_Simulation.SimKoboldAutoModeActive,
    SimKoboldAutoDepth_M     := GVL_Simulation.SimKoboldAutoDepth_M,
    SimKoboldPowerUpTime     := GVL_Simulation.SimKoboldPowerUpTime,
    SimKoboldCoast_M         := GVL_Simulation.SimKoboldCoast_M,
    KoboldMeasureEnable      := PRG_04_Treuils_Benne.Data.KoboldContactorCmdArbitrated,
    M1_CablePos_M            := Data.EncoderM1.Measurement.CablePosM,
    BtnEmergencyStop         := GVL_IHM.Emergency.Cmd.BtnEmergencyCutOff,
    HwReal                   := HwReal,
    RawPosM1                 := _SimEncoderRawPosM1,
    RawPosM2                 := _SimEncoderRawPosM2
);

// Exposition de l'image de simulation produite par le banc
HwSim.Winch       := instSimBench.Winch;
HwSim.Translation := instSimBench.Translation;
HwSim.Operator    := instSimBench.Operator;
HwSim.Machine     := instSimBench.Machine;

// 🔀 Détection de bascule de source (réel/simu) par domaine — impulsion 1 cycle.
// Même pattern que Winch : mémoire Previous*InputSourceSimulated + comparaison.
IF NOT WinchInputSourceInitialized THEN
    PreviousWinchInputSourceSimulated := WinchInputSourceSimulated;
    WinchInputSourceInitialized := TRUE;
    Data.InputSource.WinchInputSourceChanged := FALSE;
ELSE
    Data.InputSource.WinchInputSourceChanged := (WinchInputSourceSimulated <> PreviousWinchInputSourceSimulated);
    PreviousWinchInputSourceSimulated := WinchInputSourceSimulated;
END_IF;

IF NOT TranslationInputSourceInitialized THEN
    PreviousTranslationInputSourceSimulated := TranslationInputSourceSimulated;
    TranslationInputSourceInitialized := TRUE;
    Data.InputSource.TranslationInputSourceChanged := FALSE;
ELSE
    Data.InputSource.TranslationInputSourceChanged := (TranslationInputSourceSimulated <> PreviousTranslationInputSourceSimulated);
    PreviousTranslationInputSourceSimulated := TranslationInputSourceSimulated;
END_IF;

IF NOT OperatorInputSourceInitialized THEN
    PreviousOperatorInputSourceSimulated := OperatorInputSourceSimulated;
    OperatorInputSourceInitialized := TRUE;
    Data.InputSource.OperatorInputSourceChanged := FALSE;
ELSE
    Data.InputSource.OperatorInputSourceChanged := (OperatorInputSourceSimulated <> PreviousOperatorInputSourceSimulated);
    PreviousOperatorInputSourceSimulated := OperatorInputSourceSimulated;
END_IF;

IF NOT MachineInputSourceInitialized THEN
    PreviousMachineInputSourceSimulated := MachineInputSourceSimulated;
    MachineInputSourceInitialized := TRUE;
    Data.InputSource.MachineInputSourceChanged := FALSE;
ELSE
    Data.InputSource.MachineInputSourceChanged := (MachineInputSourceSimulated <> PreviousMachineInputSourceSimulated);
    PreviousMachineInputSourceSimulated := MachineInputSourceSimulated;
END_IF;

// 🔧 SEL(G, IN0, IN1) : brique standard IEC 61131-3, retourne IN1 si G=TRUE, IN0 sinon
// (AF_Partie-03 §1 : composer l'existant avant réimplémentation) — remplace les 4 IF/ELSE
// compactés qui cassaient le générateur ST→LD (CODE_QUALITY_STANDARDS.md §11).
// Utilisation explicite de HwSim.* et des 4 variables de sélection par domaine.
HwIn.Winch       := SEL(WinchInputSourceSimulated, HwReal.Winch, HwSim.Winch);
HwIn.Translation := SEL(TranslationInputSourceSimulated, HwReal.Translation, HwSim.Translation);
HwIn.Operator    := SEL(OperatorInputSourceSimulated, HwReal.Operator, HwSim.Operator);
HwIn.Machine     := SEL(MachineInputSourceSimulated, HwReal.Machine, HwSim.Machine);
{endregion}


{region "§3 Traitement joystick"}
// === 🕹️ §3 TRAITEMENT JOYSTICK ===

// La table des paliers est une source unique commune M1/M2. Les autres
// reglages restent ceux propres au joystick et a son pont IHM/persistant.
JoystickCfgEffective := GVL_PERSISTENT._JoystickCfgPersist;
JoystickCfgEffective.SpeedStepTable := GVL_PERSISTENT._WinchSpeedStepTable;

instJoystick(
    Enable                    := TRUE,
    Reset                     := PRG_07_Supervision.FaultMachineReset_IHM,
    // 🚨 ArmingPermit = ENTRÉE du joystick (vue joystick), alimentée de n'importe où.
    // 🔧 Producteur = PRG_04_Treuils_Benne (combiné interlock benne) via le bus Data.
    //    TRUE = armement autorisé (polarité positive NC-100).
    ArmingPermit              := PRG_04_Treuils_Benne.Data.ArmingPermit,
    // Autorise l'inversion directe du joystick pendant toute l'extraction et pendant
    // le vidage (repli benne + treuils).
    // Le deadman reste obligatoire ; seule la remise au neutre est supprimee
    // aux transitions AX8 -> AX12 et a AX15b pour conserver la commande maintenue.
    DirectInversionPermit     :=
        (GVL_IHM.CycleSemiAuto.State.CycleStep = E_AutoCycleStep.AX8_BOTTOM_CONFIRMED)
        OR (GVL_IHM.CycleSemiAuto.State.CycleStep = E_AutoCycleStep.AX9_RAISE_OFF_BOTTOM)
        OR (GVL_IHM.CycleSemiAuto.State.CycleStep = E_AutoCycleStep.AX10_CLOSE_BUCKET)
        OR (GVL_IHM.CycleSemiAuto.State.CycleStep = E_AutoCycleStep.AX11_CTRL_ASCENT)
        OR (GVL_IHM.CycleSemiAuto.State.CycleStep = E_AutoCycleStep.AX12_LOADED_ASCENT)
        // Repli du vidage : le geste inverse (Y+ apres Y-) doit atteindre l'etape de
        // fermeture benne sans exiger une remise au neutre, sinon l'homme-mort se
        // desarme au milieu de l'intervention.
        OR (GVL_IHM.CycleSemiAuto.State.CycleStep = E_AutoCycleStep.AX15B_DUMP_OPEN),
    BusCanOpenOP              := instDiagCanOpen.DeviceCanOpenMaster,
    JoystickOP                := instDiagCanOpen.DeviceJoystick,
    RawX                      := HwIn.Operator.JoyXRaw_ANA1,
    RawY                      := HwIn.Operator.JoyYRaw_ANA2,
    RawButton                 := HwIn.Operator.JoyBtnRaw,
    Calibrate                 := GVL_IHM.JOY1Joystick.Cmd.Calibrate,
    Cfg                       := JoystickCfgEffective,
    NeutralXMem               := _JoystickNeutralX,
    NeutralYMem               := _JoystickNeutralY
);

// 📤 Publication du sous-bus joystick qualifié
Data.Joystick.AxisX              := instJoystick.AxisCmdX;
Data.Joystick.AxisY              := instJoystick.AxisCmdY;
Data.Joystick.DeadmanArmed       := instJoystick.DeadmanArmed;
Data.Joystick.AtNeutralXY        := instJoystick.AtNeutralXY;
Data.Joystick.ArmingPermitDenied := instJoystick.ArmingPermitDenied;
Data.Joystick.Ready              := instJoystick.Ready;
Data.Joystick.Fault              := instJoystick.Fault;
Data.Joystick.NeutralXAct        := instJoystick.NeutralXAct;
Data.Joystick.NeutralYAct        := instJoystick.NeutralYAct;
{endregion}

{region "§4 Codeurs et homing — M1/M2"}
// === 🧲 §4 CODEURS & HOMING (M1 / M2) ===

// ── TREUIL M1 (Retenue) ──
// Facade codeur complete : Abs→Homing→Scale→Safety→Reliability→Speed.
// L'autorisation de homing est calculee ici (mode + treuil selectionne).
// Frontiere hardware remplie avant l'appel (le bus Hw est passe en entier).
(* Centralise les fronts IHM avant les deux facades codeur. La polarite du DI
   est explicite : Free=TRUE signifie capteur haut non atteint. *)
MachineHomingM1Status.HomedAndReliable := Data.EncoderM1.HomedAndReliable;
MachineHomingM1Status.HomingBusy       := Data.EncoderM1.Measurement.HomingLifecycle.Busy;
MachineHomingM1Status.HomingDone       := Data.EncoderM1.Measurement.HomingLifecycle.Done;
MachineHomingM1Status.HomingError      := Data.EncoderM1.Measurement.HomingFault.Error;
MachineHomingM2Status.HomedAndReliable := Data.EncoderM2.HomedAndReliable;
MachineHomingM2Status.HomingBusy       := Data.EncoderM2.Measurement.HomingLifecycle.Busy;
MachineHomingM2Status.HomingDone       := Data.EncoderM2.Measurement.HomingLifecycle.Done;
MachineHomingM2Status.HomingError      := Data.EncoderM2.Measurement.HomingFault.Error;
MachineHomingMechanicalStopOk := HwIn.Winch.M1_ContactorsReleased_DI AND NOT HwIn.Winch.M1_BrakeIsOpen_DI
                                 AND (ABS(Data.EncoderM1.Measurement.Speed_Mps) < 0.02)
                                 AND HwIn.Winch.M2_ContactorsReleased_DI AND NOT HwIn.Winch.M2_BrakeIsOpen_DI
                                 AND (ABS(Data.EncoderM2.Measurement.Speed_Mps) < 0.02);

// Les confirmations benne restent des commandes IHM N2 dédiées : elles
// homent matériellement M2 sur la géométrie observée, sans ré-homer M1.
BucketReferenceOpenEdge(CLK := GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnConfirmOpenPos);
BucketReferenceCloseEdge(CLK := GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnConfirmClosePos);
BucketReferenceRequested := (BucketReferenceOpenEdge.Q XOR BucketReferenceCloseEdge.Q)
                          AND (PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.MAINT_N2)
                          AND MachineHomingMechanicalStopOk;
IF BucketReferenceOpenEdge.Q THEN
    // Symetrique du CLOSE ci-dessous : Delta attendu benne ouverte = OffsetOpenM (butee
    // physique reelle ~2.25 m), pas 0. L'ancien preset (M1 sans offset) forcait Delta=0
    // -> hors plage [OffsetOpenM-CoherenceLimitM .. OffsetCloseM+2] -> FB_Bucket relatchait
    // ErrorID:02 juste apres la confirmation (REX MES 2026-09-04, audit T250 finding M6).
    BucketReferenceTargetM := instEncoderM1.Measurement.CablePosM + _BucketCfgPersist.Config.OffsetOpenM;
ELSIF BucketReferenceCloseEdge.Q THEN
    BucketReferenceTargetM := instEncoderM1.Measurement.CablePosM + _BucketCfgPersist.Config.OffsetCloseM;
END_IF;

// Cible haute du homing machine = position capteur de M2 (benne) : seule la cible
// DYNAMIQUE M2 du cycle (FB_CycleMachineHoming §7) consomme ce champ ; M1 y home sur
// sa propre config (ligne CfgTopSensorPosM M1 ci-dessous). Geometrie de mouflage
// benne differente -> jamais la position M1.
MachineHomingCfg.CfgTopHomingTarget_M := _WinchM2CfgPersist.CfgTopSensorPos_M;
MachineHomingCfg.CfgOffsetOpen_M      := _BucketCfgPersist.Config.OffsetOpenM;
MachineHomingCfg.CfgOffsetClose_M     := _BucketCfgPersist.Config.OffsetCloseM;
MachineHomingCfg.Initialized          := TRUE;
instCycleMachineHoming(
    Enable                     := TRUE,
    Reset                      := PRG_07_Supervision.FaultMachineReset_IHM OR GVL_IHM.CycleMachineHoming.Cmd.BtnAbort,
    Mode                       := PRG_03_Modes_Cycle.Data.Auth.Mode,
    // Garde boot : aucun homing/G7 tant que acquisition + codeurs ne sont pas valides.
    BootReady                  := Data.DataValid AND Data.EncoderM1.Ready AND Data.EncoderM2.Ready,
    TopPositionSensor          := NOT HwIn.Winch.M1M2_TopPositionFree_DI,
    WinchesMechanicallyStopped  := MachineHomingMechanicalStopOk,
    M1Status                   := MachineHomingM1Status,
    M2Status                   := MachineHomingM2Status,
    // Reference benne PERSISTANTE (survit coupure puissance) et non le flag LIVE
    // ActiveOffsetValid (qui exige la puissance) -> pas de HX1 parasite apres une
    // simple coupure secteur si le datum absolu M1/M2 est intact.
    BucketOffsetValid          := PRG_04_Treuils_Benne.Data.BucketState.MechState.BucketReferenced,
    // Permis operateur maintenu (meme source que l'arbitrage joystick) : sens montee = manche
    // tire (Y+), sens descente = manche pousse (Y-) ; ref. baseline continuite C1.
    DeadmanArmed               := Data.Joystick.DeadmanArmed,
    JoystickDeflected          := NOT Data.Joystick.AtNeutralXY,
    JoystickPull               := Data.Joystick.AxisY.DirectionPositive,
    JoystickPush               := Data.Joystick.AxisY.DirectionNegative,
    // Lancer / valider le cycle : BP joystick (= bouton homme-mort) pour le motif 3 appuis,
    // OU commande IHM dediee (front) pour le lancement direct.
    BtnValidation              := HwIn.Operator.JoyBtnRaw OR GVL_IHM.CycleMachineHoming.Cmd.BtnValidate,
    StartRequest               := GVL_IHM.CycleMachineHoming.Cmd.BtnStart,
    // Confirmation visuelle benne fermee (nouveau bouton dedie IHM HX1)
    BtnConfirmHomingBucket     := GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnConfirmHomingBucket,
    // Interlock couplage E1 et mesures pour controle stabilisation HX4
    JoystickWinchSelectArbitrated := PRG_03_Modes_Cycle.Data.Auth.JoystickWinchSelectArbitrated,
    CablePosM1                 := Data.EncoderM1.Measurement.CablePosM,
    CablePosM2                 := Data.EncoderM2.Measurement.CablePosM,
    CoherenceLimitM            := GVL_PERSISTENT._BucketCfgPersist.Config.CoherenceLimitM,
    CfgCommissioningEnable     := GVL_IHM.CycleMachineHoming.Cmd.TglCommissioning,
    CfgForceStepTarget         := GVL_IHM.CycleMachineHoming.Cfg.ForceStepTarget,
    CfgForceStepApply          := GVL_IHM.CycleMachineHoming.Cmd.BtnForceStepApply,
    Cfg                        := MachineHomingCfg
);
Data.MachineHoming.Homed            := instCycleMachineHoming.MachineHomed;
Data.MachineHoming.SetPosBucketOpen := instCycleMachineHoming.BucketCommit.CommitOpen;
Data.MachineHoming.SetPosBucketClose := instCycleMachineHoming.BucketCommit.CommitClose;
Data.MachineHoming.Active           := instCycleMachineHoming.MachineHomingActive;
Data.MachineHoming.HomingLoss       := instCycleMachineHoming.MachineHomingLossSafeStop;
Data.MachineHoming.Step             := TO_INT(instCycleMachineHoming.MachineHomingStep);
Data.MachineHoming.Instruction      := instCycleMachineHoming.MachineHomingInstruction;
Data.MachineHoming.Failed           := instCycleMachineHoming.MachineHomingFailed;
Data.MachineHoming.SeqStep          := TO_INT(instCycleMachineHoming.MachineHomingSeqStep);
Data.MachineHoming.M3Locked         := instCycleMachineHoming.M3Locked;
Data.MachineHoming.CmdWinchM1       := instCycleMachineHoming.CmdWinchM1;
Data.MachineHoming.CmdWinchM2       := instCycleMachineHoming.CmdWinchM2;
Data.MachineHoming.CmdBucketOpen    := instCycleMachineHoming.CmdBucketOpen;
Data.MachineHoming.CmdBucketClose   := instCycleMachineHoming.CmdBucketClose;
Data.MachineHoming.CmdWinchSelect   := instCycleMachineHoming.CmdWinchSelect;
HwInM1.RawPosIn          := HwIn.Winch.COD1_PosValue;
HwInM1.SpdValueIn        := HwIn.Winch.COD1_SpdValue;
HwInM1.AlarmsIn          := HwIn.Winch.COD1_Alarms;
HwInM1.WarningsIn        := HwIn.Winch.COD1_Warnings;
HwInM1.SlaveOperational  := instDiagEthercat.DeviceEncoderM1.Operational;
HwInM1.PresetStatusBit    := FALSE;
instEncoderM1(
    Enable                := TRUE,
    Reset                 := PRG_07_Supervision.FaultMachineReset_IHM,
    // Homing unitaire M1 : autorise en MAINT_N1/N2 quel que soit WinchSel (0/1/2).
    // L'ancien verrou croise WinchSel<>2 est retire (demande MES) : le homing est un
    // appui bouton delibere ET conditionne a une position de reference (butee meca OK,
    // ou capteur haut atteint pour BtnHome) -> la garde position suffit. Le cycle homing
    // machine reste inconditionnel via M1Demand.HomeReq.
    HomingPermit          := (((PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.MAINT_N1 OR PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.MAINT_N2)
                               AND (MachineHomingMechanicalStopOk OR (NOT GVL_IHM.M1TreuilRetenue.Cmd.BtnHomingAtZero
                                                                       AND NOT HwIn.Winch.M1M2_TopPositionFree_DI)))
                              OR instCycleMachineHoming.M1Demand.HomeReq),
    HomingAtTargetM       := GVL_IHM.M1TreuilRetenue.Cmd.BtnHome
                             OR GVL_IHM.M1TreuilRetenue.Cmd.BtnHomingAtZero
                             OR instCycleMachineHoming.M1Demand.HomeReq,
    HomingAtZero          := GVL_IHM.M1TreuilRetenue.Cmd.BtnHomingAtZero,
    ConfirmCoherence      := GVL_IHM.M1TreuilRetenue.Cmd.BtnConfirmCoherence,
    CfgHomingTargetM      := SEL(GVL_IHM.M1TreuilRetenue.Cmd.BtnHomingAtZero,
                                 _WinchM1CfgPersist.CfgTopSensorPos_M, 0.0),
    CfgTopSensorPosM      := _WinchM1CfgPersist.CfgTopSensorPos_M,
    UseDynamicTarget      := FALSE,
    DynamicHomingTargetM  := 0.0,
    TopPositionSensor     := NOT HwIn.Winch.M1M2_TopPositionFree_DI,
    HwIn                  := HwInM1,
    PointsPerRev          := ENCODER_POINTS_PER_REV,
    CableM_PerRev         := WINCH_CABLE_M_PER_REV,
    Cfg                   := GVL_IHM.Commun.EncoderCfg,
    BypassGlobal          := GVL_IHM.M1TreuilRetenue.Bypass.Global,
    Calib                 := _CalibM1
);

// 📤 Publication de la façade codeur M1 qualifiée
Data.EncoderM1.Measurement              := instEncoderM1.Measurement;
Data.EncoderM1.Ready                    := instEncoderM1.Ready;
Data.EncoderM1.Fault                    := instEncoderM1.Fault;
Data.EncoderM1.Homed                    := instEncoderM1.Homed;
Data.EncoderM1.HomingSuspect            := instEncoderM1.HomingSuspect;
Data.EncoderM1.EncoderFault             := instEncoderM1.EncoderFault;
Data.EncoderM1.HomedAndReliable         := instEncoderM1.HomedAndReliable;
Data.EncoderM1.PresetConfirmationFailed := instEncoderM1.PresetConfirmationFailed;
Data.EncoderM1.HwOut                    := instEncoderM1.HwOut;
COD1_PresettTrigCmd := instEncoderM1.HwOut.PresetTriggerCmd;
COD1_CodeSeqTrigCmd := instEncoderM1.HwOut.CodeSeqTriggerCmd;
COD1_PresetValue    := instEncoderM1.HwOut.PresetValueOut;

// ── TREUIL M2 (Benne) ──
// Ordre POO : synchronisation benne, puis Homing, puis facade.

// Frontiere hardware remplie avant l'appel (le bus Hw est passe en entier).
HwInM2.RawPosIn          := HwIn.Winch.COD2_PosValue;
HwInM2.SpdValueIn        := HwIn.Winch.COD2_SpdValue;
HwInM2.AlarmsIn          := HwIn.Winch.COD2_Alarms;
HwInM2.WarningsIn        := HwIn.Winch.COD2_Warnings;
HwInM2.SlaveOperational  := instDiagEthercat.DeviceEncoderM2.Operational;
HwInM2.PresetStatusBit    := FALSE;
instEncoderM2(
    Enable                := TRUE,
    Reset                 := PRG_07_Supervision.FaultMachineReset_IHM,
    // Homing unitaire M2 (benne) : autorise en MAINT_N1/N2 quel que soit WinchSel (0/1/2).
    // L'ancien verrou croise WinchSel<>1 est retire (demande MES) : meme raisonnement que
    // M1 ci-dessus. Permet notamment le homing benne en mode benne WinchSel=2.
    HomingPermit          := (((PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.MAINT_N1 OR PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.MAINT_N2)
                               AND (MachineHomingMechanicalStopOk OR (NOT GVL_IHM.M2TreuilBenne.Cmd.BtnHomingAtZero
                                                                       AND NOT HwIn.Winch.M1M2_TopPositionFree_DI)))
                              OR instCycleMachineHoming.M2Demand.HomeReq),
    HomingAtTargetM       := GVL_IHM.M2TreuilBenne.Cmd.BtnHome
                             OR GVL_IHM.M2TreuilBenne.Cmd.BtnHomingAtZero
                             OR BucketReferenceRequested
                             OR instCycleMachineHoming.M2Demand.HomeReq,
    HomingAtZero          := GVL_IHM.M2TreuilBenne.Cmd.BtnHomingAtZero,
    ConfirmCoherence      := GVL_IHM.M2TreuilBenne.Cmd.BtnConfirmCoherence,
    CfgHomingTargetM      := SEL(GVL_IHM.M2TreuilBenne.Cmd.BtnHomingAtZero,
                                 _WinchM2CfgPersist.CfgTopSensorPos_M, 0.0),
    CfgTopSensorPosM      := _WinchM2CfgPersist.CfgTopSensorPos_M,
    UseDynamicTarget      := BucketReferenceRequested OR instCycleMachineHoming.M2Demand.UseDynamicTarget,
    DynamicHomingTargetM  := SEL(BucketReferenceRequested,
                                 instCycleMachineHoming.M2Demand.DynamicTarget_M, BucketReferenceTargetM),
    TopPositionSensor     := NOT HwIn.Winch.M1M2_TopPositionFree_DI,
    HwIn                  := HwInM2,
    PointsPerRev          := ENCODER_POINTS_PER_REV,
    CableM_PerRev         := WINCH_CABLE_M_PER_REV,
    Cfg                   := GVL_IHM.Commun.EncoderCfg,
    BypassGlobal          := GVL_IHM.M2TreuilBenne.Bypass.Global,
    Calib                 := _CalibM2
);

// 📤 Publication de la façade codeur M2 qualifiée
Data.EncoderM2.Measurement              := instEncoderM2.Measurement;
Data.EncoderM2.Ready                    := instEncoderM2.Ready;
Data.EncoderM2.Fault                    := instEncoderM2.Fault;
Data.EncoderM2.Homed                    := instEncoderM2.Homed;
Data.EncoderM2.HomingSuspect            := instEncoderM2.HomingSuspect;
Data.EncoderM2.EncoderFault             := instEncoderM2.EncoderFault;
Data.EncoderM2.HomedAndReliable         := instEncoderM2.HomedAndReliable;
Data.EncoderM2.PresetConfirmationFailed := instEncoderM2.PresetConfirmationFailed;
Data.EncoderM2.HwOut                    := instEncoderM2.HwOut;
COD2_PresettTrigCmd := instEncoderM2.HwOut.PresetTriggerCmd;
COD2_CodeSeqTrigCmd := instEncoderM2.HwOut.CodeSeqTriggerCmd;
COD2_PresetValue    := instEncoderM2.HwOut.PresetValueOut;
{endregion}

{region "§5 Retours variateur M3"}
// === ↔️ §5 RETOURS VARIATEUR M3 (décodage position migré vers PRG_05, AF-02 TBD §8 #5) ===

// 📊 Retours variateur M3 conditionnés (HwIn arbitré en §2)
Data.M3.StatusWord        := WORD_TO_UINT(HwIn.Translation.M3_StatusWord);
Data.M3.ActualFrequencyHz := HwIn.Translation.M3_ActualFrequencyHz;
{endregion}

{region "§6 Qualification globale du bus Data"}
// === 🛡️ §6 QUALIFICATION GLOBALE DU BUS DATA ===
// DataValid = TRUE uniquement si les modules E/S physiques et les bus réseaux sont opérationnels.
Data.DataValid := NOT Data.InputModules.Fault 
                  AND instDiagCanOpen.Ready 
                  AND instDiagEthercat.Ready;
{endregion}

{region "§0 Decodage position M3"}
// === 🧩 §0 DÉCODAGE POSITION M3 (migré de PRG_02, AF-02 TBD §8 #5) ===
// PRG_02_Acquisition s'exécute avant ce POU (rang 01 < 05) : HwIn.Translation est
// disponible au même scan. Le décodage des capteurs M3 est propriété de PRG_05.
instPosDecoderM3(
    SensorTremie      := PRG_02_Acquisition.HwIn.Translation.M3_PosTremie_DI,
    SensorPV          := PRG_02_Acquisition.HwIn.Translation.M3_PosPV_DI,
    SensorP2          := PRG_02_Acquisition.HwIn.Translation.M3_PosPVP2_DI,
    SensorP1          := PRG_02_Acquisition.HwIn.Translation.M3_PosP1_DI,
    SensorMaintenance := PRG_02_Acquisition.HwIn.Translation.M3_PosMaintenance_DI
);

// 📤 Publication des faits M3 dans le bus PRG_05 (consommés par PRG_07)
Data.M3_SensorWordIncoherent := instPosDecoderM3.Incoherent;
{endregion}

{region "§0 Interlock hauteur M1/M2"}
// === 🚧 §0 INTERLOCK HAUTEUR M1/M2 (risque collision translation) ===
// PRG_02_Acquisition s'exécute avant ce POU dans la MainTask (rang 01 < 05) : lecture
// du même scan, aucun retard. Bypass = maintenance consciente, doctrine ST_BypassTranslation.
// ⚠️ Une position encodeur incohérente (hors plage OU homing suspect,
// FB_Encoder_Safety) ne doit PAS pouvoir se lire comme "≥ seuil" par accident — fail-safe :
// hauteur non confirmée = interlock actif (comme une hauteur insuffisante), sauf bypass.
// 🔒 Bypass.Global NE lève PLUS cet interlock (contrairement aux autres
// causes de l'axe M3) — risque de collision jugé trop grave pour être levé par un bypass
// générique. Seul Bypass.MinHeight (dédié, conscient) lève l'anti-collision hauteur.
M3_HeightInterlockOk := GVL_IHM.M3Translation.Bypass.MinHeight
                        OR (PRG_02_Acquisition.Data.EncoderM1.HomedAndReliable
                            AND PRG_02_Acquisition.Data.EncoderM2.HomedAndReliable
                            AND (PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM >= GVL_PERSISTENT._TranslationMinHeightM1M2_M)
                            AND (PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM >= GVL_PERSISTENT._TranslationMinHeightM1M2_M));
TranslationState.HeightInterlockBlocking := NOT M3_HeightInterlockOk;

{endregion}

{region "§0bis Coupure dure limite translation"}
// === 🚧 §0bis COUPURE DURE (LimitSwitchMaintenance) — bascule sur P1 si Maintenance interdite ===
// LimitSwitchTremie/Maintenance protègent nativement Trémie/Maintenance
// (§5bis FB_Translation : coupure immédiate, sans rampe, dès que CommandedDirection insiste
// dans l'extrémité). P1/P2 n'ont aucune protection dure équivalente — seul le verrou souple
// (arrival-lock) les couvre. Quand Maintenance est interdite, la coupure dure doit protéger
// P1 comme si c'était l'extrémité réelle : mot 00001 (P1=0 ET Maintenance=1), UN CRAN AVANT
// la vraie extrémité Maintenance (00000) — backup si le verrou souple a déjà échoué à arrêter
// avant P1, garde la machine hors de la zone interdite plutôt que d'attendre le vrai fond.
M3_LimitSwitchMaintenanceEffective := SEL(PRG_03_Modes_Cycle.Data.Auth.MaintenanceM3TargetEnable,
                                   NOT instPosDecoderM3.TranslationPosP1 AND instPosDecoderM3.TranslationPosMaintenance,
                                   instPosDecoderM3.LimitSwitchMaintenance);

// 🔒 §0ter STABILISATION BISTABLE FINS DE COURSE EXTRÊMES (Trémie & Maintenance/P1)
// Maintient la détection stable à 1 même si le capteur physique vibre ou saute brièvement.
// Se libère uniquement sur un mouvement effectif dans le SENS INVERSE (dégagement).
// FdC LATCHE : un rebond capteur ne libere RIEN. On ne perd l'extreme Tremie qu'en
// commandant le SENS INVERSE (M3_ReqMaintenance_Active). (Ne pas rajouter de liberation
// sur mot capteurs : rebond 11111<->01111 -> flicker autorisation translation, REX MES.)
IF instPosDecoderM3.LimitSwitchTremie THEN
    M3_LimitSwitchTremieStable := TRUE;
ELSIF M3_ReqMaintenance_Active THEN
    M3_LimitSwitchTremieStable := FALSE;
END_IF;

// 🔒 §0quater FdC SOFT DIRECTIONNEL — APPROCHE TRÉMIE INTERDITE (trémie pleine / grille)
// Bloque UNIQUEMENT le sens trémie via EffectivePermitM3_Tremie ; le recul vers
// Maintenance/P1 reste libre (EffectivePermitM3_Maintenance non touché). N'entre PAS
// dans M3_LimitSwitchTremieStable -> l'info position / le voyant IHM « pont au FdC
// trémie » restent fidèles à la position physique. Aucun latch sur recul : dès que
// TremieFull_OR_GateRaised_DI retombe, l'approche est re-permise. Débounce 200 ms.
// Bypass N2 : LimitSwitch ou Global.
// ⚠️ Signal PAS ENCORE CÂBLÉ (ST_HwMachine) : polarité TRUE = bloqué à CONFIRMER au câblage.
TonTremieProcessBlock(
    IN := PRG_02_Acquisition.HwIn.Machine.TremieFull_OR_GateRaised_DI
          AND NOT GVL_IHM.M3Translation.Bypass.LimitSwitch
          AND NOT GVL_IHM.M3Translation.Bypass.Global,
    PT := T#200ms);
M3_TremieProcessBlock := TonTremieProcessBlock.Q;

// FdC LATCHE (idem Tremie) : rebond capteur ne libere rien. Perte de l'extreme
// Maintenance uniquement sur commande sens inverse (Tremie) ou sortie de la zone
// Maintenance en positionnement cible.
IF M3_LimitSwitchMaintenanceEffective THEN
    M3_LimitSwitchMaintenanceStable := TRUE;
ELSIF M3_ReqTremie_Active OR (PRG_03_Modes_Cycle.Data.Auth.MaintenanceM3TargetEnable AND NOT instPosDecoderM3.LimitSwitchMaintenance) THEN
    M3_LimitSwitchMaintenanceStable := FALSE;
END_IF;

// 🔒 §0quater MÉMORISATION DU DERNIER POINT ATTEINT (front → jeton unique)
// PositionDecoder n'émet qu'un front transitoire (1 cycle) par capteur, montant OU descendant
// SELON LE SENS (voir FB_Translation_PositionDecoder.st) — mémorisé ici pour
// tenir le niveau nécessaire au débounce (100ms) + verrou anti-rebond (§4ter DirectionAtArrival)
// de FB_Translation, et pour l'affichage IHM. MUTUELLEMENT EXCLUSIFS : un nouveau front RAZ tous
// les autres (jeton "dernier point franchi" unique). Libéré
// (RAZ complet) UNIQUEMENT sur mouvement CONFIRMÉ (fréquence réelle mesurée, pas juste la consigne
// de sens) soutenu ≥1.5s — pas un rebond capteur ni un changement de sens instantané.
M3_ConfirmedMoving := (UINT_TO_REAL(PRG_02_Acquisition.Data.M3.ActualFrequencyHz) / 100.0) > 0.5;
TonM3ConfirmedMoving(IN := M3_ConfirmedMoving, PT := T#1s500ms);

// RAZ jeton "at position" = changement du mot capteurs (franchissement reel), SANS
// dependance a la frequence variateur (souvent 0 au banc -> l'ancien RAZ ne se
// declenchait jamais -> jeton colle). Un franchissement qui EST une arrivee re-arme
// le bon jeton via les branches TranslationAtXxx ci-dessous (priorite sur la RAZ).
// Amorçage du mot précédent avant le premier calcul : un capteur déjà actif au
// boot n'est pas un franchissement et ne doit pas effacer la restauration.
IF NOT M3_AtPositionBootRestored THEN
    M3_SensorsWordPrev := instPosDecoderM3.SensorsWord;
END_IF;
M3_SensorsWordChanged := (instPosDecoderM3.SensorsWord <> M3_SensorsWordPrev);
M3_SensorsWordPrev := instPosDecoderM3.SensorsWord;
M3_BootRestoreApplied := FALSE;
M3_BootPositionLockTimer(IN := M3_BootPositionLock, PT := T#2s);
IF M3_BootPositionLock
   AND (M3_ConfirmedMoving OR M3_ReqTremie_Active OR M3_ReqMaintenance_Active OR M3_SensorsWordChanged OR M3_BootPositionLockTimer.Q) THEN
    M3_BootPositionLock := FALSE;
END_IF;

// Restauration sûre des jetons AtPosition : attendre que les E/S aient fourni
// le même mot capteurs pendant 500 ms. Sans cette attente, le premier cycle
// pouvait lire une valeur par défaut EtherCAT/CANopen (ex. P2), restaurer le
// mauvais jeton, puis verrouiller cette mauvaise position.
IF NOT M3_AtPositionBootRestored THEN
    IF instPosDecoderM3.SensorsWord <> M3_BootSensorsWordCandidate THEN
        M3_BootSensorsWordCandidate := instPosDecoderM3.SensorsWord;
        M3_BootSensorsStableTimer(IN := FALSE, PT := T#500ms);
    ELSE
        M3_BootSensorsStableTimer(IN := TRUE, PT := T#500ms);
    END_IF;
ELSE
    M3_BootSensorsStableTimer(IN := FALSE, PT := T#500ms);
END_IF;

// Le RETAIN n'est accepté que si le mot capteurs présent au boot est stable.
// Si le pont a bougé hors tension, aucun ancien jeton n'est réinjecté.
IF NOT M3_AtPositionBootRestored
   AND NOT M3_ConfirmedMoving
   AND NOT M3_ReqTremie_Active
   AND NOT M3_ReqMaintenance_Active
   AND M3_BootSensorsStableTimer.Q THEN
    CASE instPosDecoderM3.SensorsWord OF
        2#11111:
            M3_AtTremieStable := GVL_PERSISTENT._TranslationAtTremiePersisted OR instPosDecoderM3.TranslationPosTremie;
            M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
        2#01111:
            M3_AtPVStable := GVL_PERSISTENT._TranslationAtPVPersisted OR instPosDecoderM3.TranslationPosPV;
            M3_AtTremieStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
        2#00111:
            M3_AtP2Stable := GVL_PERSISTENT._TranslationAtP2Persisted OR instPosDecoderM3.TranslationPosP2;
            M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
        2#00011:
            M3_AtP1Stable := GVL_PERSISTENT._TranslationAtP1Persisted OR instPosDecoderM3.TranslationPosP1;
            M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtMaintenanceStable := FALSE;
        2#00000:
            M3_AtMaintenanceStable := GVL_PERSISTENT._TranslationAtMaintenancePersisted OR instPosDecoderM3.TranslationPosMaintenance;
            M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE;
    END_CASE;
    M3_AtPositionBootRestored := TRUE;
    M3_BootRestoreApplied := TRUE;
    M3_BootPositionLock := TRUE;
END_IF;

IF NOT M3_BootPositionLock AND NOT M3_BootRestoreApplied AND instPosDecoderM3.TranslationAtTremie THEN
    M3_AtTremieStable := TRUE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF NOT M3_BootPositionLock AND NOT M3_BootRestoreApplied AND instPosDecoderM3.TranslationAtPV THEN
    M3_AtPVStable := TRUE; M3_AtTremieStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF NOT M3_BootPositionLock AND NOT M3_BootRestoreApplied AND instPosDecoderM3.TranslationAtP2 THEN
    M3_AtP2Stable := TRUE; M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF NOT M3_BootPositionLock AND NOT M3_BootRestoreApplied AND instPosDecoderM3.TranslationAtP1 THEN
    M3_AtP1Stable := TRUE; M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF NOT M3_BootPositionLock AND NOT M3_BootRestoreApplied AND instPosDecoderM3.TranslationAtMaintenance THEN
    M3_AtMaintenanceStable := TRUE; M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE;
ELSIF NOT M3_BootPositionLock AND NOT M3_BootRestoreApplied AND M3_SensorsWordChanged THEN
    // Le mot capteurs a change sans que ce soit une arrivee -> on a quitte le dernier point.
    // Tremie/Maintenance EXCLUS ICI (rebond capteur) : ils suivent desormais la regle
    // bistable ci-dessous, identique et deja prouvee sur LimitSwitchTremie/MaintenanceStable §0ter.
    M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE;
END_IF;

// Bistable Tremie/Maintenance : jamais efface par un rebond capteur (mot capteurs),
// uniquement par une commande franche dans le sens inverse — meme regle, deja prouvee
// sans regression depuis 2026-09-04, que M3_LimitSwitchTremieStable/MaintenanceStable §0ter.
IF M3_ReqMaintenance_Active THEN
    M3_AtTremieStable := FALSE;
END_IF;
IF M3_ReqTremie_Active THEN
    M3_AtMaintenanceStable := FALSE;
END_IF;

// --- M3 a une position de travail : STATIQUE (mot capteurs), pas un jeton de franchissement ---
// Les jetons M3_AtXxxStable ne se posent que sur un FRONT capteur : au boot PLC, pont deja
// pose a P1 ou Maintenance sans mouvement -> jetons FALSE -> le verrou descente treuil
// (T249-A) resterait bloque jusqu'a devoir franchir un capteur. On complete donc par une
// lecture STATIQUE du mot : 00011 = zone P2->P1 (capteur P1 fait, P2 depasse) ; 00000 =
// extreme Maintenance.
// ATTENTION : 00011 couvre TOUTE la zone P2->P1 (15..20 m), pas le seul point P1. On
// n'autorise donc la lecture statique QUE si le pont est A L'ARRET et sans cible en cours,
// sinon la descente treuil serait permise pendant le transit P2->P1 (5 m). Le jeton
// M3_AtP1Stable (front) reste la voie normale quand le pont vient d'arriver.
// Information de supervision uniquement : 00011 couvre toute la zone P2->P1.
// Le verrou de descente consomme directement les jetons AtP1/AtMaintenance.
M3_AtWorkPositionStable := (NOT instPosDecoderM3.Incoherent)
    AND ( M3_AtP1Stable OR M3_AtMaintenanceStable
          OR ( (instPosDecoderM3.SensorsWord = 2#00011 OR instPosDecoderM3.SensorsWord = 2#00000)
               AND NOT M3_ConfirmedMoving
               AND NOT M3_ReqTremie_Active
               AND NOT M3_ReqMaintenance_Active ) );

// Mémorisation persistante : un mot capteurs exact et stable au repos prime
// sur le jeton RAM, qui peut avoir été perdu juste avant la coupure.
IF NOT M3_ConfirmedMoving
   AND NOT M3_ReqTremie_Active
   AND NOT M3_ReqMaintenance_Active THEN
    CASE instPosDecoderM3.SensorsWord OF
        2#11111:
            GVL_PERSISTENT._TranslationAtTremiePersisted := TRUE;
            GVL_PERSISTENT._TranslationAtPVPersisted := FALSE;
            GVL_PERSISTENT._TranslationAtP2Persisted := FALSE;
            GVL_PERSISTENT._TranslationAtP1Persisted := FALSE;
            GVL_PERSISTENT._TranslationAtMaintenancePersisted := FALSE;
        2#01111:
            GVL_PERSISTENT._TranslationAtTremiePersisted := FALSE;
            GVL_PERSISTENT._TranslationAtPVPersisted := TRUE;
            GVL_PERSISTENT._TranslationAtP2Persisted := FALSE;
            GVL_PERSISTENT._TranslationAtP1Persisted := FALSE;
            GVL_PERSISTENT._TranslationAtMaintenancePersisted := FALSE;
        2#00111:
            GVL_PERSISTENT._TranslationAtTremiePersisted := FALSE;
            GVL_PERSISTENT._TranslationAtPVPersisted := FALSE;
            GVL_PERSISTENT._TranslationAtP2Persisted := TRUE;
            GVL_PERSISTENT._TranslationAtP1Persisted := FALSE;
            GVL_PERSISTENT._TranslationAtMaintenancePersisted := FALSE;
        2#00011:
            GVL_PERSISTENT._TranslationAtTremiePersisted := FALSE;
            GVL_PERSISTENT._TranslationAtPVPersisted := FALSE;
            GVL_PERSISTENT._TranslationAtP2Persisted := FALSE;
            GVL_PERSISTENT._TranslationAtP1Persisted := TRUE;
            GVL_PERSISTENT._TranslationAtMaintenancePersisted := FALSE;
        2#00000:
            GVL_PERSISTENT._TranslationAtTremiePersisted := FALSE;
            GVL_PERSISTENT._TranslationAtPVPersisted := FALSE;
            GVL_PERSISTENT._TranslationAtP2Persisted := FALSE;
            GVL_PERSISTENT._TranslationAtP1Persisted := FALSE;
            GVL_PERSISTENT._TranslationAtMaintenancePersisted := TRUE;
        ELSE
            GVL_PERSISTENT._TranslationAtTremiePersisted := M3_AtTremieStable;
            GVL_PERSISTENT._TranslationAtPVPersisted := M3_AtPVStable;
            GVL_PERSISTENT._TranslationAtP2Persisted := M3_AtP2Stable;
            GVL_PERSISTENT._TranslationAtP1Persisted := M3_AtP1Stable;
            GVL_PERSISTENT._TranslationAtMaintenancePersisted := M3_AtMaintenanceStable;
    END_CASE;
END_IF;

{endregion}

{region "§1 Arbitrage cible et direction"}
// === 🔀 §1 ARBITRAGE DU SÉLECTEUR DE CIBLE ET DE LA DIRECTION ===

// ── Arbitrage M3 (FB_TranslationCmdArbitrationM3) ──
// Remplissage des structs d'arbitrage (champ par champ, CODESYS 3.5 refuse l'init anonyme en appel)
// 🎛️ Stimuli boutons IHM M3 : en simulation ET JoyMaster inactif, les stimuli pilotent les
// boutons IHM (SEL) ; sinon la valeur IHM réelle est conservée (jamais écrasée, producteur unique).
SimBtnIHM_Active := GVL_Simulation.SimulationModeActive AND NOT GVL_IHM.Modes.Cmd.TglJoystickMaster;
ArbM3_IHM.BtnTremie         := SEL(SimBtnIHM_Active, GVL_IHM.M3Translation.Cmd.BtnTremie, GVL_Simulation.SimBtnTremie);
ArbM3_IHM.BtnMaintenance    := SEL(SimBtnIHM_Active, GVL_IHM.M3Translation.Cmd.BtnMaintenance, GVL_Simulation.SimBtnMaintenance);
ArbM3_IHM.SelPositioning    := GVL_IHM.M3Translation.Cmd.SelPositioning;
ArbM3_IHM.SetFreq_Hz        := GVL_IHM.M3Translation.Cmd.SetFreq_Hz;
ArbM3_IHM.BypassGlobal      := GVL_IHM.M3Translation.Bypass.Global;

ArbM3_Context.HeightInterlockOk := M3_HeightInterlockOk;
ArbM3_Cfg.MaxFreq_Hz            := GVL_PERSISTENT._TranslationMaxFreq_Hz;

instArbM3(
    Enable         := TRUE,
    Joystick       := PRG_02_Acquisition.Data.Joystick,
    Auth           := PRG_03_Modes_Cycle.Data.Auth,
    ReqTranslation := PRG_03_Modes_Cycle.Data.ReqProgram.ReqTranslation,
    IHM            := ArbM3_IHM,
    TglJoystickMaster := GVL_IHM.Modes.Cmd.TglJoystickMaster,
    Context        := ArbM3_Context,
    Cfg            := ArbM3_Cfg
);
M3_PositioningActive := instArbM3.PositioningActive;
SelTarget := instArbM3.SelTarget;
M3_RunRequest_Active := instArbM3.RunRequest;
M3_ReqTremie_Active := instArbM3.ReqTremie;
M3_ReqMaintenance_Active := instArbM3.ReqMaintenance;
M3_CommandConflict := instArbM3.CommandConflict;
M3_SpeedCmd_Active := instArbM3.SpeedPct;

// Verrou independant du G7 et de l'arbitrage joystick : en SEMI_AUTO, aucune
// commande M3 ne doit survivre hors des deux etapes explicitement dediees a la
// translation. Ce veto couvre notamment AX3/AX10/AX15 (manoeuvres benne), meme
// si une demande ReqTranslation ou un etat interne restait accidentellement actif.
M3_CycleTranslationStepAuthorized :=
    (PRG_03_Modes_Cycle.Data.SequenceState.Step = E_AutoCycleStep.AX2_TRANSLATE_P1)
    OR (PRG_03_Modes_Cycle.Data.SequenceState.Step = E_AutoCycleStep.AX14_TRANSLATE_DUMP);

IF (PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.SEMI_AUTO)
   AND NOT M3_CycleTranslationStepAuthorized THEN
    M3_RunRequest_Active := FALSE;
    M3_ReqTremie_Active := FALSE;
    M3_ReqMaintenance_Active := FALSE;
    M3_SpeedCmd_Active := 0.0;
END_IF;

// InvertDirection est appliqué dans FB_Translation (InvertDriveDirection), uniquement au mot
// de commande variateur en sortie — les bits ReqTremie/ReqMaintenance restent le sens sémantique réel.

// 🩺 InputModuleFault (AF06 §3bis) : un module DI TOR hors service rend indisponibles
// les retours frein/thermique/positions du VH_0808ETP/VH_0800END portant M3 — rampe rapide.
M3_SafeStop_Active := PRG_02_Acquisition.Data.InputModules.Fault;

// En mode manuel (SelTarget=0), n'importe quel des 3 points d'arrêt (Trémie/P1/Maintenance)
// arme le verrou anti-rebond §4ter de FB_Translation (DirectionAtArrival). Mot EXACT
// (TranslationAtXxx), pas le cumulatif (TranslationPosXxx) — front franc à l'arrivée quel que
// soit le sens de venue (voir FB_Translation_PositionDecoder.st).
//
// 🎯 MÉMOIRE DE CIBLE : le code de cible n'est réécrit QUE tant qu'une demande est présente ;
// la cible publiée est ensuite le JETON du point mémorisé. La perte de la demande n'efface donc
// plus une cible déjà qualifiée : le debounce de 100 ms de FB_Translation peut se terminer et
// armer son verrou d'arrivée même si l'opérateur relâche juste après le capteur. Sans cette
// mémoire, un relâchement dans la fenêtre de debounce annulait la détection d'arrivée en cours,
// et la re-demande du même sens repartait au-delà du point. La cible retombe d'elle-même dès que
// le chariot quitte le point, les jetons M3_AtXxxStable étant uniques et exclusifs.
// La voie directionnelle reste celle du mode manuel : en SEMI_AUTO la cible d'étape est fournie
// par SelTarget (1 en AX14, 3 en AX2) et ne dépend d'aucune demande.
CASE SelTarget OF
    1: M3_TargetCodeSel := 1;
    2: M3_TargetCodeSel := 2;
    3: M3_TargetCodeSel := 3;
    4: M3_TargetCodeSel := 4;
ELSE
    IF M3_ReqTremie_Active THEN
        // En Marche Avant (+1 vers Trémie) : seule Trémie est le point d'arrêt automatique
        M3_TargetCodeSel := 1;
    ELSIF M3_ReqMaintenance_Active THEN
        // En Marche Arrière (-1 vers Maintenance) :
        // - Si Maintenance autorisée -> arrêt sur Maintenance
        // - Si Maintenance interdite -> arrêt sur P1
        IF PRG_03_Modes_Cycle.Data.Auth.MaintenanceM3TargetEnable THEN
            M3_TargetCodeSel := 4;
        ELSE
            M3_TargetCodeSel := 3;
        END_IF;
    END_IF;
END_CASE;

CASE M3_TargetCodeSel OF
    1: M3_PositionSensorTarget := M3_AtTremieStable;
    2: M3_PositionSensorTarget := M3_AtP2Stable;
    3: M3_PositionSensorTarget := M3_AtP1Stable;
    4: M3_PositionSensorTarget := M3_AtMaintenanceStable;
ELSE
    M3_PositionSensorTarget := FALSE;
END_CASE;

{endregion}

{region "§1bis Garde de mode des bypass M3"}
// 🔒 Les bypass de l'axe M3 sont actionnables UNIQUEMENT en MAINT_N2 (doctrine
// ST_BypassTranslation.st) : le bit RETAIN restauré au boot est sinon consommé sans aucune
// garde de mode. Un seul bit de fin de course neutralise TROIS barrières de l'axe — le verrou
// d'arrivée et la cause 6 de FB_Translation, et la cause 6 de FB_Safety_Translation — soit la
// neutralisation des sécurités de fin de course depuis un mode de marche nominal.
// La garde est posée AU POINT DE CONSOMMATION : le stockage RETAIN et sa restauration vers
// l'IHM ne sont pas touchés, le bit reste donc lisible et actionnable en MAINT_N2.
// Origine du mode = arbitrage FB_Modes (Auth.Mode), jamais le sélecteur IHM brut — même
// exigence que la garde des bypass treuils.
M3_MaintN2 := (PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.MAINT_N2);
{endregion}

{region "§1bis Securite M3"}
// === 🛡️ §1bis SÉCURITÉ M3 (FB_Safety_Translation, câblée en parallèle visible) ===
// ⚠️ Ordre d'appel volontaire : la safety lit ici le BrakeReleaseRequest et le
// BrakeCmd du SCAN PRÉCÉDENT d'instTranslationM3 (elle est appelée avant), soit un retard
// d'un scan. Bénin : BrakeReleaseRequest ne change pas plus vite qu'un scan MainTask 10 ms
// sur une commande frein.
instSafetyTranslationM3(
    Enable                  := (PRG_03_Modes_Cycle.Data.Auth.Mode <> E_Mode.DISABLE),
    Reset                   := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                    := PRG_03_Modes_Cycle.Data.Auth.Mode,
    JoystickOnline          := PRG_02_Acquisition.Data.Network.Joystick.Online,
    JoystickOperational     := PRG_02_Acquisition.Data.Network.Joystick.Operational,
    HeartbeatIhmOk          := GVL_IHM.Commun.HeartbeatIhmOk,
    PhaseRotationOk         := PRG_02_Acquisition.HwIn.Machine.PhaseRotationOk_DI,
    BrakeThermalFeedback    := NOT PRG_02_Acquisition.HwIn.Machine.M1_M2_M3_BrakeThermalOk_DI,
    DriveOnline             := PRG_02_Acquisition.Data.Network.DriveM3.Online,
    DriveOperational        := PRG_02_Acquisition.Data.Network.DriveM3.Operational,
    DriveStatusWord         := PRG_02_Acquisition.Data.M3.StatusWord,
    DriveActualFreqHz       := UINT_TO_REAL(PRG_02_Acquisition.Data.M3.ActualFrequencyHz) / 100.0,
    BrakeFeedback           := SEL(GVL_IHM.M3Translation.Bypass.ContactorFeedback OR GVL_IHM.M3Translation.Bypass.Global, PRG_02_Acquisition.HwIn.Translation.M3_BrakeIsOpen_DI, instTranslationM3.BrakeReleaseRequest),
    BrakeCmd                := instTranslationM3.BrakeReleaseRequest,
    RunRequest              := M3_RunRequest_Active,
    ReqTremie               := M3_ReqTremie_Active,
    ReqMaintenance          := M3_ReqMaintenance_Active,
    LimitSwitchTremie       := M3_LimitSwitchTremieStable,
    LimitSwitchMaintenance  := M3_LimitSwitchMaintenanceStable,
    SensorWordIncoherent    := instPosDecoderM3.Incoherent,
    BypassGlobal            := GVL_IHM.M3Translation.Bypass.Global,
    BypassOperatorComm      := GVL_IHM.M3Translation.Bypass.OperatorComm,
    BypassDriveComm         := GVL_IHM.M3Translation.Bypass.DriveComm,
    BypassPhaseRotation     := GVL_IHM.M3Translation.Bypass.PhaseRotation,
    BypassBrakeThermal      := GVL_IHM.M3Translation.Bypass.BrakeThermal,
    BypassMecaB             := GVL_IHM.M3Translation.Bypass.MecaB,
    BypassMecaA             := GVL_IHM.M3Translation.Bypass.MecaA,
    BypassLimitSwitch       := M3_MaintN2 AND (GVL_IHM.M3Translation.Bypass.LimitSwitch OR GVL_IHM.M3Translation.Bypass.Global),
    BypassSensorIncoherent  := GVL_IHM.M3Translation.Bypass.SensorIncoherent,
    BypassSafety            := GVL_IHM.M3Translation.Bypass.Safety,
    BypassProcess           := GVL_IHM.M3Translation.Bypass.Process
);

// SafeStop réellement appliqué au mouvement = agrégat InputModuleFault OR safety M3
// (8 mécanismes) — aucune des deux causes ne doit être perdue.
// + Verrou translation pendant le cycle de homing machine (HX2..HX6) : le chariot M3
//   ne doit pas bouger tant que M1/M2 se référencent (produit par FB_CycleMachineHoming,
//   publié PRG_02.Data.MachineHoming.M3Locked). Pas de bypass : conscient = quitter le cycle.
M3_SafeStop_Aggregate := M3_SafeStop_Active
                         OR instSafetyTranslationM3.SafeStop
                         OR PRG_02_Acquisition.Data.MachineHoming.M3Locked;

{endregion}

{region "§1ter Permis effectifs M3 (D1)"}
// === 🟢 §1ter PERMIS EFFECTIFS M3 (D1 — Phase 3) ===
// Niveau exposé à l'IHM = EFFECTIF, aligné sur les treuils M1/M2 (PRG_04 §5).
// ⚠️ Le permit est une INFORMATION DE POSSIBILITÉ de mouvement dans une direction,
// donnée AVANT l'ordre. Il reflète que l'axe est PRÊT À FONCTIONNER (pas de défaut,
// puissance, thermique) ET que la direction est physiquement possible (fins de course,
// autorisation cible). Il ne reflète PAS la commande (homme-mort) : l'homme-mort est une
// condition de COMMANDE (arbitrage FB_TranslationCmdArbitrationM3 / FB_CycleSemiAuto), pas de
// possibilité — il n'entre donc PAS dans le permit exposé.
// Pour M3, le Safety (FB_Safety_Translation) fournit les faits de sécurité :
//   - TremieLimitClear = NOT LimitSwitchTremie (direction possible vers Trémie)
//   - MaintenanceLimitClear = NOT LimitSwitchMaintenance (direction possible jusqu'à P1)
//   - SafeStop / PowerCutOff = défauts (thermique, Méca A/B, incohérence, comm, phases...)
// Le permis effectif = fait de limite libre AND NOT SafeStop AND NOT PowerCutOff
// (prêt à fonctionner), aligné sur le modèle treuils où le Safety produit déjà des
// permis gatés par les défauts. Pas de Process supplémentaire (pas de benne/Kobold).
// ⚠️ Le verrou « descente treuil interdite tant que M3 pas à P1 » (DumpAtTremieDescentLocked)
// est côté TREUIL (PRG_04 §5, lignes 802-805), pas dans le permit M3 : le permit M3 reste une
// information de possibilité de mouvement de la translation, indépendante de l'état de la trémie.
// ⚠️ Le permit M3 est un permit EFFECTIF « pouvoir bouger » (prêt à fonctionner), PAS un pur
// directionnel. Quand l'axe est en défaut (SafeStop/PowerCutOff), TOUS les sens sont bloqués ;
// au retour en condition, un sens peut être permis et pas l'autre. L'interdiction d'accès à la
// zone Maintenance ne retire PAS le permis de rejoindre P1 : elle agit sur la cible et la
// coupure dure M3_LimitSwitchMaintenanceEffective.
EffectivePermitM3_Tremie    := instSafetyTranslationM3.TremieLimitClear
                               AND NOT M3_SafeStop_Aggregate
                               AND NOT instSafetyTranslationM3.PowerCutOff
                               AND NOT M3_TremieProcessBlock;
EffectivePermitM3_Maintenance := instSafetyTranslationM3.MaintenanceLimitClear
                                  AND NOT M3_SafeStop_Aggregate
                                  AND NOT instSafetyTranslationM3.PowerCutOff;

{endregion}

{region "§2 Pilotage translation M3"}
// === ⚙️ §2 EXÉCUTION PILOTAGE TRANSLATION M3 ===

// 🔧 Assemblage de la config FB_Translation (C3) — SOURCE UNIQUE : GVL_PERSISTENT.
// Fini le double sourcing (rampes flat + vitesses d'approche via GVL_IHM.M3Translation.Cfg).
// Les 3 vitesses d'approche sont lues dans _TranslationCfgPersist (miroir persistant de
// ST_TranslationCfg, synchronisé par FB_CfgPersistBridge_TranslationCfg dans PRG_07) — la
// valeur reflète toute modification IHM persistée. Les délais (DirectionInterlockDelay,
// CaptorDebounce, BrakeDelay*, BrakeFeedbackTimeout) restent aux valeurs défaut du struct
// (non réglés IHM) — même comportement qu'avant (non câblés, défauts FB).
TranslationCfg.CfgRampAccelRate           := _TranslationRampAccelRate_Pct;
TranslationCfg.CfgRampDecelNormalRate     := _TranslationRampDecelNormal_Pct;
TranslationCfg.CfgRampDecelFastRate       := _TranslationRampDecelFast_Pct;
TranslationCfg.DriveFreqScaleMaxHz        := _TranslationMaxFreq_Hz;
TranslationCfg.ApproachSpeedTremieHz      := _TranslationCfgPersist.CfgApproachSpeedTremie_Hz;
TranslationCfg.ApproachSpeedMaintenanceHz := _TranslationCfgPersist.CfgApproachSpeedMaintenance_Hz;
TranslationCfg.ApproachSpeedP1Hz          := _TranslationCfgPersist.CfgApproachSpeedP1_Hz;

instTranslationM3(
    Enable                  := (PRG_03_Modes_Cycle.Data.Auth.Mode <> E_Mode.DISABLE),
    Reset                   := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                    := PRG_03_Modes_Cycle.Data.Auth.Mode,
    RunRequest              := M3_RunRequest_Active,
    SafeStop                := M3_SafeStop_Aggregate,
    ReqTremie               := M3_ReqTremie_Active,
    ReqMaintenance          := M3_ReqMaintenance_Active,
    InvertDriveDirection    := GVL_IHM.M3Translation.Cmd.InvertDirection,
    SpeedTgt_Pct            := M3_SpeedCmd_Active,
    PositionSensorTarget    := M3_PositionSensorTarget,
    SlowdownSensorTremie       := instPosDecoderM3.TranslationPosPV,
    // Les 5 capteurs forment un code thermomètre cumulatif depuis la Trémie (voir
    // FB_Translation_PositionDecoder.st). Chaque zone est délimitée par "capteur PRÉCÉDENT retombé
    // à 0" ET "capteur de la zone encore à 1" — zone P2→P1 = NOT PosP2 AND PosP1 (mot 00011) ;
    // zone P1→Maintenance = NOT PosP1 AND PosMaintenance (mot 00001). Zones mutuellement exclusives,
    // chacune sa propre vitesse d'approche (CfgApproachSpeedP1_Hz / CfgApproachSpeedMaintenance_Hz).
    SlowdownSensorMaintenance  := (NOT instPosDecoderM3.TranslationPosP1) AND instPosDecoderM3.TranslationPosMaintenance,
    // Ralentissement P2→P1 UNIQUEMENT si P1 est un vrai point
    // d'arrêt (zone Maintenance NON autorisée). Zone Maintenance autorisée -> 100% vitesse jusqu'à
    // P1, ralentissement seulement après (zone P1→Maintenance, SlowdownSensorMaintenance ci-dessus).
    SlowdownSensorP1           := (NOT instPosDecoderM3.TranslationPosP2) AND instPosDecoderM3.TranslationPosP1
                                   AND NOT PRG_03_Modes_Cycle.Data.Auth.MaintenanceM3TargetEnable,
    LimitSwitchTremie       := M3_LimitSwitchTremieStable,
    LimitSwitchMaintenance  := M3_LimitSwitchMaintenanceStable,
    // 🛡️ Permis directionnels SAFETY (source unique instSafetyTranslationM3) — gate de sens FB_Translation
    EffectivePermitM3_Tremie := EffectivePermitM3_Tremie,
    EffectivePermitM3_Maintenance := EffectivePermitM3_Maintenance,
    DriveStatusWord         := PRG_02_Acquisition.Data.M3.StatusWord,
    DriveActualFreqHz       := UINT_TO_REAL(PRG_02_Acquisition.Data.M3.ActualFrequencyHz) / 100.0,
    Cfg                     := TranslationCfg,
    BrakeFeedback           := SEL(GVL_IHM.M3Translation.Bypass.ContactorFeedback OR GVL_IHM.M3Translation.Bypass.Global, PRG_02_Acquisition.HwIn.Translation.M3_BrakeIsOpen_DI, instTranslationM3.BrakeReleaseRequest),
    BypassContactorCheck    := GVL_IHM.M3Translation.Bypass.Global OR GVL_IHM.M3Translation.Bypass.ContactorFeedback,
    BypassLimitSwitch       := M3_MaintN2 AND (GVL_IHM.M3Translation.Bypass.Global OR GVL_IHM.M3Translation.Bypass.LimitSwitch)
);

// 📏 Gain odométrique (T301) : réglage site |P2-PV| / (CalibFreq × CalibTime), repli sur le gain
// persistant si non saisi. La mesure P2 <-> PV est PROPOSÉE (State.OdometryMeasured*), jamais appliquée.
instOdometryGainM3(
    Enable               := (PRG_03_Modes_Cycle.Data.Auth.Mode <> E_Mode.DISABLE),
    SensorPV             := instPosDecoderM3.TranslationPosPV,
    SensorP2             := instPosDecoderM3.TranslationPosP2,
    DriveActualFreq_Hz   := TO_REAL(PRG_02_Acquisition.Data.M3.ActualFrequencyHz) / 100.0,
    PosPV_M              := GVL_PERSISTENT._TranslationPosPV_M,
    PosP2_M              := GVL_PERSISTENT._TranslationPosP2_M,
    CalibFreq_Hz         := GVL_PERSISTENT._TranslationCalibFreq_Hz,
    CalibTime_S          := GVL_PERSISTENT._TranslationCalibTimeP2PV_S,
    FallbackGain         := GVL_PERSISTENT._TranslationGainMetersPerHzSec
);

// 📐 Estimateur de position continue M3 (odométrie + recalage 5 capteurs)
instPosEstimatorM3(
    Enable               := (PRG_03_Modes_Cycle.Data.Auth.Mode <> E_Mode.DISABLE),
    Reset                := PRG_07_Supervision.FaultMachineReset_IHM,
    DriveActualFreqHz    := TO_REAL(PRG_02_Acquisition.Data.M3.ActualFrequencyHz) / 100.0,
    ReqTremie            := M3_ReqTremie_Active,
    ReqMaintenance       := M3_ReqMaintenance_Active,
    SensorMaintenance    := instPosDecoderM3.TranslationPosMaintenance,
    SensorP1             := instPosDecoderM3.TranslationPosP1,
    SensorP2             := instPosDecoderM3.TranslationPosP2,
    SensorPV             := instPosDecoderM3.TranslationPosPV,
    SensorTremie         := instPosDecoderM3.TranslationPosTremie,
    PosMaintenanceM      := GVL_PERSISTENT._TranslationPosMaintenance_M,
    PosP1M               := GVL_PERSISTENT._TranslationPosP1_M,
    PosP2M               := GVL_PERSISTENT._TranslationPosP2_M,
    PosPVM               := GVL_PERSISTENT._TranslationPosPV_M,
    PosTremieM           := GVL_PERSISTENT._TranslationPosTremie_M,
    GainMetersPerHzSec   := instOdometryGainM3.GainActive,
    PersistedPositionM   := GVL_PERSISTENT._TranslationPosEstimated_M,
    PersistedInitialized := GVL_PERSISTENT._TranslationPosEstimatedInitialized
);
// Recopie continue (reprise après reboot, doctrine _TranslationSetFreq_Hz) — pas de bridge dédié.
GVL_PERSISTENT._TranslationPosEstimated_M := instPosEstimatorM3.PositionEstimatedM;
GVL_PERSISTENT._TranslationPosEstimatedInitialized := instPosEstimatorM3.Initialized;

// === T249-B : TEXTE STATUT POSITION M3 (lecture seule IHM) ============================
// Source = jeton "at position" sur front capteur (M3_AtXxxStable, mecanisme d'origine,
// RAZ sur changement de mot capteurs). Sinon zone entre 2 capteurs via SensorsWord
// (code thermometre cumulatif). AUCUNE dependance a la frequence variateur.
IF M3_AtTremieStable THEN
    M3_StatusText := 'M3 a la Tremie';
ELSIF M3_AtMaintenanceStable THEN
    M3_StatusText := 'M3 a la Maintenance';
ELSIF M3_AtP1Stable THEN
    M3_StatusText := 'M3 a P1';
ELSIF M3_AtP2Stable THEN
    M3_StatusText := 'M3 a P2';
ELSIF M3_AtPVStable THEN
    M3_StatusText := 'M3 a PV';
ELSIF instPosDecoderM3.Incoherent THEN
    M3_StatusText := 'M3 capteurs INCOHERENTS';
ELSE
    CASE instPosDecoderM3.SensorsWord OF
        2#11111: M3_StatusText := 'M3 a la Tremie';
        2#01111: M3_StatusText := 'M3 entre Tremie et PV';
        2#00111: M3_StatusText := 'M3 entre PV et P2';
        2#00011: M3_StatusText := 'M3 entre P2 et P1';
        2#00001: M3_StatusText := 'M3 entre P1 et Maintenance';
        2#00000: M3_StatusText := 'M3 a la Maintenance';
    ELSE
        M3_StatusText := 'M3 position indeterminee';
    END_CASE;
END_IF;
// Suffixe sens de deplacement (commande active).
IF M3_ReqTremie_Active THEN
    M3_StatusText := CONCAT(M3_StatusText, ' -> Tremie');
ELSIF M3_ReqMaintenance_Active THEN
    M3_StatusText := CONCAT(M3_StatusText, ' -> Maintenance');
END_IF;

{endregion}

{region "§3 Publication demande translation"}
// === 📤 §3 PUBLICATION DEMANDE BRUTE TRANSLATION ===

TranslationFinalInterlockRequest.Enable := (PRG_03_Modes_Cycle.Data.Auth.Mode <> E_Mode.DISABLE);
TranslationFinalInterlockRequest.Reset := PRG_07_Supervision.FaultMachineReset_IHM;
TranslationFinalInterlockRequest.PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI;
TranslationFinalInterlockRequest.SafeStop := M3_SafeStop_Aggregate;
TranslationFinalInterlockRequest.PowerCutOff := instSafetyTranslationM3.PowerCutOff;
TranslationFinalInterlockRequest.EffectivePermitM3_Tremie := EffectivePermitM3_Tremie;
TranslationFinalInterlockRequest.EffectivePermitM3_Maintenance := EffectivePermitM3_Maintenance;
TranslationFinalInterlockRequest.BrakeReleaseRequest := instTranslationM3.BrakeReleaseRequest;
TranslationFinalInterlockRequest.BrakeCommandOpenConfirmed := instTranslationM3.BrakeCommandOpenConfirmed;
TranslationFinalInterlockRequest.RequestedDriveControlWord := instTranslationM3.RequestedDriveControlWord;
TranslationFinalInterlockRequest.RequestedDriveFreqHz := instTranslationM3.RequestedDriveFreqHz;
TranslationFinalInterlockRequest.ReqTremieSemantic := M3_ReqTremie_Active;

// Derniere barriere avant PRG_06 : neutralisation immediate du variateur ET du
// frein M3 hors AX2/AX14 en SEMI_AUTO. Elle reste volontairement redondante avec
// le veto amont pour qu'une rampe ou un sens memorise dans FB_Translation ne
// puisse alimenter M3 pendant une etape benne.
IF (PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.SEMI_AUTO)
   AND NOT M3_CycleTranslationStepAuthorized THEN
    TranslationFinalInterlockRequest.BrakeReleaseRequest := FALSE;
    TranslationFinalInterlockRequest.RequestedDriveControlWord := 0;
    TranslationFinalInterlockRequest.RequestedDriveFreqHz := 0.0;
    TranslationFinalInterlockRequest.ReqTremieSemantic := FALSE;
END_IF;

{endregion}

{region "§4 Publication etat IHM"}
// === 📤 PUBLICATION ÉTAT TRANSLATION IHM (lecture seule) ===
IF instTranslationM3.Fault.Error THEN
    TranslationState.FBState := E_State.ERROR;
ELSIF ABS(instTranslationM3.RequestedDriveFreqHz) > 0.1 THEN
    TranslationState.FBState := E_State.BUSY;
ELSE
    TranslationState.FBState := E_State.READY;
END_IF;
TranslationState.Ready := instTranslationM3.Ready;
TranslationState.Busy := (ABS(instTranslationM3.RequestedDriveFreqHz) > 0.1);
TranslationState.Done := instTranslationM3.TargetReached;
TranslationState.Error := instTranslationM3.Fault.Error;
TranslationState.ErrorId := instTranslationM3.Fault.ErrorId;
TranslationState.BrakeCmd := instTranslationM3.BrakeReleaseRequest;
TranslationState.BrakeCommandOpenConfirmed := instTranslationM3.BrakeCommandOpenConfirmed;
// 🔌 Retour physique direct frein M3 (même source que le SEL §1bis/§2) — consommé FB_TroubleshootingView Idx108
TranslationState.BrakeFeedback := PRG_02_Acquisition.HwIn.Translation.M3_BrakeIsOpen_DI;
TranslationState.PositionReached := instTranslationM3.TargetReached;
TranslationState.DriveControlWord := instTranslationM3.RequestedDriveControlWord;
TranslationState.DriveFreqCmd_Hz := instTranslationM3.RequestedDriveFreqHz;
// 🎯 Cohérence sim : les bits actifs/SpeedCmd_Pct n'affichent la
// consigne QUE si la commande variateur est réellement émise (RequestedDriveControlWord <> 0).
// Sinon, un interlock bloquant (hauteur, SafeStop…) laisserait l'IHM suggérer un mouvement
// qui n'a pas lieu ("je bouge mais ça bouge pas"). Affiche 0 quand c'est bloqué.
TranslationState.ActiveTremie := instTranslationM3.RequestedDriveControlWord = 1;
TranslationState.ActiveMaintenance := instTranslationM3.RequestedDriveControlWord = 2;
TranslationState.SpeedCmd_Pct := SEL(instTranslationM3.RequestedDriveControlWord <> 0, M3_SpeedCmd_Active, 0.0);
TranslationState.PositionTremie := instPosDecoderM3.TranslationPosTremie;
TranslationState.PositionPV := instPosDecoderM3.TranslationPosPV;
TranslationState.PositionP2 := instPosDecoderM3.TranslationPosP2;
TranslationState.PositionP1 := instPosDecoderM3.TranslationPosP1;
TranslationState.PositionMaintenance := instPosDecoderM3.TranslationPosMaintenance;
// Affichage IHM = M3_AtXxxStable (§0quater) — armé sur front
// (direction-dépendant), libéré sur mouvement réel confirmé ≥1.5s (pas juste un rebond capteur
// ni un changement de sens instantané). Même signal que celui consommé par M3_PositionSensorTarget.
TranslationState.AtTremie := M3_AtTremieStable;
TranslationState.AtPV := M3_AtPVStable;
TranslationState.AtP2 := M3_AtP2Stable;
TranslationState.AtP1 := M3_AtP1Stable;
TranslationState.AtMaintenance := M3_AtMaintenanceStable;
// T249-B : "at position" par PLAGE (capteur ON + estime +/-0.5 m) — fiable sans
// dependance frequence variateur, contrairement a AtXxx (front/frequence). + texte statut.
TranslationState.M3StatusText      := M3_StatusText;
TranslationState.EstimatedPosM3_M := instPosEstimatorM3.PositionEstimatedM;
// 📏 T301 — gain odométrique actif + mesure proposée P2 <-> PV (lecture seule, recopie manuelle)
TranslationState.OdometryGainActive := instOdometryGainM3.GainActive;
TranslationState.OdometryCalibValid := instOdometryGainM3.CalibValid;
TranslationState.OdometryMeasureActive := instOdometryGainM3.MeasureActive;
TranslationState.OdometryMeasuredTime_S := instOdometryGainM3.MeasuredTime_S;
TranslationState.OdometryMeasuredFreqAvg_Hz := instOdometryGainM3.MeasuredFreqAvg_Hz;
TranslationState.OdometryMeasuredFreqSpread_Hz := instOdometryGainM3.MeasuredFreqSpread_Hz;
TranslationState.OdometryMeasuredGain := instOdometryGainM3.MeasuredGain;
TranslationState.OdometryMeasureCount := instOdometryGainM3.MeasureCount;
TranslationState.SensorsWord := instPosDecoderM3.SensorsWord;
TranslationState.SensorWordIncoherent := instPosDecoderM3.Incoherent;
TranslationState.LimitSwitchTremie := M3_LimitSwitchTremieStable;
TranslationState.LimitSwitchMaintenance := M3_LimitSwitchMaintenanceStable;
TranslationState.DriveActualFreq_Hz := TO_REAL(PRG_02_Acquisition.Data.M3.ActualFrequencyHz) / 100.0;
TranslationState.DriveThermalOk := PRG_02_Acquisition.HwIn.Translation.M3_ThermalOK_DI;
// 🛡️ Pas de sortie State sur FB_TranslationOutputInterlock : le "vrai état" de la
// barrière finale M3 est dérivé de son défaut (READY normal / ERROR sur défaut barrière).
IF PRG_06_Outputs.instTranslationOutputInterlockM3.Fault.Error THEN
    TranslationState.FinalInterlockState := E_State.ERROR;
ELSE
    TranslationState.FinalInterlockState := E_State.READY;
END_IF;
TranslationState.FinalInterlockReason := PRG_06_Outputs.instTranslationOutputInterlockM3.Reason;
TranslationState.FinalInterlockError := PRG_06_Outputs.instTranslationOutputInterlockM3.Fault.Error;
TranslationState.FinalInterlockErrorId := PRG_06_Outputs.instTranslationOutputInterlockM3.Fault.ErrorId;
TranslationState.FinalBrakeTimeoutElapsed := PRG_06_Outputs.instTranslationOutputInterlockM3.BrakeTimeoutElapsed;
TranslationState.DriveCommReady := (PRG_02_Acquisition.Data.M3.StatusWord AND 16#0080) <> 0;
TranslationState.DrivePowerReady := (PRG_02_Acquisition.Data.M3.StatusWord AND 16#0001) <> 0;
TranslationState.MaintenanceTargetEnable := PRG_03_Modes_Cycle.Data.Auth.MaintenanceM3TargetEnable;
TranslationState.SimulationModeActive := GVL_Simulation.SimulationModeActive;

// 🛡️ Producteur unique (CODE_QUALITY_STANDARDS §5) : la safety M3 (instSafetyTranslationM3)
// est la source de tous les diagnostics de sécurité (ErrorLimitSwitch/ErrorSensorIncoherent).
// Les erreurs propres au mouvement (frein, variateur AC600) restent sur TranslationState.ErrorId
// ci-dessus, bitfield différent, jamais mélangé.
TranslationSafety.SafeStop := M3_SafeStop_Aggregate;
TranslationSafety.PowerCutOff := instSafetyTranslationM3.PowerCutOff;
TranslationSafety.Error := instSafetyTranslationM3.Fault.Error;
TranslationSafety.ErrorId := instSafetyTranslationM3.Fault.ErrorId;
TranslationSafety.LatchedId := instSafetyTranslationM3.Fault.LatchedId;
TranslationSafety.ErrorOperatorComm := instSafetyTranslationM3.ErrorOperatorComm;
TranslationSafety.ErrorDriveComm := instSafetyTranslationM3.ErrorDriveComm;
TranslationSafety.ErrorPhaseRotation := instSafetyTranslationM3.ErrorPhaseRotation;
TranslationSafety.ErrorBrakeThermal := instSafetyTranslationM3.ErrorBrakeThermal;
TranslationSafety.ErrorMecaB := instSafetyTranslationM3.ErrorMecaB;
TranslationSafety.ErrorMecaA := instSafetyTranslationM3.ErrorMecaA;
TranslationSafety.ErrorLimitSwitch := instSafetyTranslationM3.ErrorLimitSwitch;
TranslationSafety.ErrorSensorIncoherent := instSafetyTranslationM3.ErrorSensorIncoherent;
// 🟢 Permis directionnels M3 EFFECTIFS (D1 — Safety AND Process, §1ter) — projetés vers l'IHM
// (source safety : FB_Safety_Translation ; fusion Process en local, modèle treuils PRG_04 §5)
TranslationSafety.EffectivePermitM3_Tremie := EffectivePermitM3_Tremie;
TranslationSafety.EffectivePermitM3_Maintenance := EffectivePermitM3_Maintenance;
TranslationSafety.PowerCutOffSafety := PRG_06_Outputs.M3PowerCutOffSafetyInfo;
TranslationSafety.SafeStopSafety := PRG_06_Outputs.M3SafeStopSafetyInfo;
TranslationSafety.BlockedBySafety := PRG_06_Outputs.M3BlockedBySafetyInfo;

{region "§4bis Trace de blocage terrain M3 (ST_TraceTranslation)"}
// === ↔️ §4bis TRACE DE BLOCAGE TERRAIN M3 (cause priorisée + horodatage) ===
// Diagnostic lecture seule, publié via Data.TranslationTrace et consommé par FB_TroubleshootingView.
// L'ordre IF/ELSIF EST l'ordre de priorité (cf. E_TranslationTraceBlockReason) : la cause la plus
// grave gagne. BlockReasonTimestamp est latched au premier scan du changement (1 scan, mémoire).
// Aucune action de conduite ne dépend de ces champs.
TranslationTrace.SafeStopActive           := M3_SafeStop_Aggregate;
TranslationTrace.SafeStopSourceInput      := M3_SafeStop_Active;
TranslationTrace.SafeStopSourceSafety     := instSafetyTranslationM3.SafeStop;
TranslationTrace.PowerCutOffActive        := instSafetyTranslationM3.PowerCutOff;
TranslationTrace.HeightInterlockBlocking  := NOT M3_HeightInterlockOk;
TranslationTrace.DriveOperational         := PRG_02_Acquisition.Data.Network.DriveM3.Operational;
TranslationTrace.FinalInterlockError      := TranslationState.FinalInterlockError;
// 🟢 Permis directionnels par sens EFFECTIFS (D1 — Safety AND Process, §1ter) — reflet exact des permis appliqués
TranslationTrace.EffectivePermitM3_Tremie      := EffectivePermitM3_Tremie;
TranslationTrace.TremieProcessBlockActive      := M3_TremieProcessBlock;
TranslationTrace.EffectivePermitM3_Maintenance := EffectivePermitM3_Maintenance;

// Permis de mouvement effectif = toutes les barrières levées (agrégat diagnostic)
TranslationTrace.MotionPermitEffective := NOT M3_SafeStop_Aggregate
    AND NOT instSafetyTranslationM3.PowerCutOff
    AND M3_HeightInterlockOk
    AND PRG_02_Acquisition.Data.Network.DriveM3.Operational
    AND NOT TranslationState.FinalInterlockError
    AND NOT instTranslationM3.Fault.Error;

IF instSafetyTranslationM3.PowerCutOff THEN
    TranslationTrace.BlockReason := E_TranslationTraceBlockReason.POWER_CUTOFF;
ELSIF M3_SafeStop_Aggregate THEN
    TranslationTrace.BlockReason := E_TranslationTraceBlockReason.SAFESTOP;
ELSIF instSafetyTranslationM3.Fault.Error THEN
    TranslationTrace.BlockReason := E_TranslationTraceBlockReason.SAFETY_FAULT;
ELSIF NOT M3_HeightInterlockOk THEN
    TranslationTrace.BlockReason := E_TranslationTraceBlockReason.HEIGHT_INTERLOCK;
ELSIF NOT PRG_02_Acquisition.Data.Network.DriveM3.Operational THEN
    TranslationTrace.BlockReason := E_TranslationTraceBlockReason.DRIVE_UNAVAILABLE;
ELSIF TranslationState.FinalInterlockError THEN
    TranslationTrace.BlockReason := E_TranslationTraceBlockReason.FINAL_INTERLOCK;
ELSIF instTranslationM3.Fault.Error THEN
    TranslationTrace.BlockReason := E_TranslationTraceBlockReason.FAULT;
ELSE
    TranslationTrace.BlockReason := E_TranslationTraceBlockReason.NONE;
END_IF;
IF TranslationTrace.BlockReason <> TraceTranslation_PrevReason THEN
    TranslationTrace.BlockReasonTimestamp := TIME_TO_UDINT(TIME());
END_IF;
TraceTranslation_PrevReason := TranslationTrace.BlockReason;
{endregion}

// 🧩 Cause de blocage priorisée sur l'état public IHM (miroir de la trace terrain §4bis)
TranslationState.AxisBlockReason := TranslationTrace.BlockReason;

// === 🔌 PUBLICATION BUS INTER-PRG (Data : ST_TranslationInterPrg) ===
// Copie des structs internes vers le bus de sortie (producteur unique).
Data.TranslationFinalInterlockRequest := TranslationFinalInterlockRequest;
Data.TranslationState                 := TranslationState;
Data.TranslationSafety                := TranslationSafety;
// Arret confirme sur retour reel variateur : la consigne peut deja etre nulle
// pendant la deceleration, elle ne prouve donc pas l'arret physique de M3.
Data.TranslationBusy                  := (ABS(UINT_TO_REAL(PRG_02_Acquisition.Data.M3.ActualFrequencyHz) / 100.0) > 0.5);
Data.TranslationDone                  := instTranslationM3.TargetReached;
Data.M3_AtTremieStable                := M3_AtTremieStable;
Data.M3_AtP1Stable                    := M3_AtP1Stable;
Data.M3_AtMaintenanceStable           := M3_AtMaintenanceStable;
Data.M3_AtWorkPositionStable          := M3_AtWorkPositionStable;
// 🕵️ Trace de blocage terrain (consommée FB_TroubleshootingView)
Data.TranslationTrace                 := TranslationTrace;

{endregion}

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Encoder) ===

{region "§1 Gate"}
IF NOT Enable THEN
    RawPosOut := RawPos;
    // Comptage non evalue hors simulation : la saturation ne doit pas rester figee a TRUE.
    CountSaturated := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Injection test"}
// Injection test banc : VRAI saut de position (comme un glissement réel),
// pour tester Concept 1 / Méca E ET le rattrapage joystick (voir GVL_Simulation bandeau).
TestOffsetEdge(CLK := TestOffsetCmd);
IF TestOffsetEdge.Q THEN
    RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) + TestOffsetPts);
END_IF;
{endregion}

{region "§3 Comptage"}
// 🎚️ Vitesse simulée = interpolation linéaire du palier (palier 1 → MinSpeedMps, palier 5 → MaxSpeedMps),
// pas par pas de (Max−Min)/4. Palier 0 (arrêt) ramène au palier 1 mais aucun mouvement n'est
// appliqué tant que RelayFwd/RelayRev = FALSE (section plus bas).
EffStep  := MAX(StepNumber, 1);
SpeedMps := MinSpeedMps + (INT_TO_REAL(EffStep) - 1.0) * ((MaxSpeedMps - MinSpeedMps) / 4.0);
// Points par cycle = vitesse (m/s) × points par mètre × période tâche (s) × facteur confort.
Increment := REAL_TO_UDINT(SpeedMps * (UDINT_TO_REAL(PointsPerRev) / CableM_PerRev) * CycleTimeS * SpeedScaleFactor);
// Increment "lent" (palier 1) : vitesse du roulis inertiel apres coupure des relais.
IncrStep1 := REAL_TO_UDINT(MinSpeedMps * (UDINT_TO_REAL(PointsPerRev) / CableM_PerRev) * CycleTimeS * SpeedScaleFactor);

// Front du preset : lance la latence de referencement (le codeur réel n'est pas
// instantane — il met PresetLatencyCycles cycles a se re-referencer apres le front).
PresetEdge(CLK := PresetCmd);
IF PresetEdge.Q THEN
    PresetPending := TRUE;
    PresetCount := PresetLatencyCycles;
END_IF;

// 📐 Le comptage brut est un entier SIGNÉ 32 bits : le conteneur UDINT n'est qu'un support
// d'échange (toute la chaîne aval le relit via UDINT_TO_DINT : FB_Encoder_Scale, FB_Encoder_Homing).
// Sa valeur 0 n'est donc PAS une butée mécanique — c'est un point de passage comme un autre, et
// c'est la seule façon de rester fidèle à un codeur absolu, dont le zéro de comptage est arbitraire.
// Aucune branche de comptage ne borne donc à un littéral : seule la garde de plage §3bis intervient,
// et elle est signalée (CountSaturated).
// Pendant l'attente du preset, la position brute est conservee (le codeur n'a pas encore re-reference).
// Le mouvement est gelé pendant la latence, comme un codeur réel en cours de referencement.
IF PresetPending THEN
    IF PresetCount > 0 THEN
        PresetCount := PresetCount - 1;
    ELSE
        // Latence écoulée : applique la valeur cible du preset.
        RawPos := PresetValue;
        PresetPending := FALSE;
    END_IF;
    TargetSpeedMps := 0.0;
ELSIF RelayFwd THEN
    RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) + UDINT_TO_DINT(Increment));
    MovingDir := 1;
    CoastPtsLeft := CoastDistanceM * (UDINT_TO_REAL(PointsPerRev) / CableM_PerRev);
    TargetSpeedMps := SpeedMps;
ELSIF RelayRev THEN
    RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(Increment));
    MovingDir := -1;
    CoastPtsLeft := CoastDistanceM * (UDINT_TO_REAL(PointsPerRev) / CableM_PerRev);
    TargetSpeedMps := -SpeedMps;
ELSE
    // Relais coupes : roulis inertiel (anticipation d'arret mecanique). Le treuil
    // continue a vitesse palier 1 dans le dernier sens jusqu'a epuisement de CoastPtsLeft.
    IF (CoastPtsLeft >= 1.0) AND (MovingDir <> 0) THEN
        IF MovingDir = 1 THEN
            RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) + UDINT_TO_DINT(IncrStep1));
            TargetSpeedMps := MinSpeedMps;
        ELSE
            RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(IncrStep1));
            TargetSpeedMps := -MinSpeedMps;
        END_IF;
        CoastPtsLeft := CoastPtsLeft - UDINT_TO_REAL(IncrStep1);
    ELSE
        MovingDir := 0;
        CoastPtsLeft := 0.0;
        TargetSpeedMps := 0.0;
    END_IF;
END_IF;
{endregion}

{region "§3bis Garde de plage de comptage"}
// 🛑 SEULE borne du comptage : la plage de représentation signée. Elle est SIGNALÉE
// (CountSaturated) et cohérente — une position bornée ne publie plus de vitesse de mouvement,
// ce qui interdit la signature « position figée + vitesse non nulle + zéro défaut ».
CountSaturated := FALSE;
IF UDINT_TO_DINT(RawPos) > CST_CountTravelLimitPts THEN
    RawPos := DINT_TO_UDINT(CST_CountTravelLimitPts);
    CountSaturated := TRUE;
ELSIF UDINT_TO_DINT(RawPos) < -CST_CountTravelLimitPts THEN
    RawPos := DINT_TO_UDINT(-CST_CountTravelLimitPts);
    CountSaturated := TRUE;
END_IF;
IF CountSaturated THEN
    TargetSpeedMps := 0.0;
END_IF;
{endregion}

{region "§4 Sortie"}
RawPosOut := RawPos;
// Retour vitesse rapporte (RawSpdOut) : 1er ordre vers TargetSpeedMps. SpeedReportTauS=0.0
// -> alpha=1 -> saut instantane (comportement historique inchange).
ReportedSpeedMps := ReportedSpeedMps
    + (CycleTimeS / (SpeedReportTauS + CycleTimeS)) * (TargetSpeedMps - ReportedSpeedMps);
// Formule inverse vitesse brute EtherCAT CoE (0.1 RPM) :
// SpdValue = (V_mps * 60.0) / (0.1 * CableM_PerRev) = V_mps * 300.0 (sur tambour 2m)
IF (CableM_PerRev > 0.0) THEN
    RawSpdOut := REAL_TO_DINT((ReportedSpeedMps * 60.0) / (0.1 * CableM_PerRev) * SpeedScaleFactor);
ELSE
    RawSpdOut := 0;
END_IF;
{endregion}

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Joystick) ===

{region "§1 Gate"}
// 🔑 Initialise au neutre au premier cycle uniquement ; ensuite RawX/RawY sont pilotés
// dynamiquement par les boutons. Quand la simulation est coupée, on revient au neutre.
TimingValid := (RiseTimeS > 0.0) AND (CycleTimeS > 0.0) AND (FallTimeMs > T#0MS);
IF NOT Enable OR NOT TimingValid THEN
    FirstCycle := TRUE;
    State      := CST_ST_IDLE;
    RawX       := NeutralRaw;
    RawY       := NeutralRaw;
    RawButton  := FALSE;
    ReturningActive := FALSE; // 📊 Neutralisation : simulation inactive hors Enable
    ModelActive := FALSE;
    GestureStep := CST_GESTURE_WAIT_RELEASE;
    GestureDirection := 0;
    instArmTimer(IN := FALSE, PT := ArmHoldTime);
    instButtonReleaseTimer(IN := FALSE, PT := ButtonReleaseDelay);
    RETURN;
END_IF;
{endregion}

{region "§2 Initialisation neutre"}
IF FirstCycle THEN
    RawX       := NeutralRaw;
    RawY       := NeutralRaw;
    RawButton  := FALSE;
    State      := CST_ST_IDLE;
    FirstCycle := FALSE;
    GestureStep := CST_GESTURE_WAIT_RELEASE;
END_IF;
{endregion}

{region "§3 Pseudo-aléatoire (bruit de montée)"}
// 🎲 Compteur qui repasse à zéro, multiplié pour rester dans la plage (méthode validée).
// Le bruit s'ajoute à la rampe de montée uniquement (pas à la retombée, linéaire propre).
RandCnt := (RandCnt + 1) MOD 1000;
Noise   := (RandCnt MOD 50) - 25;   // ±25 points (≈ ±0.5% de la course)
{endregion}

{region "§4 Cibles & transitions"}
// 🎯 Un SEUL bouton impose une butée d'axe ; 0 ou ≥2 boutons = neutre (pas de diagonale implicite).
// Si OvershootActive : la cible de montée DÉPASSE la butée (MaxRaw+AMT ou 0−AMT) pour
// déclencher le défaut capteur hors plage (RawOutOfRange) — test du dépassement de valeur.
BtnCount := BOOL_TO_INT(BtnLeft_Rev_TREMIE) + BOOL_TO_INT(BtnRight_Fwd_MAINT)
          + BOOL_TO_INT(BtnFwd_Up_Close) + BOOL_TO_INT(BtnRev_Down_Open);
RequestedDirection := 0;
IF BtnCount = 1 THEN
    IF BtnLeft_Rev_TREMIE THEN RequestedDirection := CST_DIRECTION_LEFT;
    ELSIF BtnRight_Fwd_MAINT THEN RequestedDirection := CST_DIRECTION_RIGHT;
    ELSIF BtnFwd_Up_Close THEN RequestedDirection := CST_DIRECTION_FORWARD;
    ELSE RequestedDirection := CST_DIRECTION_REVERSE;
    END_IF;
END_IF;

// Un seul appui brut par geste ; aucun nouvel essai tant que l'IHM reste tenue.
instArmTimer(IN := GestureStep = CST_GESTURE_ARM, PT := ArmHoldTime);
instButtonReleaseTimer(IN := GestureStep = CST_GESTURE_MOVE, PT := ButtonReleaseDelay);
DeflectionActive := FALSE;
RawButton := FALSE;
RequestMatchesGesture := (RequestedDirection = GestureDirection) AND (BtnCount = 1);
IF BtnCount > 0 THEN ModelActive := TRUE; END_IF;
IF NOT GesturePermit THEN GestureStep := CST_GESTURE_WAIT_RELEASE; END_IF;

IF GestureStep = CST_GESTURE_WAIT_RELEASE THEN
        // Les boutons doivent etre relaches APRES stabilisation du retour.
        IF (BtnCount = 0) AND (State = CST_ST_IDLE) AND GesturePermit THEN
            GestureStep := CST_GESTURE_READY;
            ModelActive := FALSE;
        END_IF;
ELSIF GestureStep = CST_GESTURE_READY THEN
        IF BtnCount = 1 THEN
            GestureDirection := RequestedDirection;
            GestureStep := CST_GESTURE_ARM;
            RawButton := TRUE;
        ELSIF BtnCount > 1 THEN
            GestureStep := CST_GESTURE_WAIT_RELEASE;
        END_IF;
ELSIF GestureStep = CST_GESTURE_ARM THEN
        IF NOT RequestMatchesGesture THEN
            GestureStep := CST_GESTURE_WAIT_RELEASE;
        ELSE
            RawButton := TRUE;
            IF instArmTimer.Q THEN GestureStep := CST_GESTURE_MOVE; END_IF;
        END_IF;
ELSIF GestureStep = CST_GESTURE_MOVE THEN
        IF NOT RequestMatchesGesture THEN
            GestureStep := CST_GESTURE_WAIT_RELEASE;
        ELSE
            DeflectionActive := TRUE;
            RawButton := NOT instButtonReleaseTimer.Q;
        END_IF;
ELSE
    GestureStep := CST_GESTURE_WAIT_RELEASE;
END_IF;

IF DeflectionActive THEN
    IF BtnLeft_Rev_TREMIE THEN
        IF OvershootActive THEN TargetX := 0 - CST_OVERSHOOT_AMT; ELSE TargetX := 0; END_IF;
        TargetY := NeutralRaw; ActiveAxis := 1;
    ELSIF BtnRight_Fwd_MAINT THEN
        IF OvershootActive THEN TargetX := MaxRaw + CST_OVERSHOOT_AMT; ELSE TargetX := MaxRaw; END_IF;
        TargetY := NeutralRaw; ActiveAxis := 1;
    ELSIF BtnFwd_Up_Close THEN
        TargetX := NeutralRaw;
        IF OvershootActive THEN TargetY := MaxRaw + CST_OVERSHOOT_AMT; ELSE TargetY := MaxRaw; END_IF;
        ActiveAxis := 2;
    ELSE
        TargetX := NeutralRaw;
        IF OvershootActive THEN TargetY := 0 - CST_OVERSHOOT_AMT; ELSE TargetY := 0; END_IF;
        ActiveAxis := 2;
    END_IF;
    State := CST_ST_RISE;
ELSE
    // 0 ou ≥2 boutons : retour au neutre.
    TargetX := NeutralRaw;
    TargetY := NeutralRaw;
    IF State = CST_ST_RISE THEN
        // Front de relâchement : retour au neutre. D'abord retombée linéaire (FALL),
        // puis petit bagotement de quelques % autour du neutre si OvershootActive (voir §6).
        State := CST_ST_FALL;
    END_IF;
END_IF;
{endregion}

{region "§5 Ascending (rampe + bruit)"}
IF State = CST_ST_RISE THEN
    // Pas de montée : pleine course (MaxRaw−NeutralRaw) en RiseTimeS.
    RiseStep := INT_TO_REAL(MaxRaw - NeutralRaw) / (RiseTimeS / CycleTimeS);
    // Axe X
    IF RawX < TargetX THEN
        RawX := MIN(RawX + REAL_TO_INT(RiseStep) + Noise, TargetX);
    ELSIF RawX > TargetX THEN
        RawX := MAX(RawX - REAL_TO_INT(RiseStep) - Noise, TargetX);
    END_IF;
    // Axe Y
    IF RawY < TargetY THEN
        RawY := MIN(RawY + REAL_TO_INT(RiseStep) + Noise, TargetY);
    ELSIF RawY > TargetY THEN
        RawY := MAX(RawY - REAL_TO_INT(RiseStep) - Noise, TargetY);
    END_IF;
END_IF;
{endregion}

{region "§6 Retombée linéaire (sans bagotement)"}
IF State = CST_ST_FALL THEN
    // Pas de retombée : pleine course en FallTimeMs (TIME_TO_REAL → ms, /1000 → s).
    FallStep := INT_TO_REAL(MaxRaw - NeutralRaw) / (TIME_TO_REAL(FallTimeMs) / 1000.0 / CycleTimeS);
    IF RawX < NeutralRaw THEN
        RawX := MIN(RawX + REAL_TO_INT(FallStep), NeutralRaw);
    ELSIF RawX > NeutralRaw THEN
        RawX := MAX(RawX - REAL_TO_INT(FallStep), NeutralRaw);
    END_IF;
    IF RawY < NeutralRaw THEN
        RawY := MIN(RawY + REAL_TO_INT(FallStep), NeutralRaw);
    ELSIF RawY > NeutralRaw THEN
        RawY := MAX(RawY - REAL_TO_INT(FallStep), NeutralRaw);
    END_IF;
    IF RawX = NeutralRaw AND RawY = NeutralRaw THEN
        // Arrivée au neutre : si bagotement demandé, lance un petit balancement de quelques %.
        IF BagotementActive THEN
            State := CST_ST_OVERSHOOT;
            IF ActiveAxis = 1 THEN
                OscDev := INT_TO_REAL(CST_BAGOT_AMT);
            ELSE
                OscDev := INT_TO_REAL(CST_BAGOT_AMT);
            END_IF;
            OscVel := 0.0;
        ELSE
            State := CST_ST_IDLE;
        END_IF;
    END_IF;
END_IF;
{endregion}

{region "§7 Bagotement (dépassement + oscillations amorties)"}
IF State = CST_ST_OVERSHOOT THEN
    // 🎢 Oscillateur harmonique amorti discret (semi-implicite) autour du neutre :
    // le joystick dépasse le centre (~12% de l'écart initial) puis oscille 1-2 fois
    // avant de se stabiliser — comportement d'un opérateur qui relâche et balance.
    OscAcc := -CST_OSC_K * OscDev - CST_OSC_C * OscVel;
    OscVel := OscVel + OscAcc;
    OscDev := OscDev + OscVel;
    IF ActiveAxis = 1 THEN
        RawX := NeutralRaw + REAL_TO_INT(OscDev);
    ELSE
        RawY := NeutralRaw + REAL_TO_INT(OscDev);
    END_IF;
    // Stabilisé : revient exactement au centre.
    IF ABS(OscDev) < 1.0 AND ABS(OscVel) < 1.0 THEN
        State := CST_ST_IDLE;
        IF ActiveAxis = 1 THEN
            RawX := NeutralRaw;
        ELSE
            RawY := NeutralRaw;
        END_IF;
    END_IF;
END_IF;
{endregion}

{region "§8 Homme-mort brut + drapeau retour"}
// RawButton est exclusivement produit par le sequenceur du geste (§4).
// Drapeau "retour dynamique en cours" : TRUE si l'état est FALL ou OVERSHOOT (retombée/bagotement).
// Permet à FB_SimBench d'émettre la sortie du modèle même après relâchement du bouton.
ReturningActive := (State = CST_ST_FALL) OR (State = CST_ST_OVERSHOOT);
{endregion}

// === IMPLEMENTATION ===
{region "§1 Gate"}
IF NOT Enable THEN
    SimChainOk     := FALSE;
    SimContactorOk := FALSE;
    SimPhaseRotationOk := FALSE;
    ContactorLatch := FALSE;
    ChainOpen      := TRUE; // Chaîne ouverte par défaut à la ré-entrée (on n'a pas armé)
    ChainOpenReq   := FALSE;
    ContactorEngageReq := FALSE;
    TonChainOpen(IN := FALSE);
    TonChainClose(IN := FALSE);
    TonContactorEngage(IN := FALSE);
    TonContactorDrop(IN := FALSE);
    RETURN;
END_IF;
{endregion}

{region "§2 Chaîne AU (contrôle granulaire + dynamique)"}
// 1. La chaîne AU est saine si l'opérateur la simule fermée (SimChainOkBit = TRUE) ET si aucun
//    événement ne l'ouvre : coup-de-poing (BtnEmergencyStop), test de redondance (TestCutActive),
//    coupure métier (PowerCutOffRequest).
// 🔧 DEADLOCK SIMULATION (corrigé) : la chaîne n'est PAS fermée par défaut ni dépendante de
//    PowerCutOff_A/B (qui sont dans le cercle). Elle est fermée UNIQUEMENT par le bit opérateur
//    `SimChainOkBit`. Le réarmement après échec de test de redondance (RedundancyTestFailedCause laté
//    → PowerCutOff_A=FALSE) reste possible car la chaîne est maintenue fermée par le bit, pas par
//    le PLC. Hors simulation (Enable=FALSE), la chaîne reste pilotée par le matériel via le repli
//    HwReal (PRG_02 §1/§2) — aucune régression sécurité réelle.
// 🆕 DYNAMIQUE : l'ouverture/fermeture suit une temporisation (CST_ChainOpenDelay / CST_ChainCloseDelay)
//    qui simule le temps de retombée des relais AU, tout en restant < 200ms (CST_TestDuration) pour
//    ne pas fausser le test de redondance. Pendant le test, la chaîne clignote (s'ouvre en TEST_A/B,
//    se referme en RESTORE_A/B) puis revient à 1.
ChainOpenReq := (NOT SimChainOkBit) OR BtnEmergencyStop OR TestCutActive OR PowerCutOffRequest;

// Temporisation d'ouverture : la chaîne s'ouvre après CST_ChainOpenDelay de demande soutenue
TonChainOpen(IN := ChainOpenReq, PT := CST_ChainOpenDelay);
// Temporisation de fermeture : la chaîne se ferme après CST_ChainCloseDelay d'absence de demande
TonChainClose(IN := NOT ChainOpenReq, PT := CST_ChainCloseDelay);

// Latch de la chaîne avec temporisations (défaut = ouverte à la ré-entrée)
IF ChainOpenReq THEN
    IF TonChainOpen.Q THEN
        ChainOpen := TRUE;
    END_IF;
ELSE
    IF TonChainClose.Q THEN
        ChainOpen := FALSE;
    END_IF;
END_IF;

SimChainOk := NOT ChainOpen;
{endregion}

{region "§3 Auto-maintien contacteur (dynamique réaliste)"}
// 2. Logique d'auto-maintien (latch) du contacteur avec priorité à la coupure.
// 🆕 DYNAMIQUE : le contacteur ne s'engage QUE pendant l'impulsion d'armement (EmergencyArming)
//    tant que la chaîne est saine, après CST_ContactorEngageDelay (temps de collage bobine), puis
//    s'auto-maintient. Il retombe après CST_ContactorDropDelay (temps de décollage bobine) dès que
//    la chaîne s'ouvre — comme une bobine réelle qui décolle sans alimentation. Ces temporisations
//    restent < CST_ArmingPulseDuration (1s) et CST_ArmingConfirmTimeout (2s) pour que la
//    confirmation contacteur reste validée. À la ré-entrée en simulation, le contacteur est NON
//    engagé (on n'a pas armé).
ContactorEngageReq := EmergencyArming AND SimChainOk;

// Temporisation d'engagement : le contacteur se colle après CST_ContactorEngageDelay de pulse soutenu
TonContactorEngage(IN := ContactorEngageReq, PT := CST_ContactorEngageDelay);
// Temporisation de retombée : le contacteur décolle après CST_ContactorDropDelay de chaîne ouverte
TonContactorDrop(IN := NOT SimChainOk, PT := CST_ContactorDropDelay);

// Latch du contacteur avec priorité à la coupure (retombée > engagement)
IF NOT SimChainOk THEN
    IF TonContactorDrop.Q THEN
        ContactorLatch := FALSE;
    END_IF;
ELSIF ContactorEngageReq THEN
    IF TonContactorEngage.Q THEN
        ContactorLatch := TRUE;
    END_IF;
END_IF;

// Recopie vers la sortie
SimContactorOk := ContactorLatch;

// Contrôleur de phases : simple propagation du bit opérateur (TRUE = sain).
// Inopérant hors simulation (le banc ne publie l'image machine que sous Enable).
SimPhaseRotationOk := SimPhaseRotationOkBit;
{endregion}

// === §1 GATE NEUTRALISATION ===
IF NOT Enable THEN
    Ready := FALSE;
    MotorTorque_Nm := 0.0;
    ResistiveTorqueAct_Nm := 0.0;
    Slip_Ratio := 0.0;
    SpeedAct_Rpm := 0.0;
    IsStalled := FALSE;
    IsGeneratorMode := FALSE;
    LoadFracFiltered_Ratio := 0.0;
    RETURN;
END_IF;

// === §2 CHARGE LISSEE (benne au sol force la cible a 0, transition sans a-coup) ===
IF IsBucketGrounded THEN
    LoadFracTarget_Ratio := 0.0;
ELSE
    LoadFracTarget_Ratio := LIMIT(0.0, LoadFrac_Ratio, 1.0);
END_IF;

IF LoadTransitionFilter_S > CST_MinFilterTime_S THEN
    FilterAlpha_Ratio := CycleTime_S / (LoadTransitionFilter_S + CycleTime_S);
ELSE
    FilterAlpha_Ratio := 1.0;
END_IF;
LoadFracFiltered_Ratio := LoadFracFiltered_Ratio
    + FilterAlpha_Ratio * (LoadFracTarget_Ratio - LoadFracFiltered_Ratio);

// === §3 COUPLAGE M1/M2 ===
// En mode couple, la benne lie mecaniquement les deux treuils : un ecart de couple entre pairs
// se traduit en effort differentiel de rattrapage (proportionnel a l'ecart de vitesse), pas en
// deux dynamiques d'inertie totalement independantes qui divergent librement.
IF IsCoupledToPeer THEN
    PeerDifferentialTorque_Nm := CoupledPeerGain_Ratio * (SpeedAct_Rpm - PeerSpeed_Rpm)
        * LoadNominalTorque_Nm / MAX(SynchronousSpeed_Rpm, 1.0);
ELSE
    PeerDifferentialTorque_Nm := 0.0;
END_IF;

// === §4 COUPLE RESISTANT APPLIQUE ===
ResistiveTorqueAct_Nm := LoadFrictionTorque_Nm
    + DirectionCmd * LoadFracFiltered_Ratio * LoadNominalTorque_Nm
    + PeerDifferentialTorque_Nm;

// === §5 MOTEUR ELEMENTAIRE ===
Motor(
    Enable := TRUE,
    StepCmd := StepCmd,
    DirectionCmd := DirectionCmd,
    NetworkVoltageAct_V := NetworkVoltageAct_V,
    ResistiveTorque_Nm := ResistiveTorqueAct_Nm,
    NetworkVoltageNom_V := NetworkVoltageNom_V,
    MaxTorque_Nm := MaxTorque_Nm,
    SlipAtMaxTorqueBase_Ratio := SlipAtMaxTorqueBase_Ratio,
    RotorResistanceOwn_Ohm := RotorResistanceOwn_Ohm,
    Inertia_KgM2 := Inertia_KgM2,
    SynchronousSpeed_Rpm := SynchronousSpeed_Rpm,
    CycleTime_S := CycleTime_S
);

MotorTorque_Nm := Motor.MotorTorque_Nm;
Slip_Ratio := Motor.Slip_Ratio;
SpeedAct_Rpm := Motor.SpeedAct_Rpm;
IsStalled := Motor.IsStalled;
IsGeneratorMode := Motor.IsGeneratorMode;

Ready := TRUE;

{region "§1 Acquisition temps"}
// 1. ACQUISITION DU TEMPS SYSTÈME
TimeCurrent := TIME();
{endregion}

{region "§2 Initialisation"}
// 2. INITIALISATION UNIQUE AU PREMIER CYCLE
IF NOT InitDone THEN
    TimeLast := TimeCurrent;
    InitDone := TRUE;
    CycleTimeS := DefaultValueS;
    RETURN;
END_IF;
{endregion}

{region "§3 Calcul delta"}
// 3. CALCUL DU DELTA EN MILLISECONDES
DeltaTimeMs := TIME_TO_UDINT(TimeCurrent - TimeLast);
{endregion}

{region "§4 Conversion, secours et bornage"}
// 4. CONVERSION EN SECONDES, AVEC DOUBLE BORNAGE DU DELTA
//
// TIME() est un compteur systeme 32 bits en millisecondes depuis le demarrage de
// l'automate. Il n'est PAS absolu : il reboucle a 0 tous les 2^32 ms (~49,7 jours).
// La soustraction TimeCurrent - TimeLast est modulo 2^32 : au passage du rebouclage,
// tant que l'ecart reel entre deux scans reste < 49,7 j (toujours vrai a 10 ms),
// DeltaTimeMs reste correct. Le rebouclage seul n'est donc pas le risque principal.
//
// Le vrai risque est un DeltaTimeMs REELLEMENT > CST_MaxCycleDeltaMs : reprise apres
// un online-change, sortie d'un point d'arret / pas-a-pas debug, ou fenetre du
// rebouclage TIME(). Le chien de garde tache (200 ms, sensibilite 1) borne deja les
// gels en fonctionnement ; ce plafond couvre les cas hors surveillance.
// Un dt aberrant publie tel quel donnerait un CycleTimeS enorme, propage en un seul
// scan dans les rampes de vitesse et les integrateurs de position/frein -> saut
// physique. Fail-safe : hors de la plage nominale (0 < dt <= plafond), on publie la
// valeur de secours DefaultValueS au lieu de l'artefact. Pas de redemarrage auto.
//
// Borne basse dt = 0 (anti-zero, ex. premier appel du scan) et borne haute
// dt > CST_MaxCycleDeltaMs (anti-artefact) partagent la meme branche de secours.
IF (DeltaTimeMs > 0) AND (DeltaTimeMs <= CST_MaxCycleDeltaMs) THEN
    CycleTimeS := UDINT_TO_REAL(DeltaTimeMs) / 1000.0;
ELSE
    CycleTimeS := DefaultValueS;
END_IF;
{endregion}

{region "§5 Archivage"}
// 5. ARCHIVAGE POUR LE PROCHAIN CYCLE
TimeLast := TimeCurrent;
{endregion}

IF NOT Enable THEN
    Initialized := FALSE;
    RawDetected := FALSE;
    ElectricalOutput := FALSE;
    PreviousRawDetected := FALSE;
    EpisodeActive := FALSE;
    BlipActive := FALSE;
    BlipRunning := FALSE;
    BlipTimerS := 0.0;
    BlipCount := 0;
    DelayTimerS := 0.0;
    EpisodeTimerS := 0.0;
    ToggleTimerS := 0.0;
    TransitionCount := 0;
    EpisodeTogglePeriodS := 0.0;
    RETURN;
END_IF;

(* Hysteresis sur une frontiere cumulative : les cinq DI restent compatibles avec
   le mot thermometre du decodeur M3, contrairement a cinq fenetres independantes. *)
IF NOT Initialized THEN
    IF ActiveBelowThreshold THEN
        RawDetected := Position_M <= Threshold_M;
    ELSE
        RawDetected := Position_M >= Threshold_M;
    END_IF;
    ElectricalOutput := RawDetected;
    PreviousRawDetected := RawDetected;
    RandomState := ScenarioSeed MOD 1000000;
    IF RandomState = 0 THEN
        RandomState := 1;
    END_IF;
    EpisodeTogglePeriodS := MAX(0.01, IntermittencePeriodS);
    Initialized := TRUE;
    RETURN;
END_IF;

IF ActiveBelowThreshold THEN
    IF RawDetected THEN
        RawDetected := Position_M <= (Threshold_M + MAX(0.0, Hysteresis_M));
    ELSE
        RawDetected := Position_M <= (Threshold_M - MAX(0.0, Hysteresis_M));
    END_IF;
ELSE
    IF RawDetected THEN
        RawDetected := Position_M >= (Threshold_M - MAX(0.0, Hysteresis_M));
    ELSE
        RawDetected := Position_M >= (Threshold_M + MAX(0.0, Hysteresis_M));
    END_IF;
END_IF;

(* Un episode est declenche par un franchissement mecanique, pas par une de ses
   propres bascules electriques. Les fronts restent donc bornes et reproductibles. *)
IF RawDetected <> PreviousRawDetected THEN
    PreviousRawDetected := RawDetected;
    EpisodeTarget := RawDetected;
    (* Une bascule mecanique pendant l'episode modifie seulement la cible finale.
       Elle ne remet jamais son chronometre a zero : l'episode reste borne. *)
    IF NOT EpisodeActive THEN
        DelayTimerS := 0.0;
        EpisodeTimerS := 0.0;
        ToggleTimerS := 0.0;
        (* Tirage unique par episode : reproductible pour une graine et sans bruit
           blanc scan-par-scan. La periode varie de 70 % a 130 % du nominal. *)
        RandomState := RandomState + 7919;
        IF RandomState >= 1000000 THEN
            RandomState := RandomState - 1000000;
        END_IF;
        EpisodeTogglePeriodS := MAX(0.01, IntermittencePeriodS
            * (0.7 + UDINT_TO_REAL(RandomState MOD 6000) / 10000.0));
        EpisodeActive := IntermittenceActive AND (IntermittenceDurationS > 0.0);
    END_IF;
    (* Blip court : arme sur le meme front MECANIQUE. Ses propres bascules electriques ne
       peuvent donc jamais le rearmer — meme protection que l'episode d'intermittence. *)
    IF (BlipTransitions > 0) AND (BlipDurationS > 0.0) THEN
        BlipRunning := TRUE;
        BlipTimerS := 0.0;
        BlipCount := 0;
        BlipActive := TRUE;
        (* Ecretage : au-dela de ce plafond, un compteur UDINT pourrait reboucler et rendre
           le blip non terminant (revue du 2026-09-20, F9). *)
        BlipTransitions := MIN(BlipTransitions, CST_BlipMaxTransitions);
    END_IF;
END_IF;

IF BlipRunning THEN
    (* Protocole du blip court : (0) la sortie rejoint d'abord l'etat MECANIQUE — le
       comportement nominal reste donc visible ; puis une excursion contradictoire toutes
       les BlipDurationS, donc de largeur BlipDurationS ; enfin la sortie est rendue a
       l'etat mecanique. Nombre d'excursions = BlipTransitions. *)
    BlipTimerS := BlipTimerS + CycleTimeS;
    IF BlipTimerS >= MAX(CycleTimeS, BlipDurationS) THEN
        BlipTimerS := 0.0;
        IF BlipCount = 0 THEN
            IF ElectricalOutput <> RawDetected THEN
                ElectricalOutput := RawDetected;
                TransitionCount := TransitionCount + 1;
            END_IF;
            BlipCount := 1;
        ELSIF BlipCount <= BlipTransitions THEN
            ElectricalOutput := NOT ElectricalOutput;
            TransitionCount := TransitionCount + 1;
            BlipCount := BlipCount + 1;
        ELSE
            BlipRunning := FALSE;
            BlipActive := FALSE;
            IF ElectricalOutput <> RawDetected THEN
                ElectricalOutput := RawDetected;
                TransitionCount := TransitionCount + 1;
            END_IF;
            DelayTimerS := 0.0;
        END_IF;
    END_IF;
ELSIF EpisodeActive THEN
    EpisodeTimerS := EpisodeTimerS + CycleTimeS;
    ToggleTimerS := ToggleTimerS + CycleTimeS;
    IF ToggleTimerS >= EpisodeTogglePeriodS THEN
        ElectricalOutput := NOT ElectricalOutput;
        ToggleTimerS := 0.0;
        TransitionCount := TransitionCount + 1;
    END_IF;
    IF EpisodeTimerS >= IntermittenceDurationS THEN
        EpisodeActive := FALSE;
        IF ElectricalOutput <> EpisodeTarget THEN
            ElectricalOutput := EpisodeTarget;
            TransitionCount := TransitionCount + 1;
        END_IF;
        DelayTimerS := 0.0;
    END_IF;
ELSIF ElectricalOutput <> RawDetected THEN
    DelayTimerS := DelayTimerS + CycleTimeS;
    IF DelayTimerS >= MAX(0.0, ElectricalDelayS) THEN
        ElectricalOutput := RawDetected;
        DelayTimerS := 0.0;
        TransitionCount := TransitionCount + 1;
    END_IF;
ELSE
    DelayTimerS := 0.0;
END_IF;

IF NOT Enable THEN
    Ready := FALSE;
    Angle_Rad := 0.0;
    AngularVelocity_RadPerS := 0.0;
    VelocityReaction_Mps := 0.0;
    RETURN;
END_IF;

VelocityReaction_Mps := 0.0;
IF Length_M > CST_MinLength_M THEN
    AngularAccel_RadPerS2 := -(CST_Gravity_Mps2 / Length_M) * Angle_Rad
        - MAX(0.0, Damping) * AngularVelocity_RadPerS
        - CartAcceleration_Mps2 / Length_M;
    AngularVelocity_RadPerS := LIMIT(-CST_MaxAngularVelocity_RadPerS,
        AngularVelocity_RadPerS + AngularAccel_RadPerS2 * CycleTime_S, CST_MaxAngularVelocity_RadPerS);
    Angle_Rad := LIMIT(-CST_MaxAngle_Rad, Angle_Rad + AngularVelocity_RadPerS * CycleTime_S,
        CST_MaxAngle_Rad);
    IF BrakeMechanicallyOpen THEN
        VelocityReaction_Mps := ReactionGain_Mps2 * Angle_Rad * CycleTime_S;
    END_IF;
END_IF;
Ready := TRUE;

IF NOT Enable THEN
    Ready := FALSE;
    CoilEnergized := FALSE;
    MechanicallyOpen := FALSE;
    ContactOpen := FALSE;
    FaultCloseActive := FALSE;
    MechanicalTimer_S := 0.0;
    ContactTimer_S := 0.0;
    FaultTimer_S := 0.0;
    RETURN;
END_IF;

(* Faute explicite : chronometre propre, remis a zero des que le stimulus retombe. *)
IF FaultCloseWhileRunning THEN
    FaultTimer_S := FaultTimer_S + CycleTime_S;
ELSE
    FaultTimer_S := 0.0;
END_IF;
FaultCloseActive := FaultCloseWhileRunning AND (FaultTimer_S >= MAX(0.0, FaultCloseDelay_S));

(* La faute fait retomber la bobine : l'etat electrique publie reste coherent avec la
   fermeture mecanique observee (jamais « bobine energisee ET frein serre »). *)
CoilEnergized := ReleaseCmd AND NOT FaultCloseActive;
IF CoilEnergized THEN
    IF NOT MechanicallyOpen THEN
        MechanicalTimer_S := MechanicalTimer_S + CycleTime_S;
        IF MechanicalTimer_S >= MAX(0.0, OpenDelay_S) THEN
            MechanicallyOpen := TRUE;
            MechanicalTimer_S := 0.0;
        END_IF;
    ELSE
        MechanicalTimer_S := 0.0;
    END_IF;
ELSIF FaultCloseActive OR (ActualFrequency_Hz <= CST_StopFrequency_Hz) THEN
    IF MechanicallyOpen THEN
        MechanicalTimer_S := MechanicalTimer_S + CycleTime_S;
        IF MechanicalTimer_S >= MAX(0.0, CloseDelay_S) THEN
            MechanicallyOpen := FALSE;
            MechanicalTimer_S := 0.0;
        END_IF;
    ELSE
        MechanicalTimer_S := 0.0;
    END_IF;
ELSE
    MechanicalTimer_S := 0.0;
END_IF;
IF MechanicallyOpen <> ContactOpen THEN
    ContactTimer_S := ContactTimer_S + CycleTime_S;
    IF ContactTimer_S >= MAX(0.0, ContactDelay_S) THEN
        ContactOpen := MechanicallyOpen;
        ContactTimer_S := 0.0;
    END_IF;
ELSE
    ContactTimer_S := 0.0;
END_IF;
Ready := TRUE;

IF NOT Enable THEN
    Ready := FALSE;
    FrequencyCmd_Hz := 0.0;
    ElectricalFrequency_Hz := 0.0;
    ActualFrequency_Hz := 0.0;
    ResponseAlpha := 0.0;
    RETURN;
END_IF;

FrequencyDelta_Hz := LIMIT(0.0, FrequencyTgt_Hz, CST_MaxFrequency_Hz) - FrequencyCmd_Hz;
IF FrequencyDelta_Hz >= 0.0 THEN
    FrequencyStep_Hz := MAX(0.0, AccelRate_HzPerS) * CycleTime_S;
ELSE
    FrequencyStep_Hz := MAX(0.0, DecelRate_HzPerS) * CycleTime_S;
END_IF;
FrequencyCmd_Hz := FrequencyCmd_Hz + LIMIT(-FrequencyStep_Hz, FrequencyDelta_Hz, FrequencyStep_Hz);
IF TimeConstant_S > CST_MinTime_S THEN
    ResponseAlpha := CycleTime_S / (TimeConstant_S + CycleTime_S);
ELSE
    ResponseAlpha := 1.0;
END_IF;
ElectricalFrequency_Hz := ElectricalFrequency_Hz
    + ResponseAlpha * (FrequencyCmd_Hz - ElectricalFrequency_Hz);
ActualFrequency_Hz := MAX(0.0, ElectricalFrequency_Hz
    - MAX(0.0, LoadFrequencyDroopGain_Hz) * ABS(LoadAngularVelocity_RadPerS));
IF ActualFrequency_Hz < 0.005 THEN
    ActualFrequency_Hz := 0.0;
END_IF;
Ready := TRUE;

// Sorties impulsionnelles : FALSE par defaut, TRUE pendant un seul scan.
ResetPulse := FALSE;
Cancelled := FALSE;

IF NOT Enable THEN
    SequenceActive := FALSE;
    Lockout := FALSE;
    Phase := 0;
    AttemptCount := 0;
    State := 0;
    StartupStarted := FALSE;
    RearmStarted := FALSE;
    RearmPending := FALSE;
    PendingPhase := 0;
    StabilizationTimer(IN := FALSE);
    InterAttemptTimer(IN := FALSE);
    PowerRearmEdge(CLK := FALSE);
    RETURN;
END_IF;

MaxAttemptsEffective := Cfg_MaxAttempts;
IF MaxAttemptsEffective < 1 THEN MaxAttemptsEffective := 1; END_IF;
IF MaxAttemptsEffective > 3 THEN MaxAttemptsEffective := 3; END_IF;

SafeCommon := EmergencyChainClosed AND NOT PowerCutOffActive AND NOT MotionActive;
PowerRearmEdge(CLK := PowerContactorEngaged);

// Le front contacteur ne peut armer qu une seule salve. Une retombee rearme
// uniquement la detection du prochain cycle de puissance.
IF NOT PowerContactorEngaged THEN
    RearmStarted := FALSE;
    RearmPending := FALSE;
END_IF;

// Si le contacteur revient pendant la sequence startup, memoriser le front :
// le rearmement sera traite apres la fin de la sequence startup, jamais perdu.
IF PowerRearmEnable AND PowerRearmEdge.Q AND (State <> 0) AND (State <> 4) THEN
    RearmPending := TRUE;
END_IF;

// Priorite au demarrage CPU. Le contacteur doit etre au repos pour cette phase.
IF (State = 0) AND StartupEnable AND NOT StartupStarted AND SafeCommon AND NOT PowerContactorEngaged THEN
    StartupStarted := TRUE;
    PendingPhase := 1;
    AttemptCount := 0;
    Lockout := FALSE;
    State := 1;
END_IF;

// La phase post-rearmement est declenchee exclusivement sur le front du retour
// contacteur et ne peut pas etre confondue avec le demarrage CPU.
IF (State = 0 OR State = 4) AND PowerRearmEnable AND PowerRearmEdge.Q AND NOT RearmStarted THEN
    RearmStarted := TRUE;
    IF SafeCommon AND PowerContactorEngaged THEN
        PendingPhase := 2;
        AttemptCount := 0;
        Lockout := FALSE;
        State := 2;
    ELSE
        Lockout := TRUE;
        Cancelled := TRUE;
        Phase := 3;
    END_IF;
END_IF;

IF (State = 4) AND PowerRearmEnable AND RearmPending AND NOT RearmStarted
   AND SafeCommon AND PowerContactorEngaged THEN
    RearmPending := FALSE;
    RearmStarted := TRUE;
    PendingPhase := 2;
    AttemptCount := 0;
    Lockout := FALSE;
    State := 2;
END_IF;

// Les deux sequences sont annulees a la moindre condition safety invalide.
IF (State = 1 OR State = 2 OR State = 3) AND NOT SafeCommon THEN
    State := 4;
    Lockout := TRUE;
    Cancelled := TRUE;
END_IF;

// Stabilisation : le timer ne progresse que si les diagnostics sont revenus
// operationnels et si les conditions safety restent valides.
StabilizationTimer(
    IN := (State = 1 OR State = 2) AND SafeCommon AND DiagnosticsStable,
    PT := Cfg_StabilizationTime
);

IF (State = 1 OR State = 2) AND StabilizationTimer.Q THEN
    ResetPulse := TRUE;
    AttemptCount := AttemptCount + 1;
    IF AttemptCount >= MaxAttemptsEffective THEN
        State := 4;
        Lockout := TRUE;
    ELSE
        State := 3;
    END_IF;
END_IF;

// Intervalle inter-impulsions. La condition safety reste re-evaluee au scan.
InterAttemptTimer(IN := (State = 3) AND SafeCommon, PT := Cfg_InterAttemptTime);
IF (State = 3) AND InterAttemptTimer.Q THEN
    State := PendingPhase;
END_IF;

SequenceActive := (State = 1 OR State = 2 OR State = 3);
IF State = 4 THEN
    Phase := 3;
ELSIF SequenceActive THEN
    Phase := PendingPhase;
ELSE
    Phase := 0;
END_IF;

{region "§1 Fronts, remises a zero de tete de scan, verrou M3"}
// === §1 FRONTS + RAZ TETE DE SCAN + VERROU M3 =========================

// Protection premier scan : forcer repos et etat propre
IF NOT FirstScanDone THEN
    SeqStep              := E_MachineHomingTxState.HX0_REPOS;
    MachineHomingSeqStep := E_MachineHomingTxState.HX0_REPOS;
    MachineHomingFailed  := FALSE;
    HomingModeBActive    := FALSE;
    StandstillHomeReqDone:= FALSE;
    RetryCount           := 0;
    HomeReqDone          := FALSE;
    PendingClose         := FALSE;
END_IF;

// Sorties impulsionnelles / mouvement : remises a FALSE en tete de scan.
M1Demand.HomeReq := FALSE;
M2Demand.HomeReq := FALSE;
BucketCommit.CommitOpen  := FALSE;
BucketCommit.CommitClose := FALSE;
CmdBucketOpen  := FALSE;
CmdBucketClose := FALSE;
CmdWinchM1.RunRequest := FALSE; CmdWinchM1.ReqAscent := FALSE; CmdWinchM1.ReqDescend := FALSE; CmdWinchM1.StepTgt := 0;
CmdWinchM2.RunRequest := FALSE; CmdWinchM2.ReqAscent := FALSE; CmdWinchM2.ReqDescend := FALSE; CmdWinchM2.StepTgt := 0;
CmdWinchSelect := -1; // Par defaut pas d'override

ResetEdge(CLK := Reset);
LatchedEdge(CLK := Fault.Latched);
TopLostEdge(CLK := TopPositionSensor);
StartEdge(CLK := StartRequest);
BtnValidationEdge(CLK := BtnValidation);
HomingBucketConfirmEdge(CLK := BtnConfirmHomingBucket);

// Miroirs booleens de contexte GRAFCET.
ModeIsMaint1 := (Mode = E_Mode.MAINT_N1);
ModeIsMaint2 := (Mode = E_Mode.MAINT_N2);
MaintenanceActive := ModeIsMaint1 OR ModeIsMaint2;

// Phases de mouvement treuils
IsInMovePhase := (SeqStep = E_MachineHomingTxState.HX2_CLIMB_COUPLED);
CycleRunning  := (SeqStep <> E_MachineHomingTxState.HX0_REPOS);

// M3Locked est calcule en §9 pour verrouiller des le scan d'entree en cycle.
{endregion}

{region "§2 Conditions intermediaires"}
// === §2 CONDITIONS NOMMEES ============================================
BothAxesHomed       := M1Status.HomedAndReliable AND M2Status.HomedAndReliable;
CommitOrOffsetValid := CommitPublished OR BucketOffsetValid;
ClimbPermit         := DeadmanArmed AND JoystickPull;
DescendPermit       := DeadmanArmed AND JoystickPush;
BucketPermit        := DeadmanArmed AND JoystickPull; // HX1 : fermeture uniquement par manche tire

// Fenetre de grace deceleration
SettleGraceTimer(IN := (SeqStep = E_MachineHomingTxState.HX1A_COUPLING_INTERLOCK)
                       OR (SeqStep = E_MachineHomingTxState.HX4_STABILIZATION_CHECK)
                       OR (SeqStep = E_MachineHomingTxState.HX5_RELEASE_CLEARANCE), PT := CST_SettleGrace);

// Conditions d'abandon fail-safe
AxisHomingError  := M1Status.HomingError OR M2Status.HomingError;
MotionOutOfPhase := CycleRunning AND NOT IsInMovePhase
                    AND NOT WinchesMechanicallyStopped AND SettleGraceTimer.Q;

// Garde de montee HX2
ClimbStepActive := (SeqStep = E_MachineHomingTxState.HX2_CLIMB_COUPLED);
ClimbCommandActive := ClimbStepActive AND ClimbPermit;
ClimbTimer(IN := ClimbCommandActive, PT := Cfg.CfgTimeoutClimb);
ClimbTimedOut := ClimbStepActive AND ClimbTimer.Q;

// Garde prise de reference HX3
HomeAxesTimer(IN := (SeqStep = E_MachineHomingTxState.HX3_FLYING_REFERENCE), PT := Cfg.CfgTimeoutHomeAxes);
HomeAxesTimedOut := (SeqStep = E_MachineHomingTxState.HX3_FLYING_REFERENCE) AND HomeAxesTimer.Q AND NOT BothAxesHomed;
FlyingHomingTimer(IN := (SeqStep = E_MachineHomingTxState.HX3_FLYING_REFERENCE) AND NOT HomingModeBActive, PT := Cfg.CfgTimeoutFlyingHoming);

// Violation couplage E1
CouplingInterlockFault := (SeqStep = E_MachineHomingTxState.HX2_CLIMB_COUPLED)
                          AND (JoystickWinchSelectArbitrated <> 0);

// Sortie de MAINT_N2 alors qu'un step mouvement/cycle est engage : abandon fail-safe.
ModeLostDuringCycle := CycleRunning AND NOT ModeIsMaint2;
TransactionAbort := CycleRunning
                    AND (AxisHomingError OR MotionOutOfPhase OR ClimbTimedOut
                         OR HomeAxesTimedOut
                         OR CouplingInterlockFault OR ModeLostDuringCycle);
{endregion}

{region "§3 Detection perte de datum"}
// === §3 PERTE DE DATUM ================================================
AxesDatumRaw    := BothAxesHomed;
MachineHomedRaw := AxesDatumRaw AND CommitOrOffsetValid AND NOT ReHomingAckRequired;

IF FirstScanDone AND NOT MachineHomedRaw AND MachineWasHomed THEN
    IF NOT WinchesMechanicallyStopped THEN
        HomingLossLatched := TRUE;
    END_IF;
    ReHomingAckRequired := TRUE;
END_IF;

MachineWasHomed := MachineHomedRaw;

MachineHomingLossSafeStop := HomingLossLatched AND NOT WinchesMechanicallyStopped;

IF ResetEdge.Q AND WinchesMechanicallyStopped THEN
    HomingLossLatched   := FALSE;
    ReHomingAckRequired := FALSE;
END_IF;
{endregion}

{region "§4 Purge sur Reset & Forcage mise en service"}
// === §4 PURGE SUR RESET ===============================================
IF ResetEdge.Q THEN
    MachineHomingFailed  := FALSE;
    HomingModeBActive    := FALSE;
    StandstillHomeReqDone:= FALSE;
    PendingClose         := FALSE;
    CommitDone           := FALSE;
    HomeReqDone          := FALSE;
    RetryCount           := 0;
    SeqStep              := E_MachineHomingTxState.HX0_REPOS;
    MachineHomingSeqStep := E_MachineHomingTxState.HX0_REPOS;
END_IF;

// §4bis Forcage de step de mise en service (encadre)
ForceStepApplyEdge(CLK := CfgForceStepApply);
IF CfgCommissioningEnable AND ModeIsMaint2 AND ForceStepApplyEdge.Q THEN
    ForceStepClamped := LIMIT(0, CfgForceStepTarget, 8);
    CASE ForceStepClamped OF
        0: SeqStep := E_MachineHomingTxState.HX0_REPOS;
        1: SeqStep := E_MachineHomingTxState.HX1_BUCKET_PREPARE;
        2: SeqStep := E_MachineHomingTxState.HX1A_COUPLING_INTERLOCK;
        3: SeqStep := E_MachineHomingTxState.HX2_CLIMB_COUPLED;
        4: SeqStep := E_MachineHomingTxState.HX3_FLYING_REFERENCE;
        5: SeqStep := E_MachineHomingTxState.HX4_STABILIZATION_CHECK;
        6: SeqStep := E_MachineHomingTxState.HX5_RELEASE_CLEARANCE;
        7: SeqStep := E_MachineHomingTxState.HX6_HOMED_SUCCESS;
        8: SeqStep := E_MachineHomingTxState.HX7_FAILED;
    END_CASE;
    HomeReqDone         := FALSE;
    PendingClose        := FALSE;
    CommitDone          := FALSE;
    MachineHomingFailed := FALSE;
END_IF;
{endregion}

{region "§5 Table des causes & socle defaut"}
// === §5 TABLE DES CAUSES + SOCLE DEFAUT ==============================
instCauses[CST_CauseHomingLostInMotion].Active   := HomingLossLatched OR ReHomingAckRequired;
instCauses[CST_CauseHomingLostInMotion].Latching := TRUE;
instCauses[CST_CauseHomingLostInMotion].Texte    := 'Perte de datum machine en mouvement : re-referencer';

instCauses[CST_CauseClimbTimeout].Active   := ClimbTimedOut;
instCauses[CST_CauseClimbTimeout].Latching := TRUE;
instCauses[CST_CauseClimbTimeout].Texte    := 'Montee au capteur haut non aboutie dans le temps imparti';

instCauses[CST_CauseMotionOutOfPhase].Active   := MotionOutOfPhase;
instCauses[CST_CauseMotionOutOfPhase].Latching := TRUE;
instCauses[CST_CauseMotionOutOfPhase].Texte    := 'Mouvement treuil detecte hors phase autorisee du cycle';

instCauses[CST_CauseHomingErrorM1].Active   := CycleRunning AND M1Status.HomingError;
instCauses[CST_CauseHomingErrorM1].Latching := TRUE;
instCauses[CST_CauseHomingErrorM1].Texte    := 'Erreur de homing codeur M1 pendant le referencement conjoint';

instCauses[CST_CauseHomingErrorM2].Active   := CycleRunning AND M2Status.HomingError;
instCauses[CST_CauseHomingErrorM2].Latching := TRUE;
instCauses[CST_CauseHomingErrorM2].Texte    := 'Erreur de homing codeur M2 pendant le referencement conjoint';

instCauses[CST_CauseHomeAxesTimeout].Active   := HomeAxesTimedOut;
instCauses[CST_CauseHomeAxesTimeout].Latching := TRUE;
instCauses[CST_CauseHomeAxesTimeout].Texte    := 'Prise de reference capteur haut non obtenue dans le temps';

instCauses[CST_CauseCouplingFault].Active   := CouplingInterlockFault;
instCauses[CST_CauseCouplingFault].Latching := TRUE;
instCauses[CST_CauseCouplingFault].Texte    := 'Defaut de couplage treuils M1+M2 en phase montee';

instCauses[CST_CauseStabilizationFault].Active   := (SeqStep = E_MachineHomingTxState.HX7_FAILED) AND (RetryCount >= 3);
instCauses[CST_CauseStabilizationFault].Latching := TRUE;
instCauses[CST_CauseStabilizationFault].Texte    := 'Stabilisation inertie treuils hors plage apres 3 tentatives';

// Socle defaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§6 Initiation du cycle"}
// === §6 INITIATION DU CYCLE ===========================================
// Le cycle ne s'auto-arme JAMAIS spontanement (securite machine, actionneurs
// sollicites des HX1). L'initiation exige une action consciente de l'operateur
// en mode MAINT_N2 (StartRequest sur IHM ou BtnValidation sur joystick).
{endregion}

{region "§7 Gate Enable"}
// === §7 GATE ENABLE ===================================================
IF NOT Enable THEN
    M1Demand.HomeReq         := FALSE;
    M2Demand.HomeReq         := FALSE;
    BucketCommit.CommitOpen  := FALSE;
    BucketCommit.CommitClose := FALSE;
    CmdBucketOpen            := FALSE;
    CmdBucketClose           := FALSE;
    CmdWinchM1.RunRequest    := FALSE; CmdWinchM1.ReqAscent := FALSE; CmdWinchM1.ReqDescend := FALSE; CmdWinchM1.StepTgt := 0;
    CmdWinchM2.RunRequest    := FALSE; CmdWinchM2.ReqAscent := FALSE; CmdWinchM2.ReqDescend := FALSE; CmdWinchM2.StepTgt := 0;
    CmdWinchSelect           := -1;
    Ready                    := FALSE;
    Lifecycle.Busy           := FALSE;
    Lifecycle.Done           := FALSE;
    MachineHomingActive      := FALSE;
    M3Locked                 := FALSE;
    MachineHomed             := FALSE;
    MachineHomingLossSafeStop := FALSE;
    CommitPublished          := FALSE;
    CommitDone               := FALSE;
    PendingClose             := FALSE;
    HomingModeBActive        := FALSE;
    StandstillHomeReqDone    := FALSE;
    RetryCount               := 0;
    SeqStep                  := E_MachineHomingTxState.HX0_REPOS;
    MachineHomingSeqStep     := E_MachineHomingTxState.HX0_REPOS;
    MachineHomingStep        := E_MachineHomingStep.IDLE;
    MachineHomingInstruction := 'Cycle homing desactive';
    RETURN;
END_IF;
{endregion}

{region "§8 GRAFCET de referencement machine (CASE SeqStep)"}
// === §8 GRAFCET (CASE SeqStep) ======================================
CASE SeqStep OF

    E_MachineHomingTxState.HX0_REPOS:
        // Etape initiale pure : aucune action.
        CmdWinchSelect := -1;
        IF (StartEdge.Q OR BtnValidationEdge.Q) AND ModeIsMaint2 THEN
            HomeReqDone := FALSE;
            RetryCount  := 0;
            SeqStep     := E_MachineHomingTxState.HX1_BUCKET_PREPARE;
        END_IF;

    E_MachineHomingTxState.HX1_BUCKET_PREPARE:
        // Decision & Fermeture benne operateur :
        // WinchSel=2 force, FDC benne logiciel inhibe, vitesse plafonnee palier 1.
        CmdWinchSelect := 2;
        IF BucketPermit AND JoystickPull THEN
            CmdBucketClose := TRUE;
        END_IF;

        IF ModeLostDuringCycle OR MotionOutOfPhase THEN
            MachineHomingFailed := TRUE;
            SeqStep := E_MachineHomingTxState.HX7_FAILED;
        ELSIF HomingBucketConfirmEdge.Q AND NOT JoystickDeflected THEN
            // Validation par 1 seul appui bouton dedie IHM, manche au neutre
            PendingClose := TRUE;
            CommitDone   := FALSE;
            SeqStep      := E_MachineHomingTxState.HX1A_COUPLING_INTERLOCK;
        END_IF;

    E_MachineHomingTxState.HX1A_COUPLING_INTERLOCK:
        // Bascule WinchSel=0, reactivation FDC benne.
        // Interlock bloquant E1 : attente confirmation couplage aval effectif.
        CmdWinchSelect := 0;
        CouplingSettleTimer(IN := (JoystickWinchSelectArbitrated = 0), PT := T#300ms);

        IF ModeLostDuringCycle OR AxisHomingError THEN
            MachineHomingFailed := TRUE;
            SeqStep := E_MachineHomingTxState.HX7_FAILED;
        ELSIF (JoystickWinchSelectArbitrated = 0) AND CouplingSettleTimer.Q AND WinchesMechanicallyStopped THEN
            SeenNeutral := NOT JoystickDeflected;
            SeqStep     := E_MachineHomingTxState.HX2_CLIMB_COUPLED;
        END_IF;

    E_MachineHomingTxState.HX2_CLIMB_COUPLED:
        // Montee couplee M1+M2 palier 1 MAX vers capteur haut.
        CmdWinchSelect := 0;
        IF ClimbPermit AND (JoystickWinchSelectArbitrated = 0) THEN
            CmdWinchM1.RunRequest := TRUE; CmdWinchM1.ReqAscent := TRUE; CmdWinchM1.StepTgt := CST_StepSlow;
            CmdWinchM2.RunRequest := TRUE; CmdWinchM2.ReqAscent := TRUE; CmdWinchM2.StepTgt := CST_StepSlow;
        END_IF;

        IF TransactionAbort THEN
            MachineHomingFailed := TRUE;
            SeqStep := E_MachineHomingTxState.HX7_FAILED;
        ELSIF TopPositionSensor THEN
            M1Demand.HomeReq      := TRUE;
            M2Demand.HomeReq      := TRUE;
            HomeReqDone           := TRUE;
            HomingModeBActive     := FALSE;
            StandstillHomeReqDone := FALSE;
            SeqStep               := E_MachineHomingTxState.HX3_FLYING_REFERENCE;
        END_IF;

    E_MachineHomingTxState.HX3_FLYING_REFERENCE:
        // Referencement conjoint M1+M2 sur capteur haut :
        // Mode A "a la volee" prioritaire, avec repli automatique en Mode B "a l'arret".
        CmdWinchSelect := 0;

        // --- MODE A : PRISE DE REFERENCE A LA VOLEE ---
        IF NOT HomingModeBActive THEN
            // Impulsion initiale de homing au vol si pas encore emise au franchissement
            IF NOT HomeReqDone THEN
                M1Demand.HomeReq := TRUE;
                M2Demand.HomeReq := TRUE;
                HomeReqDone      := TRUE;
            END_IF;

            // En vol, si les codeurs confirment -> succes immediat Mode A
            IF BothAxesHomed THEN
                SeqStep := E_MachineHomingTxState.HX4_STABILIZATION_CHECK;
            // Repli automatique Mode B si le preset ne se confirme pas dans le temps imparti (3s)
            // OU si les treuils s'arretent ou si le manche est relache
            ELSIF FlyingHomingTimer.Q OR WinchesMechanicallyStopped OR NOT JoystickDeflected THEN
                HomingModeBActive     := TRUE;
                StandstillHomeReqDone := FALSE;
            END_IF;

        // --- MODE B : REPLI AUTOMATIQUE A L'ARRET ---
        ELSE
            // En repli Mode B : aucun ordre de mouvement emis, arret mecanique confirme attendu
            IF WinchesMechanicallyStopped THEN
                // A l'arret physique complet, re-emission impulsionnelle de HomeReq
                IF NOT StandstillHomeReqDone THEN
                    M1Demand.HomeReq      := TRUE;
                    M2Demand.HomeReq      := TRUE;
                    StandstillHomeReqDone := TRUE;
                END_IF;

                // Validation prise de reference a l'arret
                IF BothAxesHomed THEN
                    SeqStep := E_MachineHomingTxState.HX4_STABILIZATION_CHECK;
                END_IF;
            END_IF;
        END_IF;

        IF TransactionAbort THEN
            MachineHomingFailed := TRUE;
            SeqStep := E_MachineHomingTxState.HX7_FAILED;
        END_IF;

    E_MachineHomingTxState.HX4_STABILIZATION_CHECK:
        // Arret treuils, controle inertie [8.50..8.80m] et concordance codeurs.
        CmdWinchSelect := 0;
        SeenNeutral := NOT JoystickDeflected;

        StabilizationOk := WinchesMechanicallyStopped AND SeenNeutral
                           AND (CablePosM1 >= Cfg.CfgStabilizationMinM) AND (CablePosM1 <= Cfg.CfgStabilizationMaxM)
                           AND (CablePosM2 >= Cfg.CfgStabilizationMinM) AND (CablePosM2 <= Cfg.CfgStabilizationMaxM)
                           AND (ABS(CablePosM1 - CablePosM2) <= CoherenceLimitM);

        StabilizationFailed := WinchesMechanicallyStopped AND SeenNeutral AND NOT StabilizationOk;

        IF ModeLostDuringCycle OR AxisHomingError THEN
            MachineHomingFailed := TRUE;
            SeqStep := E_MachineHomingTxState.HX7_FAILED;
        ELSIF StabilizationOk THEN
            SeqStep := E_MachineHomingTxState.HX5_RELEASE_CLEARANCE;
        ELSIF StabilizationFailed THEN
            RetryCount := RetryCount + 1;
            IF RetryCount >= 3 THEN
                MachineHomingFailed := TRUE;
                SeqStep := E_MachineHomingTxState.HX7_FAILED;
            ELSE
                // Repositionnement et nouvelle tentative : retour en preparation benne
                SeqStep := E_MachineHomingTxState.HX1_BUCKET_PREPARE;
            END_IF;
        END_IF;

    E_MachineHomingTxState.HX5_RELEASE_CLEARANCE:
        // Degagement zone haute, confirmation joystick au neutre.
        CmdWinchSelect := 0;
        IF ModeLostDuringCycle OR AxisHomingError THEN
            MachineHomingFailed := TRUE;
            SeqStep := E_MachineHomingTxState.HX7_FAILED;
        ELSIF NOT JoystickDeflected AND WinchesMechanicallyStopped THEN
            SeqStep := E_MachineHomingTxState.HX6_HOMED_SUCCESS;
        END_IF;

    E_MachineHomingTxState.HX6_HOMED_SUCCESS:
        // Validation finale : MachineHomed := TRUE, commit atomique benne.
        CmdWinchSelect := 0;
        IF NOT CommitDone THEN
            BucketCommit.CommitClose := PendingClose;
            CommitPublished          := TRUE;
            CommitDone               := TRUE;
        ELSE
            PendingClose := FALSE;
            SeqStep      := E_MachineHomingTxState.HX0_REPOS;
        END_IF;

    E_MachineHomingTxState.HX7_FAILED:
        // Echec sequence unifie : sorties a 0, attente Reset conscient en MAINT_N2.
        CmdWinchSelect := -1;
        ;

END_CASE;
{endregion}

{region "§9 Cycle de vie & qualification de sortie"}
// === §9 CYCLE DE VIE + QUALIFICATION ================================
CycleRunning := (SeqStep <> E_MachineHomingTxState.HX0_REPOS);

// Selection treuil demandee par le cycle
IF (SeqStep = E_MachineHomingTxState.HX1_BUCKET_PREPARE) THEN
    CmdWinchSelect := 2;
ELSIF (SeqStep = E_MachineHomingTxState.HX1A_COUPLING_INTERLOCK)
   OR (SeqStep = E_MachineHomingTxState.HX2_CLIMB_COUPLED)
   OR (SeqStep = E_MachineHomingTxState.HX3_FLYING_REFERENCE)
   OR (SeqStep = E_MachineHomingTxState.HX4_STABILIZATION_CHECK)
   OR (SeqStep = E_MachineHomingTxState.HX5_RELEASE_CLEARANCE)
   OR (SeqStep = E_MachineHomingTxState.HX6_HOMED_SUCCESS) THEN
    CmdWinchSelect := 0;
ELSE
    CmdWinchSelect := -1;
END_IF;

M3Locked             := CycleRunning;
MachineHomingActive  := CycleRunning;
Lifecycle.Busy       := CycleRunning;
Lifecycle.Done       := CommitPublished AND (SeqStep = E_MachineHomingTxState.HX0_REPOS);
MachineHomingSeqStep := SeqStep;

CommitOrOffsetValid := CommitPublished OR BucketOffsetValid;
MachineHomed := BothAxesHomed AND CommitOrOffsetValid
                AND (SeqStep <> E_MachineHomingTxState.HX7_FAILED)
                AND NOT MachineHomingFailed AND NOT ReHomingAckRequired
                AND NOT Fault.Latched;
{endregion}

{region "§10 Guide operateur — echelle de priorite"}
// === §10 GUIDE OPERATEUR (echelle de priorite) ======================
IF Fault.Latched THEN
    MachineHomingStep := E_MachineHomingStep.FAILED;
    MachineHomingInstruction := 'Erreur ou Echec homing - Acquitter (Reset)';
ELSIF MachineHomingFailed OR (SeqStep = E_MachineHomingTxState.HX7_FAILED) THEN
    MachineHomingStep := E_MachineHomingStep.FAILED;
    MachineHomingInstruction := 'HX7 - Homing incomplet - Acquitter Reset N2';
ELSIF MachineHomingLossSafeStop THEN
    MachineHomingStep := E_MachineHomingStep.LOSS_SAFESTOP;
    MachineHomingInstruction := 'Reference perdue - Arret controle';
ELSIF MachineHomed AND NOT CycleRunning THEN
    MachineHomingStep := E_MachineHomingStep.VALID;
    MachineHomingInstruction := '';
ELSIF (SeqStep = E_MachineHomingTxState.HX1_BUCKET_PREPARE) THEN
    MachineHomingStep := E_MachineHomingStep.AWAIT_BUCKET_CONFIRM;
    MachineHomingInstruction := 'HX1 - RefHoming Fermer benne, valider sur IHM';
ELSIF (SeqStep = E_MachineHomingTxState.HX1A_COUPLING_INTERLOCK) THEN
    MachineHomingStep := E_MachineHomingStep.NEED_MECHANICAL_STOP;
    MachineHomingInstruction := 'HX1a - RefHoming Verif couplage M1+M2';
ELSIF (SeqStep = E_MachineHomingTxState.HX2_CLIMB_COUPLED) THEN
    MachineHomingStep := E_MachineHomingStep.NEED_TOP_POSITION;
    MachineHomingInstruction := 'HX2 - RefHoming Tirer JOY palier 1 vers haut';
ELSIF (SeqStep = E_MachineHomingTxState.HX3_FLYING_REFERENCE) THEN
    MachineHomingStep := E_MachineHomingStep.HOMING_IN_PROGRESS;
    IF HomingModeBActive THEN
        IF NOT WinchesMechanicallyStopped THEN
            MachineHomingInstruction := 'HX3 - Repli arret (Mode B) : attente arret treuils';
        ELSE
            MachineHomingInstruction := 'HX3 - Repli arret (Mode B) : reference conjointement';
        END_IF;
    ELSE
        MachineHomingInstruction := 'HX3 - RefHoming Prise de reference au vol';
    END_IF;
ELSIF (SeqStep = E_MachineHomingTxState.HX4_STABILIZATION_CHECK) THEN
    MachineHomingStep := E_MachineHomingStep.NEED_MECHANICAL_STOP;
    MachineHomingInstruction := 'HX4 - RefHoming Arret et controle inertie';
ELSIF (SeqStep = E_MachineHomingTxState.HX5_RELEASE_CLEARANCE) THEN
    MachineHomingStep := E_MachineHomingStep.NEED_MECHANICAL_STOP;
    MachineHomingInstruction := 'HX5 - RefHoming Relacher JOY au neutre';
ELSIF (SeqStep = E_MachineHomingTxState.HX6_HOMED_SUCCESS) THEN
    MachineHomingStep := E_MachineHomingStep.VALID;
    MachineHomingInstruction := 'HX6 - RefHoming Machine referencee';
ELSIF NOT M1Status.HomedAndReliable AND NOT M2Status.HomedAndReliable THEN
    MachineHomingStep := E_MachineHomingStep.BOTH_NOT_HOMED;
    IF Mode = E_Mode.MAINT_N2 THEN
        MachineHomingInstruction := 'HX0 - RefHoming M1+M2 non ref - Lancer sur IHM';
    ELSIF Mode = E_Mode.MAINT_N1 THEN
        MachineHomingInstruction := 'HX0 - M1+M2 non ref - Homing unitaire possible';
    ELSE
        MachineHomingInstruction := 'HX0 - M1+M2 non referencies';
    END_IF;
ELSIF NOT M1Status.HomedAndReliable THEN
    MachineHomingStep := E_MachineHomingStep.M1_NOT_HOMED;
    IF Mode = E_Mode.MAINT_N2 THEN
        MachineHomingInstruction := 'HX0 - RefHoming M1 non ref - Lancer sur IHM';
    ELSIF Mode = E_Mode.MAINT_N1 THEN
        MachineHomingInstruction := 'HX0 - M1 non ref - Homing unitaire possible';
    ELSE
        MachineHomingInstruction := 'HX0 - M1 non reference';
    END_IF;
ELSIF NOT M2Status.HomedAndReliable THEN
    MachineHomingStep := E_MachineHomingStep.M2_NOT_HOMED;
    IF Mode = E_Mode.MAINT_N2 THEN
        MachineHomingInstruction := 'HX0 - RefHoming M2 non ref - Lancer sur IHM';
    ELSIF Mode = E_Mode.MAINT_N1 THEN
        MachineHomingInstruction := 'HX0 - M2 non ref - Homing unitaire possible';
    ELSE
        MachineHomingInstruction := 'HX0 - M2 non reference';
    END_IF;
ELSIF NOT (CommitPublished OR BucketOffsetValid) THEN
    IF Mode = E_Mode.MAINT_N2 THEN
        MachineHomingStep := E_MachineHomingStep.AWAIT_BUCKET_CONFIRM;
        MachineHomingInstruction := 'HX0 - RefHoming Lancer le homing (etat benne)';
    ELSIF Mode = E_Mode.MAINT_N1 THEN
        MachineHomingStep := E_MachineHomingStep.OFFSET_UNKNOWN;
        MachineHomingInstruction := 'HX0 - Offset benne inconnu';
    ELSE
        MachineHomingStep := E_MachineHomingStep.OFFSET_UNKNOWN;
        MachineHomingInstruction := 'HX0 - Offset benne inconnu';
    END_IF;
ELSE
    MachineHomingStep := E_MachineHomingStep.VALID;
    MachineHomingInstruction := 'Reference machine valide';
END_IF;

// Capture R9 de l'etape a l'apparition du defaut latche
IF LatchedEdge.Q THEN
    MachineHomingStepAtError := MachineHomingStep;
END_IF;

Ready := Enable AND NOT Fault.Latched;
FirstScanDone := TRUE;
{endregion}

{region "§1 Gate"}
// 🛑 1. GATE : Désactivation logique si Enable = FALSE
IF NOT Enable THEN
    Ready := FALSE;
    DeviceJoystick.State := E_Diag_State.DISABLED;
    DeviceJoystick.Online := FALSE;
    DeviceJoystick.Operational := FALSE;
    DeviceJoystick.Error := FALSE;
    DeviceJoystick.ErrorId := 16#0000;
    DeviceCanOpenMaster.State := E_Diag_State.DISABLED;
    DeviceCanOpenMaster.Online := FALSE;
    DeviceCanOpenMaster.Operational := FALSE;
    DeviceCanOpenMaster.Error := FALSE;
    DeviceCanOpenMaster.ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;
{endregion}

{region "§2 Interprétation valeurs brutes"}
// 🧮 2. INTERPRÉTATION DES VALEURS BRUTES
CANbusOnlineReal         := (CANbusStateRaw = 2);
DeviceJoystickOnlineReal := (DeviceJoystickStateRaw = DEVICE_STATE.RUNNING);

CANbusOnlineEff          := CANbusOnlineReal OR SimBypassActive OR NetworkBypassActive OR CanBusBypassActive;
DeviceJoystickOnlineEff  := DeviceJoystickOnlineReal OR SimBypassActive OR NetworkBypassActive OR JoystickBypassActive;
{endregion}

{region "§3 Reset front"}
// 🔑 3. RESET FRONT — Efface les défauts si la cause a disparu
ResetEdge(CLK := Reset);
ResetTransientEdge(CLK := ResetTransient);
IF ResetTransientEdge.Q THEN
    // Auto-reset : seuls les bits communication connus sont effaces.
    IF (CANbusOnlineEff AND DeviceJoystickOnlineEff) THEN
        DeviceJoystick.ErrorId := DeviceJoystick.ErrorId AND 16#FFFC;
    END_IF;
END_IF;
IF ResetEdge.Q THEN
    // Reset operateur complet du diagnostic joystick.
    IF (CANbusOnlineEff AND DeviceJoystickOnlineEff) THEN
        DeviceJoystick.ErrorId := 16#0000;
        DeviceJoystick.StateAtError := E_Diag_State.DISABLED;
    END_IF;
END_IF;
{endregion}

{region "§4 Diagnostic joystick"}
// 🔍 4. DIAGNOSTIC JOYSTICK
// Bit 0 : Perte de communication CAN
IF NOT CANbusOnlineEff THEN
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId OR 16#0001;  (* Perte liaison CAN joystick *)
ELSE
    DeviceJoystick.Online := TRUE;
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId AND 16#FFFE; (* Effacement auto si la liaison revient *)
END_IF;

// Bit 1 : Mode non-opérationnel (esclave CANopen en pré-op ou défaut)
IF NOT DeviceJoystickOnlineEff THEN
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId OR 16#0002;  (* Joystick pas opérationnel *)
    DeviceJoystick.Operational := FALSE;
ELSE
    DeviceJoystick.Operational := TRUE;
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId AND 16#FFFD; (* Effacement auto dès que RUNNING *)
END_IF;
{endregion}

{region "§5 Machine etat joystick"}
// 🚦 5. MACHINE D'ÉTAT JOYSTICK
IF DeviceJoystick.ErrorId <> 0 THEN
    DeviceJoystick.State := E_Diag_State.ERROR;
ELSIF NOT (DeviceJoystick.Online AND DeviceJoystick.Operational) THEN
    DeviceJoystick.State := E_Diag_State.INIT;
ELSIF (SimBypassActive OR NetworkBypassActive OR JoystickBypassActive) AND NOT (CANbusOnlineReal AND DeviceJoystickOnlineReal) THEN
    DeviceJoystick.State := E_Diag_State.SIMULATED;
ELSE
    DeviceJoystick.State := E_Diag_State.READY;
END_IF;
{endregion}

{region "§6 Sorties globales"}
// 📤 6. SORTIES GLOBALES
DeviceJoystick.Error := (DeviceJoystick.ErrorId <> 0);

DeviceCanOpenMaster.Operational := CANbusOnlineEff;
DeviceCanOpenMaster.Online := CANbusOnlineEff;
DeviceCanOpenMaster.Error := NOT CANbusOnlineEff;

IF NOT CANbusOnlineEff THEN
    DeviceCanOpenMaster.ErrorId := 16#0001;
    DeviceCanOpenMaster.State := E_Diag_State.ERROR;
    IF DeviceCanOpenMaster.StateAtError = E_Diag_State.DISABLED THEN
        DeviceCanOpenMaster.StateAtError := E_Diag_State.INIT;
    END_IF;
ELSIF (SimBypassActive OR NetworkBypassActive OR CanBusBypassActive) AND NOT CANbusOnlineReal THEN
    DeviceCanOpenMaster.ErrorId := 16#0000;
    DeviceCanOpenMaster.State := E_Diag_State.SIMULATED;
ELSE
    DeviceCanOpenMaster.ErrorId := 16#0000;
    DeviceCanOpenMaster.State := E_Diag_State.READY;
END_IF;
{endregion}

{region "§1 Gate de desactivation"}
// 🛑 1. GATE : Désactivation si Enable = FALSE
IF NOT Enable THEN
    Ready := FALSE;
    DeviceVariateur.State := E_Diag_State.DISABLED;
    DeviceEncoderM1.State := E_Diag_State.DISABLED;
    DeviceEncoderM2.State := E_Diag_State.DISABLED;
    DeviceVariateur.Online := FALSE;
    DeviceEncoderM1.Online := FALSE;
    DeviceEncoderM2.Online := FALSE;
    DeviceVariateur.Operational := FALSE;
    DeviceEncoderM1.Operational := FALSE;
    DeviceEncoderM2.Operational := FALSE;
    DeviceVariateur.Error := FALSE;
    DeviceEncoderM1.Error := FALSE;
    DeviceEncoderM2.Error := FALSE;
    DeviceEthercatMaster.State := E_Diag_State.DISABLED;
    DeviceEthercatMaster.Online := FALSE;
    DeviceEthercatMaster.Operational := FALSE;
    DeviceEthercatMaster.Error := FALSE;
    DeviceEthercatMaster.ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;

{endregion}

{region "§2 Interpretation etats bruts et bypass"}
// 🧮 2. INTERPRÉTATION DES VALEURS BRUTES
VariateurOnlineReal := (DeviceVariateurStateRaw = DEVICE_STATE.RUNNING);
EncoderM1OnlineReal := (DeviceEncoderM1StateRaw = DEVICE_STATE.RUNNING);
EncoderM2OnlineReal := (DeviceEncoderM2StateRaw = DEVICE_STATE.RUNNING);

VariateurBypass := DeviceVariateurSimBypass OR NetworkBypassActive OR VariateurBypassActive;
EncoderM1Bypass := DeviceEncoderM1SimBypass OR NetworkBypassActive OR EncoderM1BypassActive;
EncoderM2Bypass := DeviceEncoderM2SimBypass OR NetworkBypassActive OR EncoderM2BypassActive;

VariateurOnlineEff := VariateurOnlineReal OR VariateurBypass;
EncoderM1OnlineEff := EncoderM1OnlineReal OR EncoderM1Bypass;
EncoderM2OnlineEff := EncoderM2OnlineReal OR EncoderM2Bypass;

// 🔑 3. RESET FRONT
ResetEdge(CLK := Reset);
ResetTransientEdge(CLK := ResetTransient);
IF ResetTransientEdge.Q THEN
    // Auto-reset : liste blanche stricte des seuls bits de perte de liaison.
    // Les futurs bits variateur/codeur ne peuvent donc pas etre effaces ici.
    IF VariateurOnlineEff THEN DeviceVariateur.ErrorId := DeviceVariateur.ErrorId AND 16#FFEF; END_IF;
    IF EncoderM1OnlineEff THEN DeviceEncoderM1.ErrorId := DeviceEncoderM1.ErrorId AND 16#FFDF; END_IF;
    IF EncoderM2OnlineEff THEN DeviceEncoderM2.ErrorId := DeviceEncoderM2.ErrorId AND 16#FFCF; END_IF;
END_IF;
IF ResetEdge.Q THEN
    // Reset operateur : acquittement complet du diagnostic reseau si l equipement
    // est revenu effectif. Cette voie reste distincte de ResetTransient.
    IF VariateurOnlineEff THEN DeviceVariateur.ErrorId := 16#0000; DeviceVariateur.StateAtError := E_Diag_State.DISABLED; END_IF;
    IF EncoderM1OnlineEff THEN DeviceEncoderM1.ErrorId := 16#0000; DeviceEncoderM1.StateAtError := E_Diag_State.DISABLED; END_IF;
    IF EncoderM2OnlineEff THEN DeviceEncoderM2.ErrorId := 16#0000; DeviceEncoderM2.StateAtError := E_Diag_State.DISABLED; END_IF;
END_IF;

{endregion}

{region "§3 Diagnostic par equipement"}
// 🔍 4. DIAGNOSTIC VARIATEUR (AC600_ECAT_Drive / Translation M3)
DeviceVariateur.Online := VariateurOnlineEff;
DeviceVariateur.Operational := VariateurOnlineEff;

IF NOT DeviceVariateur.Online THEN
    DeviceVariateur.ErrorId := DeviceVariateur.ErrorId OR 16#0010;  (* Perte liaison physique variateur *)
ELSE
    DeviceVariateur.ErrorId := DeviceVariateur.ErrorId AND 16#FFEF; (* Effacement auto dès que RUNNING *)
END_IF;

// 🔍 5. DIAGNOSTIC ENCODEUR M1 (COD1_CODEUR / WinchM1)
DeviceEncoderM1.Online := EncoderM1OnlineEff;
DeviceEncoderM1.Operational := EncoderM1OnlineEff;

IF NOT DeviceEncoderM1.Online THEN
    DeviceEncoderM1.ErrorId := DeviceEncoderM1.ErrorId OR 16#0020;  (* Perte liaison encodeur M1 *)
ELSE
    DeviceEncoderM1.ErrorId := DeviceEncoderM1.ErrorId AND 16#FFDF; (* Effacement auto dès que RUNNING *)
END_IF;

// 🔍 6. DIAGNOSTIC ENCODEUR M2 (COD2_CODEUR / WinchM2)
DeviceEncoderM2.Online := EncoderM2OnlineEff;
DeviceEncoderM2.Operational := EncoderM2OnlineEff;

IF NOT DeviceEncoderM2.Online THEN
    DeviceEncoderM2.ErrorId := DeviceEncoderM2.ErrorId OR 16#0030;  (* Perte liaison encodeur M2 *)
ELSE
    DeviceEncoderM2.ErrorId := DeviceEncoderM2.ErrorId AND 16#FFCF; (* Effacement auto dès que RUNNING *)
END_IF;

{endregion}

{region "§4 Etats diagnostic par equipement"}
// 🚦 7. STATE MACHINES DE CHAQUE APPAREIL
IF DeviceVariateur.ErrorId <> 0 THEN
    DeviceVariateur.State := E_Diag_State.ERROR;
ELSIF NOT VariateurOnlineEff THEN
    DeviceVariateur.State := E_Diag_State.INIT;
ELSIF VariateurBypass AND NOT VariateurOnlineReal THEN
    DeviceVariateur.State := E_Diag_State.SIMULATED;
ELSE
    DeviceVariateur.State := E_Diag_State.READY;
END_IF;

IF DeviceEncoderM1.ErrorId <> 0 THEN
    DeviceEncoderM1.State := E_Diag_State.ERROR;
ELSIF NOT EncoderM1OnlineEff THEN
    DeviceEncoderM1.State := E_Diag_State.INIT;
ELSIF EncoderM1Bypass AND NOT EncoderM1OnlineReal THEN
    DeviceEncoderM1.State := E_Diag_State.SIMULATED;
ELSE
    DeviceEncoderM1.State := E_Diag_State.READY;
END_IF;

IF DeviceEncoderM2.ErrorId <> 0 THEN
    DeviceEncoderM2.State := E_Diag_State.ERROR;
ELSIF NOT EncoderM2OnlineEff THEN
    DeviceEncoderM2.State := E_Diag_State.INIT;
ELSIF EncoderM2Bypass AND NOT EncoderM2OnlineReal THEN
    DeviceEncoderM2.State := E_Diag_State.SIMULATED;
ELSE
    DeviceEncoderM2.State := E_Diag_State.READY;
END_IF;

{endregion}

{region "§5 Synthese EtherCAT et sorties"}
// 📤 8. RÉSUMÉ ET DÉFAUTS
DeviceVariateur.Error := (DeviceVariateur.ErrorId <> 0);
DeviceEncoderM1.Error := (DeviceEncoderM1.ErrorId <> 0);
DeviceEncoderM2.Error := (DeviceEncoderM2.ErrorId <> 0);

DeviceEthercatMaster.Online := (VariateurOnlineEff AND EncoderM1OnlineEff AND EncoderM2OnlineEff) OR NetworkBypassActive OR EcatBusBypassActive;
DeviceEthercatMaster.Operational := DeviceEthercatMaster.Online;
DeviceEthercatMaster.Error := NOT DeviceEthercatMaster.Operational;

IF DeviceEthercatMaster.Error THEN
    DeviceEthercatMaster.ErrorId := 16#0001;
    DeviceEthercatMaster.State := E_Diag_State.ERROR;
ELSIF (VariateurBypass OR EncoderM1Bypass OR EncoderM2Bypass OR EcatBusBypassActive) THEN
    DeviceEthercatMaster.ErrorId := 16#0000;
    DeviceEthercatMaster.State := E_Diag_State.SIMULATED;
ELSE
    DeviceEthercatMaster.ErrorId := 16#0000;
    DeviceEthercatMaster.State := E_Diag_State.READY;
END_IF;
{endregion}

{region "§1 Gate neutralisation"}
IF NOT Enable THEN
    Ready := FALSE;
    Measurement.RawPos := 0; Measurement.EncoderAvailable := FALSE;
    Measurement.CablePosM := 0.0; Measurement.CablePosMSafe := 0.0; Measurement.EncoderIncoherent := FALSE;
    Measurement.Speed_Mps := 0.0; Measurement.SignedSpeed_Mps := 0.0; Measurement.SpeedValid := FALSE;
    Measurement.HomingFault.Error := FALSE; Measurement.HomingFault.ErrorId := 0;
    Measurement.HomingLifecycle.Busy := FALSE; Measurement.HomingLifecycle.Done := FALSE;
    Measurement.AbsFault.Error := FALSE;    Measurement.AbsFault.ErrorId := 0;
    EncoderFault := TRUE;
    HomedAndReliable := FALSE;
    // Frontiere HW sortie : aucun ordre preset publie hors autorisation
    // (sinon PRG_02_Acquisition relaie une valeur perimee au codeur absolu -> preset parasite, reference corrompue)
    HwOut.PresetTriggerCmd := 0; HwOut.CodeSeqTriggerCmd := 0; HwOut.PresetValueOut := 0;
    // Reference connue MAINTENUE depuis Calib (RETAIN) meme FB desactive (AF09 §4) :
    // un FB desactive ne doit pas faire perdre la reference aux consommateurs aval (PRG_04, FB_Encoder_Scale).
    Homed := Calib.Homed;
    HomingSuspect := Calib.HomingSuspect;
    Measurement.HomingRefRaw := Calib.HomingRefRaw;
    // PresetConfirmationFailed est un diagnostic latch : il reste gele hors Enable
    // et ne doit pas etre efface par ce gate (AC3).
    // Socle appele meme Enable=FALSE : maintient le latch non acquitte et traite le Reset
    // hors autorisation (AC4). Les causes ne sont pas evaluees (Enable=FALSE -> vue live a 0),
    // les latches sont preserves.
    instFault(Enable := FALSE, Reset := Reset, Causes := instCauses);
    Fault := instFault.Fault;
    RETURN;
END_IF;
Ready := TRUE;
{endregion}

{region "§2 Abs"}
    instAbs(
    Enable              := Enable,
    Reset               := Reset,
    RawPosIn            := HwIn.RawPosIn,
    AlarmsIn            := HwIn.AlarmsIn,
    WarningsIn          := HwIn.WarningsIn,
    SlaveOperational    := HwIn.SlaveOperational,
    PresetRequest       := instHoming.PresetRequest,
    PresetValue         := instHoming.PresetValue,
    PointsPerRev        := PointsPerRev
);
{endregion}

{region "§3 Homing"}
instHoming(
    Enable               := Enable,
    Reset                := Reset,
    Home                 := HomingAtTargetM,
    HomingPermit         := HomingPermit,
    BtnConfirmCoherence  := ConfirmCoherence,
    UseDynamicTarget     := UseDynamicTarget,
    DynamicHomingTargetM := DynamicHomingTargetM,
    CfgHomingTargetM     := CfgHomingTargetM,
    CfgTopSensorPosM     := SEL(HomingAtZero, CfgTopSensorPosM, 0.0),
    TopPositionSensor    := TopPositionSensor,
    RawPos               := instAbs.RawPos,
    EncoderAvailable     := instAbs.EncoderAvailable,
    PresetStatusBit      := HwIn.PresetStatusBit,
    Cfg                  := Cfg,
    PointsPerRev         := PointsPerRev,
    MultiTurnRevsMax     := 4096,
    CableM_PerRev        := CableM_PerRev,
    BypassGlobal         := BypassGlobal,
    Calib                := Calib
);
{endregion}

{region "§4 Scale"}
instScale(
    RawPos       := instAbs.RawPos,
    HomingRefRaw := instHoming.HomingRefRaw,
    CableM_PerRev := CableM_PerRev,
    PointsPerRev := PointsPerRev
);
{endregion}

{region "§5 Safety"}
instSafety(
    Enable             := Enable,
    Reset              := Reset,
    CablePosM          := instScale.CablePosM,
    HomingSuspect      := instHoming.HomingSuspect,
    PositionMinM       := PositionMinM,
    PositionMaxM       := PositionMaxM,
    BypassGlobal       := BypassGlobal
);
{endregion}

{region "§6 Reliability"}
instRel(
    EncoderAvailable  := instAbs.EncoderAvailable,
    Homed             := instHoming.Homed,
    EncoderIncoherent := instSafety.EncoderIncoherent
);
{endregion}

{region "§7 Speed"}
instSpeed(
    Enable        := Enable,
    Reset         := Reset,
    SpdValueIn    := HwIn.SpdValueIn,
    PositionValid := NOT instRel.EncoderFault,
    CableM_PerRev := CableM_PerRev
);
{endregion}

{region "§8 Remplissage struct et synthese"}
Measurement.RawPos            := instAbs.RawPos;
Measurement.EncoderAvailable  := instAbs.EncoderAvailable;
Measurement.CablePosM         := instSafety.CablePosMSafe;
Measurement.CablePosMSafe     := instSafety.CablePosMSafe;
Measurement.EncoderIncoherent := instSafety.EncoderIncoherent;
Measurement.Speed_Mps         := instSpeed.Speed_Mps;
Measurement.SignedSpeed_Mps   := instSpeed.SignedSpeed_Mps;
Measurement.SpeedValid        := instSpeed.Valid;
Measurement.HomingFault        := instHoming.Fault;
Measurement.HomingLifecycle    := instHoming.Lifecycle;
Measurement.AbsFault           := instAbs.Fault;
Measurement.HomingRefRaw      := instHoming.HomingRefRaw;

// Frontiere HW sortie (preset)
HwOut.PresetTriggerCmd := instAbs.PresetTriggerCmd;
HwOut.CodeSeqTriggerCmd := instAbs.CodeSeqTriggerCmd;
HwOut.PresetValueOut    := instAbs.PresetValueOut;

// Etats codeur
Homed            := instHoming.Homed;
HomingSuspect    := instHoming.HomingSuspect;
EncoderFault     := instRel.EncoderFault;
HomedAndReliable := instRel.HomedAndReliable;
PresetConfirmationFailed := instHoming.PresetConfirmationFailed;

// Synthese statut facade : brique defaut socle (Fault:ST_Fault), pattern FB_Joystick.
// Causes exprimees en CLAIR (ST_FaultCause), alimentees UNIQUEMENT depuis les sorties
// publiques des sous-FB (encapsulation stricte, jamais de lecture VAR interne).
//   - Cause 0/1 : LIVE (Latching=FALSE) -> Fault.Error, retombe seule.
//   - Cause 2   : LATCHED (Latching=TRUE) -> arme Fault.Latched, acquittee au Reset front.
// Interlock machine toujours sur les faits bruts (EncoderFault, HomedAndReliable,
// EncoderIncoherent), jamais sur Fault.Latched (conservation).
instCauses[0].Active := NOT instAbs.EncoderAvailable; instCauses[0].Latching := FALSE;
instCauses[0].Texte := 'Perte materiel / communication codeur EtherCAT';
instCauses[1].Active := instSafety.EncoderIncoherent; instCauses[1].Latching := FALSE;
instCauses[1].Texte := 'Incoherence mesure / saut de position codeur';
instCauses[2].Active := instHoming.PresetConfirmationFailed; instCauses[2].Latching := TRUE;
instCauses[2].Texte := 'Echec confirmation transaction preset codeur';

// Socle appele APRES le pipeline : causes du scan courant, aucun scan de retard (AC4).
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;     // source de verite = socle
Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§1 CAUSES + SOCLE (appele AVANT le gate)"}
// 🎯 CAUSES exprimées en CLAIR (liste ST_FaultCause) — plus de bitfield WORD.
//    - CalibFail : cause A ACQUITTER (Latching=TRUE) -> arme Fault.Latched.
//    - RawOutOfRange / BusLost : cause LIVE seulement (Latching=FALSE) -> Fault.Error, retombe seule.
//    Interlock sur la cause brute ; le socle gère latch/reset.
RawOutOfRange := (RawX < (0 - Cfg.RawOutOfRangeMargin))
              OR (RawX > (10000 + Cfg.RawOutOfRangeMargin))
              OR (RawY < (0 - Cfg.RawOutOfRangeMargin))
              OR (RawY > (10000 + Cfg.RawOutOfRangeMargin));
BusLost := (NOT BusCanOpenOP.Operational OR NOT JoystickOP.Operational);

// Calibration : un front (Calibrate) hors zone -> cause a acquitter. La cause reste active tant que
// les axes sont HORS zone valide [2000..8000] : Reset ne l'efface que si la cause a disparu
// (interlock socle sur la cause brute). Effacee par un Reset avec axes en zone.
IF Calibrate AND NOT LastCalibrate THEN
    IF RawX >= 2000 AND RawX <= 8000 AND RawY >= 2000 AND RawY <= 8000 THEN
        NeutralXMem := RawX;       // memorisation nouvelle position neutre X
        NeutralYMem := RawY;       // memorisation nouvelle position neutre Y
        CalibFail := FALSE;        // calibration valide : plus de cause
    ELSE
        CalibFail := TRUE;         // échec : cause a acquitter (persistante tant que hors zone)
    END_IF;
END_IF;
LastCalibrate := Calibrate;
// Ré-acquisition de la cause (front Reset + cause disparue) : n'efface la cause QUE si les
// axes sont revenus en zone valide. Reste latee tant que hors zone (interlock sur cause brute).
IF Reset AND (RawX >= 2000 AND RawX <= 8000 AND RawY >= 2000 AND RawY <= 8000) THEN
    CalibFail := FALSE;
END_IF;

// Remplissage de la LISTE de causes pour le socle (index 0..2)
// Cause en clair (Active/Latching/Texte) ; 3 causes fixes.
instCauses[0].Active := CalibFail;     instCauses[0].Latching := TRUE;
instCauses[0].Texte := 'Echec calibration joystick (RawX/Y hors zone)';
instCauses[1].Active := RawOutOfRange; instCauses[1].Latching := FALSE;
instCauses[1].Texte := 'Capteur joystick hors plage ADC';
instCauses[2].Active := BusLost;       instCauses[2].Latching := FALSE;
instCauses[2].Texte := 'Perte liaison bus CAN joystick';

// Appel du socle TOUJOURS (meme si le gate RETURN ensuite) : la cause bus doit etre vue.
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;     // source de verite = socle

// Disponibilite = Enable + bus OK + pas de defaut LATE. Une cause live (bus, capteur) ne latche pas
// -> elle n'entre pas dans Fault.Latched ; le bus est deja couvert par ...OP.Operational ci-dessous.
Ready := Enable AND BusCanOpenOP.Operational AND JoystickOP.Operational AND NOT Fault.Latched;
{endregion}

{region "§2 Gate securite (neutralisation pipeline, n efface pas le statut)"}
// 1. GATE — neutralise le pipeline si indisponible. Le statut a deja ete rempli (zone 0).
IF NOT Enable OR BusLost THEN
    AxisCmdX.Enable := FALSE; AxisCmdX.StartStop := FALSE; AxisCmdX.SpeedTgt := 0.0; AxisCmdX.StepTgt := 0;
    AxisCmdX.DirectionPositive := FALSE; AxisCmdX.DirectionNegative := FALSE; AxisCmdX.AtNeutral := TRUE;
    AxisCmdY.Enable := FALSE; AxisCmdY.StartStop := FALSE; AxisCmdY.SpeedTgt := 0.0; AxisCmdY.StepTgt := 0;
    AxisCmdY.DirectionPositive := FALSE; AxisCmdY.DirectionNegative := FALSE; AxisCmdY.AtNeutral := TRUE;
    AxisCmdX.Direction := 0; AxisCmdX.Deflection := 0;
    AxisCmdY.Direction := 0; AxisCmdY.Deflection := 0;
    AtNeutralXY := TRUE;
    DeadmanArmed := FALSE;
    DeadmanArmPending := FALSE;
    InversionLockActive := FALSE;
    PrevDirX := 0;
    PrevDirY := 0;
    ArmingPermitDenied := FALSE;
    NeutralXYEdge(CLK := FALSE);
    NeutralHoldTimer(IN := FALSE, PT := Cfg.NeutralHoldTime);
    DeadmanArmTimer(IN := FALSE, PT := Cfg.DeadmanArmHoldTime);
    DeadmanArmGraceTimer(IN := FALSE, PT := Cfg.DeadmanArmGraceTime);
    NeutralXAct := NeutralXMem;
    NeutralYAct := NeutralYMem;
    RETURN;
END_IF;
{endregion}

{region "§3 Acquisition + mise a l echelle"}
// Mise a l'echelle (deadband) - le neutre s'evalue sur les 2 axes
ScaleX(RawIn := RawX, Neutral := NeutralXMem, DeadbandRaw := Cfg.DeadbandRaw);
ScaleY(RawIn := RawY, Neutral := NeutralYMem, DeadbandRaw := Cfg.DeadbandRaw);
AtNeutralXY := (ScaleX.OutPct = 0.0) AND (ScaleY.OutPct = 0.0);   // les 2 axes en zone morte - permis mouvement
{endregion}

{region "§4 Armement homme mort"}
// 🔀 Inversion inter-scan : le sens n'est RETENU que si la déflexion dépasse
// CST_InversionFlipThreshold_Pct (>> bruit Hall / bord de deadband). Un aller-retour
// +1<->-1 sans échantillon 0 pose le verrou. Levé exclusivement au front AtNeutralXY.
// RawOutOfRange : lecture capteur non fiable -> aucun sens retenu (le geste est déjà forcé à 0
// par le SEL du pipeline). Une reprise capteur-défaut -> valide ne compte donc pas comme flip.
DirX := 0;
DirY := 0;
IF NOT RawOutOfRange THEN
    IF ScaleX.OutPct > CST_InversionFlipThreshold_Pct THEN
        DirX := 1;
    ELSIF ScaleX.OutPct < -CST_InversionFlipThreshold_Pct THEN
        DirX := -1;
    END_IF;
    IF ScaleY.OutPct > CST_InversionFlipThreshold_Pct THEN
        DirY := 1;
    ELSIF ScaleY.OutPct < -CST_InversionFlipThreshold_Pct THEN
        DirY := -1;
    END_IF;
END_IF;
FlipX := ((PrevDirX = 1) AND (DirX = -1)) OR ((PrevDirX = -1) AND (DirX = 1));
FlipY := ((PrevDirY = 1) AND (DirY = -1)) OR ((PrevDirY = -1) AND (DirY = 1));

NeutralXYEdge(CLK := AtNeutralXY);
IF NeutralXYEdge.Q THEN
    InversionLockActive := FALSE;
END_IF;

IF FlipX OR (FlipY AND NOT (DirectInversionPermit AND DeadmanArmed)) THEN
    InversionLockActive := TRUE;
    DeadmanArmed := FALSE;
    DeadmanArmPending := FALSE;
END_IF;

// Bouton homme-mort : armement par MAINTIEN (Cfg.DeadmanArmHoldTime), independant de la position.
// ⚠️ Un appui PENDANT le verrou d'inversion n'arme PAS de demande : le nouveau front conscient
//    doit survenir APRÈS le retour au neutre (sinon on "pré-charge" le réarmement stick inversé).
DeadmanEdge(CLK := RawButton);
IF DeadmanEdge.Q AND NOT InversionLockActive THEN DeadmanArmPending := TRUE; END_IF;
IF NOT RawButton THEN DeadmanArmPending := FALSE; END_IF;

// Securite : armage UNIQUEMENT si DeadmanArmPending ET ArmingPermit.
DeadmanArmTimer(IN := DeadmanArmPending AND NOT DeadmanArmed AND ArmingPermit AND NOT InversionLockActive, PT := Cfg.DeadmanArmHoldTime);
IF DeadmanArmTimer.Q THEN
    DeadmanArmed := TRUE;
    DeadmanArmPending := FALSE;
END_IF;

// Désarmement externe immédiat : le retrait d'ArmingPermit (changement de mode, fin de cycle
// benne) désarme TOUT DE SUITE le geste — pas d'armement résiduel "surprise" à la ré-acquisition.
IF NOT ArmingPermit THEN
    DeadmanArmed := FALSE;
    DeadmanArmPending := FALSE;
END_IF;

// Avertissement "armage non autorise" (niveau, pendant l'appui non autorise)
ArmingPermitDenied := RawButton AND NOT ArmingPermit;

// Desarmage par maintien au neutre (apres grace)
DeadmanArmGraceTimer(IN := DeadmanArmed, PT := Cfg.DeadmanArmGraceTime);
NeutralHoldTimer(IN := DeadmanArmed AND AtNeutralXY AND DeadmanArmGraceTimer.Q, PT := Cfg.NeutralHoldTime);
IF NeutralHoldTimer.Q THEN DeadmanArmed := FALSE; END_IF;
{endregion}

{region "§5 Pipeline axe X"}
CmdXVal := SEL(DeadmanArmed AND NOT RawOutOfRange, 0.0, ScaleX.OutPct);

AxisCmdX.Enable := NOT RawOutOfRange AND ArmingPermit;
AxisCmdX.SpeedTgt := ABS(CmdXVal);   // NON signee (le sens = bits DirectionPositive/Negative + AxisCmdX.Direction)
AxisCmdX.StartStop := (ABS(CmdXVal) > CST_DirectionQualificationThreshold_Pct);

AxisCmdX.DirectionPositive := (CmdXVal > CST_DirectionQualificationThreshold_Pct);
AxisCmdX.DirectionNegative := (CmdXVal < -CST_DirectionQualificationThreshold_Pct);
AxisCmdX.AtNeutral := NOT AxisCmdX.DirectionPositive AND NOT AxisCmdX.DirectionNegative;
IF AxisCmdX.AtNeutral THEN AxisCmdX.SpeedTgt := 0.0; END_IF;

// Projections monitoring dans le struct (les bits restent la source logique)
IF AxisCmdX.DirectionPositive THEN AxisCmdX.Direction := 1;
ELSIF AxisCmdX.DirectionNegative THEN AxisCmdX.Direction := -1;
ELSE AxisCmdX.Direction := 0; END_IF;
AxisCmdX.Deflection := REAL_TO_INT(CmdXVal);   // deflexion signee -100..+100 % (anim IHM)
{endregion}

{region "§6 Pipeline axe Y et sorties"}
CmdYVal := SEL(DeadmanArmed AND NOT RawOutOfRange, 0.0, ScaleY.OutPct);

AxisCmdY.Enable := NOT RawOutOfRange AND ArmingPermit;
AxisCmdY.SpeedTgt := ABS(CmdYVal);   // NON signee (le sens = bits DirectionPositive/Negative + AxisCmdY.Direction)
AxisCmdY.StartStop := (ABS(CmdYVal) > CST_DirectionQualificationThreshold_Pct);

AxisCmdY.DirectionPositive := (CmdYVal > CST_DirectionQualificationThreshold_Pct);
AxisCmdY.DirectionNegative := (CmdYVal < -CST_DirectionQualificationThreshold_Pct);
AxisCmdY.AtNeutral := NOT AxisCmdY.DirectionPositive AND NOT AxisCmdY.DirectionNegative;
IF AxisCmdY.AtNeutral THEN AxisCmdY.SpeedTgt := 0.0; END_IF;

// 🪜 Decodage consigne % -> palier (logique FB_Winch §5, deplacee au joystick).
//    AxisCmdY.SpeedTgt (%) reste pour l'IHM ; AxisCmdY.StepTgt (1..5, 0=arret) pour la logique/limitations.
SpeedStepHyst1(IN := REAL_TO_INT(AxisCmdY.SpeedTgt), HIGH := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[1] + Cfg.SpeedStepHystMargin), LOW := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[1] - Cfg.SpeedStepHystMargin));
SpeedStepHyst2(IN := REAL_TO_INT(AxisCmdY.SpeedTgt), HIGH := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[2] + Cfg.SpeedStepHystMargin), LOW := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[2] - Cfg.SpeedStepHystMargin));
SpeedStepHyst3(IN := REAL_TO_INT(AxisCmdY.SpeedTgt), HIGH := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[3] + Cfg.SpeedStepHystMargin), LOW := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[3] - Cfg.SpeedStepHystMargin));
SpeedStepHyst4(IN := REAL_TO_INT(AxisCmdY.SpeedTgt), HIGH := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[4] + Cfg.SpeedStepHystMargin), LOW := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[4] - Cfg.SpeedStepHystMargin));

// ⚠️ HYSTERESIS (Util CODESYS) est un hystérésis BAS : OUT=TRUE quand IN<LOW, OUT=FALSE
//    quand IN>HIGH. Pour un décodage ASCENDANT (petite déflexion → palier bas, grande →
//    palier haut) on teste donc `NOT OUT` : palier supérieur seulement une fois IN au-dessus
//    du seuil (bande d'hystérésis LOW..HIGH autour de StepThreshold_Pct[n]).
IF AxisCmdY.SpeedTgt <= CST_DirectionQualificationThreshold_Pct THEN
    AxisCmdY.StepTgt := 0;
ELSE
    AxisCmdY.StepTgt := 1;
    IF NOT SpeedStepHyst1.OUT THEN AxisCmdY.StepTgt := 2; END_IF;
    IF NOT SpeedStepHyst2.OUT THEN AxisCmdY.StepTgt := 3; END_IF;
    IF NOT SpeedStepHyst3.OUT THEN AxisCmdY.StepTgt := 4; END_IF;
    IF NOT SpeedStepHyst4.OUT THEN AxisCmdY.StepTgt := 5; END_IF;
END_IF;

// Projections monitoring dans le struct (les bits restent la source logique)
IF AxisCmdY.DirectionPositive THEN AxisCmdY.Direction := 1;
ELSIF AxisCmdY.DirectionNegative THEN AxisCmdY.Direction := -1;
ELSE AxisCmdY.Direction := 0; END_IF;
AxisCmdY.Deflection := REAL_TO_INT(CmdYVal);   // deflexion signee -100..+100 % (anim IHM)

// Memorisation apres traitement : l'inversion suivante compare deux scans qualifies successifs.
PrevDirX := DirX;
PrevDirY := DirY;

// Miroirs point neutre courant
NeutralXAct := NeutralXMem;
NeutralYAct := NeutralYMem;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. RESET FRONT
ResetEdge(CLK := Reset);

IF ResetEdge.Q OR BypassGlobal THEN
    PhaseRotationFault    := FALSE;
    BrakeThermalFault     := FALSE;
    MecaBFault            := FALSE;
    MecaAFault            := FALSE;
    SensorIncoherentFault := FALSE;
END_IF;

IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    PhaseRotationFault    := FALSE;
    BrakeThermalFault     := FALSE;
    MecaBFault            := FALSE;
    MecaAFault            := FALSE;
    SensorIncoherentFault := FALSE;
END_IF;

IF NOT BypassGlobal THEN
    TonStartupWarmup(IN := Enable, PT := T#3s);

    // Cause 0 : Perte com opérateur (live)
    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassOperatorComm) THEN
        instCauses[0].Active := (NOT JoystickOnline OR NOT JoystickOperational OR NOT HeartbeatIhmOk);
    ELSE
        instCauses[0].Active := FALSE;
    END_IF;
    instCauses[0].Latching := FALSE;
    instCauses[0].Texte    := 'Perte communication operateur translation';

    // Cause 1 : Perte EtherCAT drive (live)
    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassDriveComm) THEN
        instCauses[1].Active := (NOT DriveOnline OR NOT DriveOperational);
    ELSE
        instCauses[1].Active := FALSE;
    END_IF;
    instCauses[1].Latching := FALSE;
    instCauses[1].Texte    := 'Perte communication EtherCAT variateur M3';

    // Cause 2 : Rotation de phase (latched)
    IF NOT (BypassProcess OR BypassPhaseRotation) AND NOT PhaseRotationOk THEN
        PhaseRotationFault := TRUE;
    END_IF;
    instCauses[2].Active   := PhaseRotationFault;
    instCauses[2].Latching := TRUE;
    instCauses[2].Texte    := 'Defaut rotation de phases';

    // Cause 3 : Thermique frein (latched)
    IF NOT (BypassSafety OR BypassBrakeThermal) AND BrakeThermalFeedback THEN
        BrakeThermalFault := TRUE;
    END_IF;
    instCauses[3].Active   := BrakeThermalFault;
    instCauses[3].Latching := TRUE;
    instCauses[3].Texte    := 'Surchauffe thermique frein translation';

    // Cause 4 : Méca B (latched)
    // ⚠️ Éval gardée par la comm drive (DriveOnline AND DriveOperational) : sans comm, le
    //    statusword / la fréquence remontés ne sont pas fiables. Une perte bus doit tomber en
    //    Cause 1 (DriveComm, bit1 -> SafeStop acquittable), PAS en Méca B (bit4 -> PowerCutOff
    //    non-resettable). DriveStatusWord.0 (= "ready to switch on")
    //    figé sur bus mort -> coupure chaîne intempestive.
    // Déclencheur = preuve de rotation RÉELLE (fréquence de sortie mesurée) OU retour frein
    // encore ouvert. DriveStatusWord.0 ("ready to switch on") retiré : à 1 dès variateur
    // alimenté, il ne prouve PAS un mouvement.
    IF NOT (BypassSafety OR BypassMecaB) AND DriveOnline AND DriveOperational THEN
        IF (NOT HeartbeatIhmOk) OR (NOT RunRequest AND NOT BrakeCmd) THEN
            UncommandedActiveB := (ABS(DriveActualFreqHz) > CST_StopFreqThresholdHz) OR BrakeFeedback;
        ELSE
            UncommandedActiveB := FALSE;
        END_IF;
        TonMecaB(IN := UncommandedActiveB, PT := PostRampTimeout);
        IF TonMecaB.Q THEN MecaBFault := TRUE; END_IF;
    ELSE
        TonMecaB(IN := FALSE);
    END_IF;
    instCauses[4].Active   := MecaBFault;
    instCauses[4].Latching := TRUE;
    instCauses[4].Texte    := 'Absence confirmation arret translation (Meca B)';

    // Cause 5 : Méca A (latched)
    IF NOT (BypassSafety OR BypassMecaA) THEN
        IF NOT RunRequest AND NOT BrakeCmd THEN
            UncommandedActiveA := ABS(DriveActualFreqHz) > 0.5;
        ELSE
            UncommandedActiveA := FALSE;
        END_IF;
        TonMecaA(IN := UncommandedActiveA, PT := PostRampTimeoutMecaA);
        IF TonMecaA.Q THEN MecaAFault := TRUE; END_IF;
    ELSE
        TonMecaA(IN := FALSE);
    END_IF;
    instCauses[5].Active   := MecaAFault;
    instCauses[5].Latching := TRUE;
    instCauses[5].Texte    := 'Mouvement non commande translation (Meca A)';

    // Cause 6 : Limite extrême escalade (live)
    // REVERT 2026-09-04 : le retrait de DriveStatusWord.0 n'a jamais ete confirme comme la
    // cause reelle d'un defaut terrain (le defaut rapporte etait en realite bit0/MecaB,
    // pas cette cause 6) -> pas de modif safety sans confirmation terrain, retour a l'origine.
    IF NOT (BypassSafety OR BypassLimitSwitch) THEN
        OverrunCondition := (LimitSwitchTremie AND ReqTremie AND (ABS(DriveActualFreqHz) > 0.5 OR DriveStatusWord.0))
                         OR (LimitSwitchMaintenance AND ReqMaintenance AND (ABS(DriveActualFreqHz) > 0.5 OR DriveStatusWord.0));
        TonLimitSwitchOverrun(IN := OverrunCondition, PT := T#1S500MS);
        instCauses[6].Active := TonLimitSwitchOverrun.Q;
    ELSE
        TonLimitSwitchOverrun(IN := FALSE);
        instCauses[6].Active := FALSE;
    END_IF;
    instCauses[6].Latching := FALSE;
    instCauses[6].Texte    := 'Depassement limite extreme translation';

    // Cause 7 : Mot capteurs incohérent (latched)
    IF NOT (BypassSafety OR BypassSensorIncoherent) AND SensorWordIncoherent THEN
        SensorIncoherentFault := TRUE;
    END_IF;
    instCauses[7].Active   := SensorIncoherentFault;
    instCauses[7].Latching := TRUE;
    instCauses[7].Texte    := 'Incoherence combinaison capteurs translation';

ELSE
    TonMecaB(IN := FALSE);
    TonMecaA(IN := FALSE);
    TonLimitSwitchOverrun(IN := FALSE);

    // 🧪 BypassGlobal : l'évaluation des causes ci-dessus est sautée. Purge de la vue LIVE
    // pour que instCauses[i].Active ne reste pas FIGÉ (sinon PowerCutOff / SafeStop gelés,
    // réarmement impossible malgré le bypass). Latches déjà effacés au § FRONTS & REARMENT.
    FOR CauseIdx := 0 TO 15 DO
        instCauses[CauseIdx].Active := FALSE;
    END_FOR;
END_IF;

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable THEN
    SafeStop := FALSE;
    PowerCutOff := FALSE;
    ErrorOperatorComm := FALSE;
    ErrorDriveComm := FALSE;
    ErrorPhaseRotation := FALSE;
    ErrorBrakeThermal := FALSE;
    ErrorMecaB := FALSE;
    ErrorMecaA := FALSE;
    ErrorLimitSwitch := FALSE;
    ErrorSensorIncoherent := FALSE;
    TremieLimitClear := FALSE;
    MaintenanceLimitClear := FALSE;
    TonMecaB(IN := FALSE);
    TonMecaA(IN := FALSE);
    TonLimitSwitchOverrun(IN := FALSE);
    TonStartupWarmup(IN := FALSE);
    Ready := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Sorties sécurités et drapeaux IHM"}
// 📤 3. SORTIES SÉCURITÉ & DRAPEAUX
SafeStop := Fault.Error OR NOT PowerContactorEngaged;

// PowerCutOff actif si bits 3..7 actifs (causes physiques)
PowerCutOff := (Fault.ErrorId AND 16#00F8) <> 16#0000;

ErrorOperatorComm     := instCauses[0].Active;
ErrorDriveComm        := instCauses[1].Active;
ErrorPhaseRotation    := instCauses[2].Active;
ErrorBrakeThermal     := instCauses[3].Active;
ErrorMecaB            := instCauses[4].Active;
ErrorMecaA            := instCauses[5].Active;
ErrorLimitSwitch      := instCauses[6].Active;
ErrorSensorIncoherent := instCauses[7].Active;

// 🛡️ Permis directionnels M3 — NIVEAU SAFETY (polarité fail-safe : TRUE = autorisé)
// ⚠️ Ces sorties sont des permits directionnels SAFETY (pur directionnel), PAS le permit
// EFFECTIF « pouvoir bouger ». Le permit effectif (prêt à fonctionner) est calculé en
// PRG_05_Translation §1ter : Safety directionnel AND NOT M3_SafeStop_Aggregate AND NOT
// PowerCutOff. C'est LUI qui reflète la sémantique « pouvoir bouger » : quand l'axe est en
// défaut (SafeStop/PowerCutOff), TOUS les sens sont bloqués ; au retour en condition, un sens
// La décision des huit permis est produite en PRG_05. Ce FB ne produit que les faits
// de sécurité nécessaires à cette décision : les deux fins de course sont-elles libres ?
// Le droit d'accès à la zone Maintenance (MaintenanceM3TargetEnable) est volontairement
// séparé : il ne doit pas empêcher le déplacement légal jusqu'à P1.
TremieLimitClear := NOT LimitSwitchTremie;
MaintenanceLimitClear := NOT LimitSwitchMaintenance;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. RESET FRONT
ResetEdge(CLK := Reset);

IF ResetEdge.Q THEN
    DriveFaultLatching := FALSE;
    DriveResetPulseActive := Enable;
END_IF;

DriveResetPulseTimer(IN := DriveResetPulseActive, PT := CST_DriveResetPulseTime);
IF DriveResetPulseTimer.Q OR NOT Enable THEN
    DriveResetPulseActive := FALSE;
END_IF;

IF DriveStatusWord.4 THEN
    DriveFaultLatching := TRUE;
END_IF;

instCauses[0].Active   := Brake.Fault.Error;
instCauses[0].Latching := FALSE;
instCauses[0].Texte    := 'Defaut sequence ou retour frein translation';

instCauses[3].Active   := DriveFaultLatching;
instCauses[3].Latching := TRUE;
instCauses[3].Texte    := 'Defaut variateur translation AC600';

// REX MES 2026-09-04 (trace Suivi_TranslationM3bug_20260904_27) : ce test se declenchait
// INSTANTANEMENT a chaque arrivee NOMINALE sur le FdC (CommandedTremie ET LimitSwitchTremie
// sont vrais des le 1er scan d'une arrivee normale, avant meme que la decel soit terminee)
// -> Fault.Error pulse -> §6 force BrakeReleaseRequest:=FALSE en ecrasant Brake.BrakeCmd
// pendant que FB_Brake pense toujours commander l'ouverture (son propre MovementRequested
// reste vrai le temps du coast ~600ms) -> incoherence commande/retour frein -> latch
// definitif dans FB_Brake. On ne fault desormais que sur un DEPASSEMENT REEL : encore
// commande vers le FdC, sur le FdC, ET reellement en train de tourner (pas juste en decel),
// soutenu 1.5s (meme garde que FB_Safety_Translation Cause 6).
OverrunLimitSwitch := NOT BypassLimitSwitch
    AND ((CommandedTremie AND LimitSwitchTremie) OR (CommandedMaintenance AND LimitSwitchMaintenance))
    AND (ABS(DriveActualFreqHz) > 0.5);
TonLimitSwitchOverrun(IN := OverrunLimitSwitch, PT := T#1S500MS);
instCauses[6].Active := TonLimitSwitchOverrun.Q;
instCauses[6].Latching := FALSE;
instCauses[6].Texte    := 'Limite extreme translation atteinte';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable THEN
    SpeedRamp(Target := 0.0, AccelRate := 0.0, DecelRate := 100000.0, CycleTimeS := 1.0);
    Brake(Enable := FALSE);
    RequestedDriveControlWord := 0;
    RequestedDriveFreqHz := 0.0;
    BrakeReleaseRequest := FALSE;
    BrakeCommandOpenConfirmed := FALSE;
    BrakeContactorCheck.Command := FALSE;
    BrakeContactorCheck.Feedback := BrakeFeedback;
    CommandedTremie := FALSE;
    CommandedMaintenance := FALSE;
    DirectionChangePending := FALSE;
    ArrivalLock := FALSE;
    ArrivalIsExtreme := FALSE;
    ArrivalWasTremie := FALSE;
    ArrivalWasMaintenance := FALSE;
    LastMoveDirection := 0;
    ArrivalStopConfirmed := FALSE;
    TargetReached := FALSE;
    DirectionChangeDelay(IN := FALSE);
    CaptorDebounceTon(IN := FALSE);
    TonBrakeRealFreqTimeout(IN := FALSE);
    Ready := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Premier scan et temps de cycle"}
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    CommandedTremie := FALSE;
    CommandedMaintenance := FALSE;
END_IF;

CycleTimeCalc();
{endregion}

{region "§4 Arrivée sur cible et interlock direction"}
CaptorDebounceTon(IN := PositionSensorTarget, PT := Cfg.CaptorDebounce);
TargetReached := CaptorDebounceTon.Q;
ArrivalEdge(CLK := TargetReached);

// 🧠 Sens du dernier mouvement réellement commandé : mémoire PROPRE À L'AXE, mise à jour
// avant la lecture du front d'arrivée (CommandedTremie/CommandedMaintenance portent encore
// le sens du scan précédent) et jamais remise à zéro par la perte de la demande — contrairement
// à ces deux locaux, qui retombent dès que la demande disparaît (§4 ci-dessous). C'est cette
// mémoire qui qualifie le sens d'arrivée quand la demande est retirée avant la fin du debounce.
IF CommandedTremie THEN
    LastMoveDirection := 1;
ELSIF CommandedMaintenance THEN
    LastMoveDirection := -1;
END_IF;

// Arrivée sur une extrémité réelle uniquement (Trémie/Maintenance), jamais un point
// intermédiaire (P1/P2/PV) : LimitSwitchMaintenance porte déjà la règle métier "P1 compte
// comme extrémité quand Maintenance est interdite comme cible" (PRG_05_Translation §0ter),
// donc aucune redondance de logique ici, juste sa consommation.
ArrivalIsExtreme := ((LastMoveDirection = 1) AND LimitSwitchTremie)
                  OR ((LastMoveDirection = -1) AND LimitSwitchMaintenance);

IF ArrivalEdge.Q AND ArrivalIsExtreme THEN
    ArrivalLock := TRUE;
    IF CommandedTremie OR CommandedMaintenance THEN
        ArrivalWasTremie := CommandedTremie;
        ArrivalWasMaintenance := CommandedMaintenance;
    ELSE
        // Demande déjà retombée : le sens d'arrivée est pris sur la mémoire du dernier
        // mouvement. Sans elle, les deux drapeaux seraient FALSE et la condition de
        // relâchement ci-dessous accepterait une demande du MÊME sens — le verrou
        // d'arrivée perdrait toute autorité et le chariot serait relancé au-delà du point
        // d'arrêt (relance + dépassement). Cas nominal du séquenceur : il retire sa demande
        // sur le jeton d'arrivée, soit 100 ms avant l'armement de ce verrou.
        ArrivalWasTremie := (LastMoveDirection = 1);
        ArrivalWasMaintenance := (LastMoveDirection = -1);
    END_IF;
END_IF;

// Verrou d'arrivee extreme M3 : le FdC securite est une preuve d'arret de sens,
// meme si le capteur de position cible n'a pas encore produit son front (cas
// d'arrivee rapide / decalage de scans). On ne ferme pas le frein ici : le verrou
// ne fait que maintenir la rampe a zero et empecher une re-demande du meme sens.
// Liberation uniquement par une demande explicite du sens inverse (logique ci-dessous).
IF NOT BypassLimitSwitch THEN
    IF CommandedTremie AND LimitSwitchTremie THEN
        ArrivalLock := TRUE;
        ArrivalWasTremie := TRUE;
        ArrivalWasMaintenance := FALSE;
    ELSIF CommandedMaintenance AND LimitSwitchMaintenance THEN
        ArrivalLock := TRUE;
        ArrivalWasTremie := FALSE;
        ArrivalWasMaintenance := TRUE;
    END_IF;
END_IF;

IF ArrivalLock AND ((ReqTremie AND NOT ArrivalWasTremie) OR (ReqMaintenance AND NOT ArrivalWasMaintenance)) THEN
    ArrivalLock := FALSE;
END_IF;

DirectionChangeDelay(
    IN := (ReqTremie OR ReqMaintenance)
          AND ((ReqTremie AND NOT CommandedTremie) OR (ReqMaintenance AND NOT CommandedMaintenance))
          AND (ABS(SpeedRamp.Current) <= 0.1)
          AND (ABS(DriveActualFreqHz) <= 0.5),
    PT := Cfg.DirectionInterlockDelay
);

IF NOT (CommandedTremie OR CommandedMaintenance) AND (ReqTremie OR ReqMaintenance) THEN
    CommandedTremie := ReqTremie;
    CommandedMaintenance := ReqMaintenance;
    DirectionChangePending := FALSE;
ELSIF DirectionChangeDelay.Q THEN
    CommandedTremie := ReqTremie;
    CommandedMaintenance := ReqMaintenance;
    DirectionChangePending := FALSE;
ELSIF (ReqTremie OR ReqMaintenance)
      AND ((ReqTremie AND NOT CommandedTremie) OR (ReqMaintenance AND NOT CommandedMaintenance)) THEN
    DirectionChangePending := TRUE;
ELSE
    DirectionChangePending := FALSE;
END_IF;

IF NOT (ReqTremie OR ReqMaintenance) THEN
    CommandedTremie := FALSE;
    CommandedMaintenance := FALSE;
    DirectionChangePending := FALSE;
END_IF;
{endregion}

{region "§4bis Permis directionnels et EffectiveSafeStop"}
// 🛡️ 4bis. GATE DE SENS (permis directionnels SAFETY) — modèle treuils FB_Winch
// RampStopActive = SafeStop OR demande vers un sens non permis. Bloque la RAMPE
// (arrêt réel) vers un sens non autorisé sans fabriquer de sens numérique.
// Consommé dans la gate de rampe (§5) et le choix de décélération.
// Le permis Maintenance représente la possibilité de rejoindre P1/maintenance physique ;
// l'interdiction d'accès à la zone Maintenance est gérée séparément par la cible P1 et sa
// coupure dure, sans couper le déplacement légal jusqu'à P1.
EffectiveSafeStop := SafeStop
                      OR (ReqTremie AND NOT EffectivePermitM3_Tremie)
                      OR (ReqMaintenance AND NOT EffectivePermitM3_Maintenance)
                      OR (ReqTremie AND ReqMaintenance);
{endregion}

{region "§5 Consigne et rampe de vitesse"}
IF DirectionChangePending OR NOT (ReqTremie OR ReqMaintenance) OR ArrivalLock OR EffectiveSafeStop OR NOT RunRequest THEN
    RampTargetPct := 0.0;
ELSE
    RampTargetPct := LIMIT(0.0, SpeedTgt_Pct, 100.0);
END_IF;

SpeedRamp(
    Target := RampTargetPct,
    AccelRate := Cfg.CfgRampAccelRate,
    DecelRate := SEL(EffectiveSafeStop, Cfg.CfgRampDecelNormalRate, Cfg.CfgRampDecelFastRate),
    CycleTimeS := CycleTimeCalc.CycleTimeS
);
{endregion}

{region "§6 Commande variateur et frein"}
TonBrakeRealFreqTimeout(
    IN := (RampTargetPct <= 0.1) AND (ABS(SpeedRamp.Current) <= 0.1),
    PT := T#2S
);

MovementRequested := (ABS(SpeedRamp.Current) > 0.1)
                  OR ((ABS(DriveActualFreqHz) > 0.5) AND NOT TonBrakeRealFreqTimeout.Q);

Brake(
    Enable := Enable,
    Reset := Reset,
    MovementRequested := MovementRequested,
    ContactorFeedback := BrakeFeedback,
    BypassContactorCheck := BypassContactorCheck,
    DelayContactClose := Cfg.BrakeDelayContactClose,
    DelayMagnetise := Cfg.BrakeDelayMagnetise,
    DelayMotorDecel := Cfg.BrakeDelayMotorDecel,
    FeedbackTimeout := Cfg.BrakeFeedbackTimeout
);

BrakeReleaseRequest := Brake.BrakeCmd;
BrakeCommandOpenConfirmed := Brake.BrakeCommandOpenConfirmed;
BrakeContactorCheck := Brake.ContactorCheck;

PhysicalTremie := CommandedTremie;
PhysicalMaintenance := CommandedMaintenance;
IF InvertDriveDirection THEN
    PhysicalTremie := CommandedMaintenance;
    PhysicalMaintenance := CommandedTremie;
END_IF;

IF PhysicalTremie AND Brake.BrakeCmd THEN
    RequestedDriveControlWord := 1; // FWD
ELSIF PhysicalMaintenance AND Brake.BrakeCmd THEN
    RequestedDriveControlWord := 2; // REV
ELSE
    RequestedDriveControlWord := 0;
END_IF;

RequestedDriveFreqHz := (SpeedRamp.Current / 100.0) * Cfg.DriveFreqScaleMaxHz;

// Ralentissements d'approche
IF CommandedTremie AND SlowdownSensorTremie THEN
    RequestedDriveFreqHz := MIN(RequestedDriveFreqHz, Cfg.ApproachSpeedTremieHz);
ELSIF CommandedMaintenance AND SlowdownSensorMaintenance THEN
    RequestedDriveFreqHz := MIN(RequestedDriveFreqHz, Cfg.ApproachSpeedMaintenanceHz);
ELSIF CommandedMaintenance AND SlowdownSensorP1 THEN
    RequestedDriveFreqHz := MIN(RequestedDriveFreqHz, Cfg.ApproachSpeedP1Hz);
END_IF;

IF Fault.Error THEN
    RequestedDriveControlWord := 0;
    RequestedDriveFreqHz := 0.0;
    BrakeReleaseRequest := FALSE;
END_IF;

IF DriveResetPulseActive THEN
    RequestedDriveControlWord := WORD#7;
    RequestedDriveFreqHz := 0.0;
    BrakeReleaseRequest := FALSE;
END_IF;

// 🎯 FAIT PUBLIC D'ARRÊT CONFIRMÉ : vrai quand l'axe a armé son verrou d'arrivée ET qu'il est
// physiquement arrêté — aucune rotation réelle au variateur (seuil 0,5 Hz, même mesure que
// Translation_Busy côté programme) et frein non commandé ouvert. Ce n'est donc pas une simple
// reprise du capteur : c'est la conjonction du verrou de l'axe et de l'arrêt physique, fait
// consommable par la porte de transition de cycle pour n'avancer qu'après un arrêt acquis.
// ⚠️ Au banc la fréquence réelle est nulle en permanence : ce fait s'y prouve par injection
// d'entrée (DriveActualFreqHz), jamais par la seule observation du banc.
ArrivalStopConfirmed := ArrivalLock
                        AND NOT Fault.Error
                        AND (ABS(DriveActualFreqHz) <= 0.5)
                        AND NOT BrakeReleaseRequest;
{endregion}

// === IMPLEMENTATION ===

Ready := Enable;

// Les deux bits de sens sont reconstruits à chaque cycle : aucune demande ne doit
// rester mémorisée lors d'un changement de source (IHM/joystick/cycle).
RunRequest      := FALSE;
ReqTremie       := FALSE;
ReqMaintenance  := FALSE;
CommandConflict := FALSE;

IF NOT Enable THEN
    RunRequest        := FALSE;
    ReqTremie         := FALSE;
    ReqMaintenance    := FALSE;
    CommandConflict   := FALSE;
    SpeedPct          := 0.0;
    PositioningActive := FALSE;
    SelTarget         := 0;
ELSE
    // ── Pont SEMI_AUTO : consomme la demande du séquenceur de cycle ──
    IF Auth.Mode = E_Mode.SEMI_AUTO THEN
        PositioningActive := TRUE;
        SelTarget := ReqTranslation.PositionTgt;
        // PositionTgt=3 (P1) en AX2 : jog bidirectionnel autorisé, mais la
        // cible d'arrêt reste P1 dans FB_Translation.
        CycleTargetDirectionOk := (SelTarget = 3)
                               OR ((SelTarget = 1) AND Joystick.AxisX.DirectionPositive)
                               OR ((SelTarget <> 1) AND Joystick.AxisX.DirectionNegative);
        CycleJoystickAxisOk := CycleTargetDirectionOk AND Joystick.AxisY.AtNeutral;
        RunRequest := ReqTranslation.ReqStart AND Context.HeightInterlockOk AND CycleJoystickAxisOk;
        IF RunRequest THEN
            SpeedPct := 100.0;
            IF (SelTarget = 1)
               OR ((SelTarget = 3) AND Joystick.AxisX.DirectionPositive) THEN
                ReqTremie := TRUE;
            ELSE
                ReqMaintenance := TRUE;
            END_IF;
        ELSE
            SpeedPct := 0.0;
        END_IF;
    ELSIF (Auth.Mode = E_Mode.MAINT_N1) OR (Auth.Mode = E_Mode.MAINT_N2) THEN
        // ── Mode maintenance : jog joystick ou boutons IHM ──
        PositioningActive := IHM.SelPositioning;
        SelTarget := 0;

        IF NOT TglJoystickMaster AND IHM.BtnTremie THEN
            ReqTremie := TRUE;
        ELSIF NOT TglJoystickMaster AND IHM.BtnMaintenance THEN
            ReqMaintenance := TRUE;
        ELSIF TglJoystickMaster THEN
            ReqTremie := Joystick.AxisX.DirectionPositive;
            ReqMaintenance := Joystick.AxisX.DirectionNegative;
        END_IF;

        // Homme-mort exigé même pour boutons IHM en MAINT_N1/N2.
        // ⚠️ Tautologie conservée bit-identique : (BypassGlobal OR NOT Tgl OR Tgl) = toujours TRUE.
        RunRequest := (ReqTremie OR ReqMaintenance)
                     AND (IHM.BypassGlobal OR NOT TglJoystickMaster OR TglJoystickMaster)
                     AND Joystick.DeadmanArmed
                     // Interlock inter-axes : un ordre treuil Y bloque M3.
                     AND (NOT TglJoystickMaster OR (Joystick.AxisY.Direction = 0))
                     AND Context.HeightInterlockOk;

        // Échelle fréquence : SetFreq_Hz (ou 100% si non renseignée), manche mis à l'échelle si joystick maître
        FreqPct := SEL(IHM.SetFreq_Hz > 0.0,
                       100.0,
                       (IHM.SetFreq_Hz / SEL(Cfg.MaxFreq_Hz > 0.0, 50.0, Cfg.MaxFreq_Hz)) * 100.0);
        SpeedPct := SEL(TglJoystickMaster,
                        FreqPct,
                        (ABS(Joystick.AxisX.SpeedTgt) / 100.0) * FreqPct);
    ELSE
        // ── Autres modes : neutralisé ──
        PositioningActive := FALSE;
        SelTarget := 0;
        RunRequest := FALSE;
        SpeedPct  := 0.0;
    END_IF;
END_IF;

// Une demande contradictoire est toujours neutralisée. RunRequest reste vrai afin de
// conserver la sémantique de décélération de FB_Translation ; aucune direction n'est choisie.
CommandConflict := ReqTremie AND ReqMaintenance;
IF CommandConflict THEN
    ReqTremie := FALSE;
    ReqMaintenance := FALSE;
END_IF;

// Clamp consigne (bit-identique PRG_05 §1)
SpeedPct := LIMIT(0.0, ABS(SpeedPct), 100.0);

// SelTarget = Maintenance (4) interdit si Maintenance non autorisée
IF (SelTarget = 4) AND NOT Auth.MaintenanceM3TargetEnable THEN
    SelTarget := 0;
END_IF;

// === IMPLEMENTATION ===

{region "§1 Assemblage mot et cohérence"}
// 🧾 Assemblage du mot (bit4=Trémie ... bit0=Maintenance, ordre doc AF_Partie-02 §3bis)
SensorsWord := 0;
IF SensorTremie      THEN SensorsWord := SensorsWord OR 16#10; END_IF;
IF SensorPV          THEN SensorsWord := SensorsWord OR 16#08; END_IF;
IF SensorP2          THEN SensorsWord := SensorsWord OR 16#04; END_IF;
IF SensorP1          THEN SensorsWord := SensorsWord OR 16#02; END_IF;
IF SensorMaintenance THEN SensorsWord := SensorsWord OR 16#01; END_IF;

// 🎯 Les 6 combinaisons valides (progression monotone décroissante Trémie→Maintenance)
CASE SensorsWord OF
    2#11111, 2#01111, 2#00111, 2#00011, 2#00001, 2#00000:
        Incoherent := FALSE;
    ELSE
        Incoherent := TRUE;
END_CASE;

// 🚧 Limites extrêmes — uniquement sur mot valide (évite un Fdc fantôme déclenché par une incohérence)
LimitSwitchTremie := (NOT Incoherent) AND (SensorsWord = 2#11111);
LimitSwitchMaintenance := (NOT Incoherent) AND (SensorsWord = 2#00000);
{endregion}

{region "§2 Reprise capteurs"}
// Reprise des capteurs de position pour les consommateurs aval (passthrough, identique à l'entrée filtrée)
// ⚠️ CUMULATIF — voir avertissement en déclaration, réservé au ralentissement d'approche.
TranslationPosTremie      := SensorTremie;
TranslationPosPV          := SensorPV;
TranslationPosP2          := SensorP2;
TranslationPosP1          := SensorP1;
TranslationPosMaintenance := SensorMaintenance;
{endregion}

{region "§3 Fronts individuels"}
// Front individuel par capteur — voir avertissement en déclaration. Transitoire (1 cycle),
// mémorisé par l'appelant.
EdgeUpTremie(CLK := SensorTremie);           EdgeDnTremie(CLK := SensorTremie);
EdgeUpPV(CLK := SensorPV);                   EdgeDnPV(CLK := SensorPV);
EdgeUpP2(CLK := SensorP2);                   EdgeDnP2(CLK := SensorP2);
EdgeUpP1(CLK := SensorP1);                   EdgeDnP1(CLK := SensorP1);
EdgeUpMaintenance(CLK := SensorMaintenance); EdgeDnMaintenance(CLK := SensorMaintenance);

// Front du capteur PROPRE à chaque position — voir modèle en déclaration.
// Extrémités : un seul sens valide chacune. Points intermédiaires : les deux fronts de LEUR PROPRE
// capteur (montant = atteint en venant de Maintenance, descendant = dépassé en venant de Trémie).
TranslationAtTremie      := EdgeUpTremie.Q;
TranslationAtPV          := EdgeUpPV.Q OR EdgeDnPV.Q;
TranslationAtP2          := EdgeUpP2.Q OR EdgeDnP2.Q;
TranslationAtP1          := EdgeUpP1.Q OR EdgeDnP1.Q;
TranslationAtMaintenance := EdgeDnMaintenance.Q;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Gate et initialisation"}
IF NOT Enable THEN
    Recalibrated := FALSE;
    RecalibratedSensorId := -1;
    RecalibrationAnomaly := FALSE;
    // 🔒 Sorties odométriques VOLONTAIREMENT conservées hors Enable (AC3 / persistance continue RETAIN) :
    // - PositionEstimatedM & Initialized : estimation odométrique et référence absolue maintenues pour ne pas perdre la position M3 hors Enable
    RETURN;
END_IF;

IF ColdStart THEN
    PositionEstimatedM := PersistedPositionM;
    Initialized := PersistedInitialized;
    ColdStart := FALSE;
END_IF;

CycleTimeCalc(DefaultValueS := 0.010);
Recalibrated := FALSE;
RecalibrationAnomaly := FALSE;   (* T361 : témoin à pulse, remis à zéro à chaque scan comme Recalibrated *)
{endregion}

{region "§2 Fronts capteurs"}
// 1. Détection des fronts sur franchissement des capteurs fixes — MONTANT ET DESCENDANT.
//    Les 5 capteurs forment un mot thermomètre CUMULATIF (FB_Translation_PositionDecoder :
//    bit_X = TRUE ssi position <= cote_X). Chaque capteur bascule donc à SA cote dans les DEUX
//    sens : front MONTANT en venant de Maintenance (trajet vers la Trémie), front DESCENDANT en
//    allant vers la Maintenance. Ne consommer que le front montant ne recalait que le trajet
//    vers la Trémie — et JAMAIS l'arrivée en Maintenance, dont le mot 00000 est justement le
//    front DESCENDANT du capteur Maintenance (front montant = départ de Maintenance).
TrigTremie(CLK := SensorTremie);              TrigDnTremie(CLK := SensorTremie);
TrigPV(CLK := SensorPV);                      TrigDnPV(CLK := SensorPV);
TrigP2(CLK := SensorP2);                      TrigDnP2(CLK := SensorP2);
TrigP1(CLK := SensorP1);                      TrigDnP1(CLK := SensorP1);
TrigMaintenance(CLK := SensorMaintenance);    TrigDnMaintenance(CLK := SensorMaintenance);
{endregion}

{region "§3 Recalage et intégration"}
// 2. Recalage absolu sur franchissement capteur — sur front MONTANT ou DESCENDANT, et
//    UNIQUEMENT après le premier scan utile.
//    Au 1er scan, un capteur "déjà présent" à l'initialisation (sim démarre à la trémie :
//    5 capteurs actifs) n'est pas un franchissement réel ; sinon le recalage IF/ELSIF
//    partirait de Maintenance (premier dans l'ordre) et écraserait la position à 30 m.
//    Ordre de priorité inchangé (Maintenance -> P1 -> P2 -> PV -> Trémie) : sur un mot
//    thermomètre une seule bascule survient par scan, la priorité ne départage donc qu'un mot
//    incohérent (capteur collé / parasite), cas déjà surveillé par le décodeur (Incoherent).
PositionBeforeM := PositionEstimatedM;   (* T361 : référence de mesure, AVANT tout recalage de ce scan *)
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
ELSE
    IF TrigMaintenance.Q OR TrigDnMaintenance.Q THEN
        PositionEstimatedM := PosMaintenanceM;
        Recalibrated := TRUE;
        RecalibratedSensorId := 0;
    ELSIF TrigP1.Q OR TrigDnP1.Q THEN
        PositionEstimatedM := PosP1M;
        Recalibrated := TRUE;
        RecalibratedSensorId := 1;
    ELSIF TrigP2.Q OR TrigDnP2.Q THEN
        PositionEstimatedM := PosP2M;
        Recalibrated := TRUE;
        RecalibratedSensorId := 2;
    ELSIF TrigPV.Q OR TrigDnPV.Q THEN
        PositionEstimatedM := PosPVM;
        Recalibrated := TRUE;
        RecalibratedSensorId := 3;
    ELSIF TrigTremie.Q OR TrigDnTremie.Q THEN
        PositionEstimatedM := PosTremieM;
        Recalibrated := TRUE;
        RecalibratedSensorId := 4;
    END_IF;
END_IF;

// 2bis. T361 — TÉMOIN D'ANOMALIE DE RECALAGE : OBSERVER, JAMAIS BLOQUER.
// Le recalage ci-dessus est TOUJOURS appliqué, sans condition : le capteur franchi reste la
// meilleure référence absolue disponible, et refuser la correction laisserait une position FAUSSE
// ET NON CORRIGÉE. Ce bloc ne fait que MESURER la correction effectivement appliquée et PUBLIER
// l'anomalie au-delà de CST_RecalibrationAnomalyM — c'est précisément ce qui a manqué sur la trace
// Suivi_74 : des sauts de 4,53 à 9,12 m (audit T360) qui n'ont été vus qu'en post-mortem.
// 🔒 Le seuil ci-dessous ne doit JAMAIS devenir une condition des affectations `PositionEstimatedM`
// du bloc 2 : ce serait refuser un recalage légitime, l'erreur exacte que le gate G520 interdit.
// La décision Q2 du lot T333 (recaler sans garde tant que T301 n'a pas calibré le gain) reste la
// règle — l'anomalie est un témoin de diagnostic, pas un verrou.
IF Recalibrated THEN
    RecalibrationCorrectionM := ABS(PositionEstimatedM - PositionBeforeM);
    RecalibrationAnomaly := RecalibrationCorrectionM > CST_RecalibrationAnomalyM;
END_IF;

// 3. Initialisation au tout premier démarrage sur le premier capteur actif vu (si non initialisé)
IF NOT Initialized THEN
    IF SensorTremie THEN PositionEstimatedM := PosTremieM; Initialized := TRUE;
    ELSIF SensorPV THEN PositionEstimatedM := PosPVM; Initialized := TRUE;
    ELSIF SensorP2 THEN PositionEstimatedM := PosP2M; Initialized := TRUE;
    ELSIF SensorP1 THEN PositionEstimatedM := PosP1M; Initialized := TRUE;
    ELSIF SensorMaintenance THEN PositionEstimatedM := PosMaintenanceM; Initialized := TRUE;
    END_IF;
END_IF;

// 4. Intégration temporelle continue (Odométrie cycle par cycle)
// Les bits explicites portent le sens sémantique. Une demande contradictoire est
// neutralisée : aucun déplacement estimé ne doit être inventé.
IF DriveActualFreqHz > 0.1 THEN
    IF ReqTremie AND NOT ReqMaintenance THEN
        PositionEstimatedM := PositionEstimatedM - (DriveActualFreqHz * GainMetersPerHzSec * CycleTimeCalc.CycleTimeS);
    ELSIF ReqMaintenance AND NOT ReqTremie THEN
        PositionEstimatedM := PositionEstimatedM + (DriveActualFreqHz * GainMetersPerHzSec * CycleTimeCalc.CycleTimeS);
    END_IF;
END_IF;
{endregion}

{region "§4 Bornage"}
// Bornage de sécurité pour éviter la dérive infinie hors rail
// Convention 0 m=Trémie, 30 m=Maintenance : bornage [Trémie-0.5, Maintenance+0.5].
PositionEstimatedM := LIMIT(PosTremieM - 0.5, PositionEstimatedM, PosMaintenanceM + 0.5);
{endregion}

// === §1 GATE NEUTRALISATION ===
IF NOT Enable THEN
    Ready := FALSE;
    MotorTorque_Nm := 0.0;
    Slip_Ratio := 0.0;
    SpeedAct_Rpm := 0.0;
    IsStalled := FALSE;
    IsGeneratorMode := FALSE;
    SpeedRel_RadPerS := 0.0;
    RETURN;
END_IF;

StepCmdSafe := LIMIT(1, StepCmd, CST_StepCount);
IF StepCmdSafe <> StepCmd THEN
    Ready := FALSE;
    RETURN;
END_IF;
IF (DirectionCmd <> 1) AND (DirectionCmd <> -1) THEN
    Ready := FALSE;
    RETURN;
END_IF;

// Bornage systematique des entrees de config sensibles (denominateurs) -- CODE_QUALITY_STANDARDS §6
InertiaSafe_KgM2 := MAX(CST_MinDenominator, Inertia_KgM2);
RotorResistanceOwnSafe_Ohm := MAX(CST_MinDenominator, RotorResistanceOwn_Ohm);
SlipAtMaxTorqueBaseSafe_Ratio := MAX(CST_MinDenominator, SlipAtMaxTorqueBase_Ratio);
NetworkVoltageNomSafe_V := MAX(1.0, NetworkVoltageNom_V);

// === §2 GLISSEMENT ET COUPLE (FORMULE DE KLOSS) ===
SynchronousSpeed_RadPerS := SynchronousSpeed_Rpm * 2.0 * 3.14159265 / 60.0;

// gmax(palier) = gmax_base * R2_total(palier) / R2_rotor_propre -- ajouter de la resistance
// externe deplace le glissement au couple max vers 1 (couple demarrage), sans changer Cmax.
// gmax_base = gmax au palier rotor court-circuite (resistance externe nulle).
SlipAtMaxTorqueStep_Ratio := SlipAtMaxTorqueBaseSafe_Ratio
    * (RotorResistanceOwnSafe_Ohm + CST_RotorExtResistanceStep_Ohm[StepCmdSafe])
    / RotorResistanceOwnSafe_Ohm;

// Glissement en repere de commande (N_rel) : peut etre negatif (survitesse -> freinage
// generateur). SpeedRel_RadPerS reste dans ce repere ; SpeedAct_Rpm restitue le signe physique.
Slip_Ratio := 1.0 - SpeedRel_RadPerS / SynchronousSpeed_RadPerS;

IF ABS(Slip_Ratio) < CST_MinSlip_Ratio THEN
    IF Slip_Ratio >= 0.0 THEN
        SlipEff_Ratio := CST_MinSlip_Ratio;
    ELSE
        SlipEff_Ratio := -CST_MinSlip_Ratio;
    END_IF;
ELSE
    SlipEff_Ratio := Slip_Ratio;
END_IF;

VoltageRatio2 := (NetworkVoltageAct_V / NetworkVoltageNomSafe_V) * (NetworkVoltageAct_V / NetworkVoltageNomSafe_V);

KlossRunning(
    Enable := TRUE,
    MaxTorque_Nm := MaxTorque_Nm,
    Slip_Ratio := SlipEff_Ratio,
    SlipAtMaxTorque_Ratio := SlipAtMaxTorqueStep_Ratio,
    VoltageRatio2 := VoltageRatio2);
MotorTorque_Nm := KlossRunning.Torque_Nm;

// === §3 DYNAMIQUE MECANIQUE ===
// Pas de saturation basse : SpeedRel_RadPerS peut devenir negatif (glissement arriere sous
// surcharge) ou depasser le synchronisme (regime generateur).
SpeedRel_RadPerS := SpeedRel_RadPerS
    + (MotorTorque_Nm - ResistiveTorque_Nm) / InertiaSafe_KgM2 * CycleTime_S;

SpeedAct_Rpm := SpeedRel_RadPerS * DirectionCmd * 60.0 / (2.0 * 3.14159265);

// === §4 DECROCHAGE PREDICTIF ===
// Au palier courant, couple disponible a glissement bloque (g=1) < couple resistant, ET
// vitesse quasi nulle -- prediction "ce palier peut-il tenir la charge depuis l'arret ?",
// pas une mesure d'arret reel.
IF ABS(SpeedAct_Rpm) < CST_StallSpeedThreshold_Rpm THEN
    KlossLockedRotor(
        Enable := TRUE,
        MaxTorque_Nm := MaxTorque_Nm,
        Slip_Ratio := 1.0,
        SlipAtMaxTorque_Ratio := SlipAtMaxTorqueStep_Ratio,
        VoltageRatio2 := VoltageRatio2);
    Stalled := KlossLockedRotor.Torque_Nm < ResistiveTorque_Nm;
    IF Stalled THEN
        IsStalled := TRUE;
    END_IF;
ELSE
    Stalled := FALSE;
END_IF;

IsGeneratorMode := MotorTorque_Nm < 0.0;

Ready := TRUE;

{region "§1 Reset (front, toujours effectif)"}
// Front Reset : efface tous les latches. Jamais conditionné, agit même Enable=FALSE (§9).
Ready := Enable;
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    FOR i := 0 TO 15 DO Latch[i] := FALSE; END_FOR;
END_IF;
{endregion}

{region "§2 Vue LIVE — Error / ErrorId"}
// Bitfield des causes présentes MAINTENANT. Retombe seule à 0 quand les causes disparaissent.
// Non évaluée si Enable=FALSE (pas de lecture de cause hors autorisation).
Fault.ErrorId := 0;
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active THEN
            Fault.ErrorId := Fault.ErrorId OR SHL(WORD#1, INT_TO_DWORD(i));
        END_IF;
    END_FOR;
END_IF;
Fault.Error := (Fault.ErrorId <> 0);
{endregion}

{region "§3 Armement des latches (causes à acquitter)"}
// Une cause Active ET Latching arme son bit ; le bit reste jusqu'au front Reset (§1),
// même si la cause disparaît. Réapparition => ré-armement (ré-alarme).
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active AND Causes[i].Latching THEN
            Latch[i] := TRUE;
        END_IF;
    END_FOR;
END_IF;
{endregion}

{region "§4 Vue LATCHÉE — Latched / LatchedId"}
// Toujours publiée, y compris Enable=FALSE : un défaut non acquitté reste visible.
Fault.LatchedId := 0;
FOR i := 0 TO 15 DO
    IF Latch[i] THEN
        Fault.LatchedId := Fault.LatchedId OR SHL(WORD#1, INT_TO_DWORD(i));
    END_IF;
END_FOR;
Fault.Latched := (Fault.LatchedId <> 0);
{endregion}

// 🛡️ 1. GATE GENERAL (D-A11, C1) — PAS de Homed : non-reference ≠ incoherent.
//    Ce gate sert a la fiabilite de la mesure (vitesse, mouvements, PositionsValid).
EncoderFault := (NOT EncoderAvailable) OR EncoderIncoherent;

// 🎯 2. GATE STRICT — reserve a l'interlock hauteur M3 (C1) : on ne translate pas
//    si la hauteur est inconnue (jamais home) ou douteuse.
HomedAndReliable := EncoderAvailable AND Homed AND (NOT EncoderIncoherent);

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Abs) ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. RESET FRONT
ResetEdge(CLK := Reset);

// 🔍 2. DIAGNOSTIC BUS / ALARME (Cause 0 : live)
instCauses[0].Active   := (AlarmsIn <> 0) OR NOT SlaveOperational;
instCauses[0].Latching := FALSE;
instCauses[0].Texte    := 'Defaut communication EtherCAT codeur absolu';

// ⏱️ 3. TIMEOUT PRESET (Cause 1 : latched)
IF ResetEdge.Q AND (PresetSeqStep = 0) THEN
    PresetTimeoutError := FALSE;
END_IF;
instCauses[1].Active   := PresetTimeoutError;
instCauses[1].Latching := TRUE;
instCauses[1].Texte    := 'Timeout sequence preset SDO codeur';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

EncoderAvailable := NOT instCauses[0].Active;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable THEN
    EncoderAvailable := FALSE;
    Ready := FALSE;
    PresetTriggerCmd := 0; CodeSeqTriggerCmd := 0; PresetValueOut := 0;
    PresetSeqStep := 0;
    PresetCompleted := FALSE;
    PresetTimer(IN := FALSE, PT := PresetTimeout);
    PresetTimerVisual(IN := FALSE, PT := T#500MS);
    // RawPos, AngleRaw et TurnCount sont volontairement gelés hors Enable
    // (AF09 F09.01 / AC5) : aucune lecture bus ni remise a zero dans ce gate.
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Lecture position"}
// 📥 3. LECTURE POSITION — GELER SUR DOUTE (Partie10 §6)
// Si EncoderAvailable=FALSE : RawPos/AngleRaw/TurnCount conservent leur dernière valeur (pas de RETURN
// global ici pour ne pas geler aussi la séquence preset/l'état — seule la lecture est gelée).
IF EncoderAvailable THEN
    RawPos := RawPosIn;   // Sens de comptage géré côté codeur (CoE 6000h bit0, startup parameter CODESYS) — voir Partie10 §3bis. Plus de calcul ici.
    AngleRaw := UDINT_TO_UINT(RawPos MOD PointsPerRev);
    TurnCount := RawPos / PointsPerRev;
END_IF;
{endregion}

{region "§4 Séquence preset"}
// 🔧 4. SÉQUENCE PRESET (écriture bus)
// PresetTriggerCmd := 2 déclenche le référencement à PresetValue (valeur de commande, pas un
// masque de bits). CodeSeqTriggerCmd : rôle non identifié — laissé à 0, PAS piloté tant que sa
// fonction n'est pas confirmée. Ne jamais lui donner une valeur arbitraire.
PresetReqEdge(CLK := PresetRequest);
PresetCompleted := FALSE;
CodeSeqTriggerCmd := 0;                 // non piloté — rôle inconnu, voir note ci-dessus
CASE PresetSeqStep OF
    0: // IDLE
        PresetTriggerCmd := 0;
        IF PresetReqEdge.Q AND EncoderAvailable THEN
            PresetValueOut := PresetValue;
            PresetSeqStep := 1;
            PresetTimer(IN := TRUE, PT := PresetTimeout);
        END_IF;
    1: // Déclenchement preset (laissé actif pendant 0.5s pour confort visuel en simulation/bus)
        PresetTriggerCmd := 2;   // Référence le codeur à PresetValueOut
        RawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(PresetValueOut);
        IF ABS(RawDiff) <= UDINT_TO_DINT(PresetTolerancePts) THEN
            PresetTimer(IN := FALSE, PT := PresetTimeout);
            PresetTimerVisual(IN := TRUE, PT := T#500MS);
            IF PresetTimerVisual.Q THEN
                PresetTriggerCmd := 0;
                PresetCompleted := TRUE;
                PresetSeqStep := 0;
                PresetTimerVisual(IN := FALSE, PT := T#500MS);
            END_IF;
        ELSIF PresetTimer.Q THEN
            PresetTriggerCmd := 0;
            PresetTimeoutError := TRUE;
            PresetSeqStep := 0;
            PresetTimer(IN := FALSE, PT := PresetTimeout);
            PresetTimerVisual(IN := FALSE, PT := T#500MS);
        END_IF;
END_CASE;
{endregion}

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Homing) ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. FRONTS
ResetEdge(CLK := Reset);
HomeEdge(CLK := Home);
ConfirmCoherenceEdge(CLK := BtnConfirmCoherence);

// Effacement des latches d'erreur sur Reset conscient
IF ResetEdge.Q THEN
    PresetConfirmationFailed := FALSE;
    HomingModeError := FALSE;
    TargetOutOfRangeError := FALSE;
    PresetFailError := FALSE;
END_IF;

// Levée de doute incohérence boot (BtnConfirmCoherence)
IF ConfirmCoherenceEdge.Q AND HomingPermit THEN
    Calib.HomingSuspect := FALSE;
    BootIncoherentError := FALSE;
END_IF;

// Configuration des causes nommées
instCauses[0].Active   := HomingModeError;
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Homing non autorise dans ce mode';

instCauses[1].Active   := TargetOutOfRangeError;
instCauses[1].Latching := TRUE;
instCauses[1].Texte    := 'Cible de homing hors plage';

instCauses[2].Active   := PresetFailError;
instCauses[2].Latching := TRUE;
instCauses[2].Texte    := 'Echec confirmation transaction preset';

instCauses[3].Active   := BootIncoherentError;
instCauses[3].Latching := TRUE;
instCauses[3].Texte    := 'Incoherence position codeur au demarrage';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE — neutralisation ; on continue toutefois d'exposer le dernier état RETAIN connu
// (FB_Encoder_Scale a besoin de HomingRefRaw même si ce FB est désactivé)
IF NOT Enable THEN
    PresetRequest := FALSE;
    PresetValue := 0;
    Ready := FALSE;
    Lifecycle.Busy := FALSE;
    Lifecycle.Done := FALSE;
    InitDone := FALSE;   // Force un nouveau contrôle à la prochaine activation
    PresetVerificationActive := FALSE;
    PresetVerifyTimer(IN := FALSE, PT := CST_PresetVerifyTime);
    Homed := Calib.Homed;
    HomingSuspect := Calib.HomingSuspect;
    HomingRefRaw := Calib.HomingRefRaw;
    // PresetConfirmationFailed est un diagnostic latch : il est gelé hors Enable
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Cohérence au redémarrage"}
// 🔍 3. COHÉRENCE AU REDÉMARRAGE — une fois par session Enable, dès que le codeur répond
IF NOT InitDone THEN
    IF EncoderAvailable THEN
        RawDiffRestart := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(Calib.LastKnownRawPos);
        IF Calib.Homed AND (ABS(RawDiffRestart) > UDINT_TO_DINT(Calib.RestartCoherenceTolerancePts)) THEN
            Calib.HomingSuspect := TRUE;
            BootIncoherentError := TRUE;
        END_IF;
        InitDone := TRUE;
    END_IF;
END_IF;
{endregion}

{region "§4 Demande et déclenchement homing"}
// ⚙️ 4. DEMANDE & DÉCLENCHEMENT HOMING
PresetRequest := FALSE;
PresetValue := 0;
TopSensorEdge(CLK := TopPositionSensor);
DynamicTargetEdge(CLK := UseDynamicTarget);

HomingModeOk := HomingPermit;

IF HomeEdge.Q AND NOT HomingModeOk THEN
    HomingModeError := TRUE;
END_IF;

NominalHomingTrigger := HomingModeOk AND NOT UseDynamicTarget
                         AND ((Home AND TopSensorEdge.Q) OR (HomeEdge.Q AND TopPositionSensor));

UnitaryHomingTrigger := HomingModeOk AND NOT UseDynamicTarget AND HomeEdge.Q;

DynamicHomingTrigger := HomingModeOk AND (DynamicTargetEdge.Q OR (UseDynamicTarget AND HomeEdge.Q));

HomingTrigger := (NominalHomingTrigger OR UnitaryHomingTrigger OR DynamicHomingTrigger)
                 AND NOT PresetVerificationActive;

IF HomingTrigger THEN
    IF UseDynamicTarget THEN
        TargetPositionM := DynamicHomingTargetM;
    ELSIF NominalHomingTrigger THEN
        TargetPositionM := CfgTopSensorPosM;
    ELSE
        TargetPositionM := CfgHomingTargetM;
    END_IF;

    // Bornage obligatoire avant écriture (CODE_QUALITY_STANDARDS §6) [-99;+99] m
    IF (TargetPositionM < -99.0) OR (TargetPositionM > 99.0) THEN
        TargetOutOfRangeError := TRUE;
    ELSE
        TargetPoints := REAL_TO_DINT(TargetPositionM * UDINT_TO_REAL(PointsPerRev) / CableM_PerRev);
        PendingHomingRefRaw := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) - TargetPoints);
        PresetValue := RawPos;
        PresetRequest := TRUE;
        PresetVerificationActive := TRUE;
        Lifecycle.Done := FALSE;
    END_IF;
END_IF;
{endregion}

{region "§5 Suivi de transaction preset"}
// ⏳ 5. SUIVI DE LA TRANSACTION PRESET
PresetVerifyTimer(IN := PresetVerificationActive, PT := CST_PresetVerifyTime);
IF PresetVerificationActive AND PresetVerifyTimer.Q THEN
    CandidateRawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(PendingHomingRefRaw);
    IF PointsPerRev <> 0 THEN
        CandidateCablePosM := DINT_TO_REAL(CandidateRawDiff) * CableM_PerRev / UDINT_TO_REAL(PointsPerRev);
    ELSE
        CandidateCablePosM := 0.0;
    END_IF;
    ReadbackOk := ABS(CandidateCablePosM - TargetPositionM) <= CST_HomingVerifyToleranceM;
    StatusBitOk := PresetStatusBit;

    CASE Cfg.PresetConfirmMode OF
        E_PresetConfirmMode.READBACK_ONLY:
            PresetConfirmed := ReadbackOk;
        E_PresetConfirmMode.READBACK_AND_STATUSBIT:
            PresetConfirmed := ReadbackOk AND StatusBitOk;
        E_PresetConfirmMode.STATUSBIT_ONLY:
            PresetConfirmed := StatusBitOk;
        ELSE
            PresetConfirmed := FALSE;
    END_CASE;

    IF PresetConfirmed THEN
        Calib.HomingRefRaw := PendingHomingRefRaw;
        Calib.Homed := TRUE;
        Calib.HomingSuspect := FALSE;
        Calib.LastKnownRawPos := RawPos;
        PresetConfirmationFailed := FALSE;
        PresetFailError := FALSE;
        Lifecycle.Done := TRUE;
    ELSE
        Calib.HomingSuspect := TRUE;
        PresetConfirmationFailed := TRUE;
        PresetFailError := TRUE;
        Lifecycle.Done := FALSE;
    END_IF;

    PresetVerificationActive := FALSE;
    PresetVerifyTimer(IN := FALSE, PT := CST_PresetVerifyTime);
END_IF;
{endregion}

{region "§6 Sorties état & calibration"}
// 📤 6. SORTIES ÉTAT & CALIBRATION
IF EncoderAvailable AND NOT PresetVerificationActive THEN
    Calib.LastKnownRawPos := RawPos;
END_IF;

Lifecycle.Busy := PresetVerificationActive;
Homed := Calib.Homed AND NOT Calib.HomingSuspect;
HomingSuspect := Calib.HomingSuspect;
HomingRefRaw := Calib.HomingRefRaw;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. RESET FRONT
ResetEdge(CLK := Reset);

// 🔍 2. SURVEILLANCE BORNAGE & INCOHÉRENCE BOOT
instCauses[0].Active   := NOT BypassGlobal AND ((CablePosM < PositionMinM) OR (CablePosM > PositionMaxM));
instCauses[0].Latching := FALSE;
instCauses[0].Texte    := 'Depassement bornes physiques absolues cable';

instCauses[1].Active   := NOT BypassGlobal AND HomingSuspect;
instCauses[1].Latching := FALSE;
instCauses[1].Texte    := 'Incoherence position au redemarrage';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable THEN
    Ready := FALSE;
    CablePosMSafe := CablePosM;
    EncoderIncoherent := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Transmission mesure et sécurité"}
// 📏 3. TRANSMISSION DE LA MESURE & SÉCURITÉ
CablePosMSafe := CablePosM;
EncoderIncoherent := Fault.Error;
{endregion}

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Scale) ===

// 🧮 Écart signé sûr : conversion DINT AVANT soustraction (§3.1) — jamais l'inverse
RawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(HomingRefRaw);

// 📏 Formule fixe points → mètres (Partie10 §2), garde division par zéro
IF PointsPerRev > 0 THEN
    CablePosM := DINT_TO_REAL(RawDiff) * (CableM_PerRev / UDINT_TO_REAL(PointsPerRev));
ELSE
    CablePosM := 0.0;
END_IF;

{region "§1 Gate de neutralisation & Reset"}
ResetEdge(CLK := Reset);

// Purge immediate sur perte de confiance, desactivation ou Reset
IF NOT Enable OR ResetEdge.Q OR NOT PositionValid THEN
    Speed_Mps       := 0.0;
    SignedSpeed_Mps := 0.0;
    Valid           := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Conversion directe vitesse CoE (0.1 RPM -> m/s)"}
// Formule cinematique directe :
// N_RPM = SpdValueIn * 0.1
// V_mps = (N_RPM * CableM_PerRev) / 60.0 = (DINT_TO_REAL(SpdValueIn) * 0.1 * CableM_PerRev) / 60.0
SignedSpeed_Mps := (DINT_TO_REAL(SpdValueIn) * 0.1 * CableM_PerRev) / 60.0;
Speed_Mps       := ABS(SignedSpeed_Mps);
Valid           := TRUE;
{endregion}

IF RawIn >= Neutral THEN
    Delta := INT_TO_REAL(10000 - Neutral);
    IF Delta > 0.0 THEN
        OutPct := (INT_TO_REAL(RawIn - Neutral) / Delta) * 100.0;
    ELSE
        OutPct := 0.0;
    END_IF;
ELSE
    Delta := INT_TO_REAL(Neutral);
    IF Delta > 0.0 THEN
        OutPct := (INT_TO_REAL(RawIn - Neutral) / Delta) * 100.0;
    ELSE
        OutPct := 0.0;
    END_IF;
END_IF;

IF ABS(RawIn - Neutral) <= DeadbandRaw THEN
    OutPct := 0.0;
END_IF;

// 🛡️ Limitation de plage : une valeur brute hors plage nominale ne doit jamais
// produire une consigne supérieure à ±100 %. Ce garde-fou protège les
// consommateurs en aval, notamment la translation M3.
OutPct := LIMIT(-100.0, OutPct, 100.0);

// === IMPLEMENTATION ===

{region "§1 Fronts"}
// 🔑 1. FRONTS
ResetEdge(CLK := Reset);
BypassEdge(CLK := BypassContactorCheck);

// Acquittement des drapeaux contacteur
IF ResetEdge.Q OR BypassContactorCheck THEN
    ContactorIncoherentError := FALSE;
    ContactorCheck.StuckClosed := FALSE;
    ContactorCheck.StuckOpen   := FALSE;
END_IF;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE — pas d'Enable = frein collé (sécurité positive), aucune temporisation en cours
IF NOT Enable THEN
    TonMagnetise(IN := FALSE, PT := DelayMagnetise + DelayContactClose);
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    TonFeedback(IN := FALSE, PT := FeedbackTimeout);
    BrakeCmd := FALSE;
    Ready := FALSE;
    ContactorCheck.Command := FALSE;          // 📊 Neutralisation : miroir de BrakeCmd := FALSE
    ContactorCheck.Feedback := ContactorFeedback; // 📊 Neutralisation : miroir entrée physique
    BrakeCommandOpenConfirmed := FALSE;       // 🛡️ Fail-Safe : frein commandé fermé hors Enable

    // Évaluation du socle de défaut sous neutralisation (permet acquittement Reset hors Enable)
    instCauses[0].Active   := FALSE;
    instCauses[0].Latching := TRUE;
    instCauses[0].Texte    := 'Incoherence retour contacteur frein';
    instFault(Enable := FALSE, Reset := Reset, Causes := instCauses);
    Fault := instFault.Fault;
    RETURN;
END_IF;
{endregion}

{region "§3 Séquence temporisée"}
// 🛠️ 3. SÉQUENCE TEMPORISÉE (démarrage vs arrêt)
IF MovementRequested THEN
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    TonMagnetise(IN := TRUE, PT := DelayMagnetise + DelayContactClose);
    IF TonMagnetise.Q THEN
        BrakeCmd := TRUE;              // ✅ Contacteur + magnétisation acquis → relâche
    ELSE
        BrakeCmd := FALSE;             // ⏳ Encore collé pendant la magnétisation
    END_IF;
ELSE
    // Sécurité positive : fermeture immédiate du frein (collé) dès que les contacteurs de sens s'ouvrent
    TonMagnetise(IN := FALSE, PT := DelayMagnetise + DelayContactClose);
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    BrakeCmd := FALSE;                 // Fermeture immédiate
END_IF;
{endregion}

{region "§4 Double vérification contacteur"}
// 🔍 4. DOUBLE VÉRIFICATION RETOUR CONTACTEUR (ST_ContactorCheck)
ContactorCheck.Command := BrakeCmd;
ContactorCheck.Feedback := ContactorFeedback;

// ContactorFeedback est dans le MÊME sens que BrakeCmd (TRUE = relâché = frein ouvert).
TonFeedback(IN := (BrakeCmd <> ContactorFeedback), PT := FeedbackTimeout);
IF NOT BypassContactorCheck THEN
    IF TonFeedback.Q THEN
        ContactorCheck.StuckClosed := (BrakeCmd AND NOT ContactorFeedback);
        ContactorCheck.StuckOpen   := (NOT BrakeCmd AND ContactorFeedback);
        ContactorIncoherentError   := TRUE;
    END_IF;
END_IF;
{endregion}

{region "§5 Causes & Socle Défaut"}
// 🚨 5. SOCLE DÉFAUT & SORTIE SÛRE
instCauses[0].Active   := NOT BypassContactorCheck AND (ContactorCheck.StuckClosed OR ContactorCheck.StuckOpen OR (TonFeedback.Q AND (BrakeCmd <> ContactorFeedback)));
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Incoherence retour contacteur frein';

instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

Ready := Enable AND NOT Fault.Latched;

// Sortie sûre immédiate
IF Fault.Error OR Fault.Latched THEN
    BrakeCmd := FALSE;
END_IF;
{endregion}

{region "§6 Confirmation ouverture"}
// 📤 6. CONFIRMATION OUVERTURE FREIN
IF BypassContactorCheck THEN
    BrakeCommandOpenConfirmed := BrakeCmd;
ELSE
    BrakeCommandOpenConfirmed := ContactorFeedback AND NOT Fault.Latched;  (* TRUE = frein ouvert = desserrage confirmé *)
END_IF;
{endregion}

// Détection du comportement (Accélération vs Décélération)
// Classification par CÔTÉ DE ZÉRO + sens de déplacement, plus par signe brut de Target seul
// (robuste à une traversée de zéro rapide).
// 🛡️ Garde-fou : la rampe ne sort jamais de la plage normalisée ±100 %.
TargetLimited := LIMIT(-100.0, Target, 100.0);
Current := LIMIT(-100.0, Current, 100.0);

IF (Current >= 0.0 AND TargetLimited >= Current) OR (Current <= 0.0 AND TargetLimited <= Current) THEN
    StepX := AccelRate * CycleTimeS; // S'éloigne du zéro (reste du même côté, va plus loin)
ELSE
    StepX := DecelRate * CycleTimeS; // Retourne vers zéro, ou le traverse vers l'autre signe
END_IF;

// Application de la rampe
IF Current < TargetLimited THEN
    Current := Current + StepX;
    IF Current > TargetLimited THEN Current := TargetLimited; END_IF;
ELSIF Current > TargetLimited THEN
    Current := Current - StepX;
    IF Current < TargetLimited THEN Current := TargetLimited; END_IF;
END_IF;

// 🛡️ Limitation finale : même une valeur d'état déjà corrompue reste bornée.
Current := LIMIT(-100.0, Current, 100.0);

IF NOT Enable THEN
    Ready := FALSE;
    Torque_Nm := 0.0;
    RETURN;
END_IF;

Torque_Nm := 2.0 * MaxTorque_Nm
    / (Slip_Ratio / SlipAtMaxTorque_Ratio + SlipAtMaxTorque_Ratio / Slip_Ratio)
    * VoltageRatio2;

Ready := TRUE;

documentation.xhtml:
🧪 Contrôle granulaire de la chaîne AU : TRUE = simuler la chaîne fermée (on peut armer) ;
FALSE = chaîne ouverte (on ne peut pas armer). Défaut FALSE → à la ré-entrée en simu,
la chaîne est ouverte et le contacteur non engagé (on n'a pas armé).
